// BOS-240: boss-build must finalize BLOCKED (not REVIEW_READY) when it defers a *required*
// item at the wall-clock cap. These assertions pin the honest-finalize invariant into the
// shipped Claude and Codex artifacts so the terminal-state logic can't silently regress. They
// read the committed generated files (no source skip) so CI enforces them with no extra setup.
const RESIDENT_BODIES = {
  canonical: `${CORE}/SKILL.md`,
}
const readSkill = (rel) => fs.readFileSync(path.join(rootDir, rel), 'utf8')
const readRef = (mirror, ref) =>
  fs.readFileSync(
    path.join(rootDir, path.dirname(RESIDENT_BODIES[mirror]), 'references', ref),
    'utf8',
  )

test('BOS-240: resident body pins the required-deferred → BLOCKED finalize invariant (both mirrors)', () => {
  for (const [mirror, rel] of Object.entries(RESIDENT_BODIES)) {
    const body = readSkill(rel)
    // The distinction + invariant is stated in the always-resident body.
    assert.match(
      body,
      /Required-deferred/,
      `${mirror}: body must define the required-deferred distinction`,
    )
    assert.match(
      body,
      /BLOCKED, never\s+REVIEW_READY/,
      `${mirror}: body must state required-deferred ⇒ BLOCKED, never REVIEW_READY`,
    )
    // Required = API-version bump for an observable bossanova.v1 change + open must-fix findings.
    assert.match(body, /API-version\s+bump/, `${mirror}: required must name the API-version bump`)
    assert.match(
      body,
      /must-fix\s+findings/,
      `${mirror}: required must name open must-fix findings`,
    )
    assert.match(
      body,
      /bossanova\.v1/,
      `${mirror}: required item is an observable bossanova.v1 change`,
    )
    // Optional stays non-fatal (Minor findings + best-effort proof).
    assert.match(
      body,
      /_?optional_?[^\n]*Minor\s+findings[^\n]*best-effort\s+proof[^\n]*non-fatal/i,
      `${mirror}: optional (Minor findings + best-effort proof) must stay non-fatal`,
    )
    // The wall-clock breaker no longer grants "usually BLOCKED" latitude.
    assert.doesNotMatch(
      body,
      /usually\s+BLOCKED/,
      `${mirror}: wall-clock breaker must not permit REVIEW_READY with an unaddressed required item`,
    )
    // BOS-674: Steps 9 and 12 moved to references/finalize-and-stop.md, but the invariant is
    // load-bearing enough that the resident pointer block must restate it — a reader who never
    // opens the reference still learns that readying and REVIEW_READY are gated on it.
    const pointers = region(body, '## Steps 8-12:', '## Cron gate')
    assert.match(
      pointers,
      /no\s+required\s+item\s+was\s+deferred/,
      `${mirror}: the resident Steps 8-12 pointer block must keep the Step 9 deferral gate`,
    )
    assert.match(
      pointers,
      /REVIEW_READY\s+only\s+with\s+no\s+deferred\s+required\s+item/,
      `${mirror}: the resident Steps 8-12 pointer block must keep the Step 12 terminal-state gate`,
    )

    // Enforced at the finalize gate (Step 9) and terminal-state selection (Step 12).
    const ref = finalizeAndStop(path.dirname(rel))
    const step9 = region(ref, '## Step 9:', '## Step 10:')
    assert.match(
      step9,
      /no\s+required\s+item\s+was\s+deferred/,
      `${mirror}: Step 9 must assert no required item was deferred before readying`,
    )
    const step12 = region(ref, '## Step 12:')
    assert.match(
      step12,
      /REVIEW_READY\s+only\s+with\s+no\s+deferred\s+required\s+item/,
      `${mirror}: Step 12 must pick REVIEW_READY only with no deferred required item`,
    )
  }
})

// BOS-841: the ABORT list overreached. `a plan with unresolved decisions` sat in the same
// compound bullet as `empty/contradictory acceptance criteria`, so ordinary plan ambiguity —
// exactly what the section's own opening sentence calls "decide and record" — ended the run
// BLOCKED. These assertions pin the split, and they are section-sliced rather than whole-file
// matched because the moved phrase still appears in the file: a whole-file `doesNotMatch` on
// `unresolved decisions` would be false by construction, and a whole-file `match` would pass
// while the phrase sat in the wrong list.
test('BOS-841: Decide vs ABORT separates genuinely-unsafe from decide-and-record (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const body = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')
    const section = region(body, '## Decide vs ABORT', '## Mode detection', `${dir}/SKILL.md`)

    // A.1 — slice the ABORT list itself, and assert every bullet over THAT slice rather than over
    // the section. The section now spans both groups, so a section-wide match cannot tell a bullet
    // that was DELETED from one that was RELOCATED into the decide-and-record group — and silent
    // relocation is this file's documented failure mode, the very thing this ticket is performing.
    // Every assertion below therefore reads `abortList`, never `section`.
    const abortList = region(
      section,
      'must **ABORT to BLOCKED**',
      'On any of these:',
      `${dir}/SKILL.md Decide vs ABORT`,
    )

    // The genuinely-unsafe conditions, one assertion each, so a deletion names itself.
    assert.match(
      abortList,
      /destructive\s+or\s+data\s+migrations; schema\s+drops\/rewrites/,
      `${dir}/SKILL.md: the hard-ABORT list must still name destructive/data migrations and schema drops/rewrites`,
    )
    assert.match(
      abortList,
      /auth, secrets, credential, or\s+keyring\s+changes/,
      `${dir}/SKILL.md: the hard-ABORT list must still name auth/secrets/credential/keyring changes`,
    )
    assert.match(
      abortList,
      /production\s+config\s+or\s+deploy\s+changes/,
      `${dir}/SKILL.md: the hard-ABORT list must still name production config or deploy changes`,
    )
    assert.match(
      abortList,
      /dependency\s+upgrades\/additions\s+not\s+already\s+specified\s+by\s+the\s+plan/,
      `${dir}/SKILL.md: the hard-ABORT list must still name unspecified dependency upgrades/additions`,
    )
    assert.match(
      abortList,
      /anything\s+the\s+Trust\s+rules\s+name/,
      `${dir}/SKILL.md: the hard-ABORT list must still defer to the Trust rules`,
    )

    // A.2 — the acceptance-criteria half stays a hard ABORT; only the decisions half moved.
    assert.match(
      abortList,
      /empty\/contradictory\s+acceptance\s+criteria/,
      `${dir}/SKILL.md: the hard-ABORT list must still name empty/contradictory acceptance criteria`,
    )
    assert.match(
      abortList,
      /AC\s+requiring\s+production\s+access\s+or\s+deployed-environment\s+audit\s+from\s+a\s+worktree/,
      `${dir}/SKILL.md: the hard-ABORT list must name production-only or deployed-audit ACs`,
    )

    // The list is exactly seven bullets. Seven named conditions all present is not the same claim as
    // seven conditions TOTAL: without a count, an eighth unsafe condition could be appended — or a
    // moved bullet re-added alongside its replacement — with every assertion above still green.
    // Match indented bullets too: a nested `  - …` appended under a bullet adds a seventh
    // condition a top-level-only pattern never counts, so the exactness claim would go green on
    // precisely the edit it exists to catch.
    const abortBullets = abortList.match(/^\s*- .+$/gm) ?? []
    assert.strictEqual(
      abortBullets.length,
      7,
      `${dir}/SKILL.md: the hard-ABORT list must carry exactly seven bullets, found ${abortBullets.length}: ${JSON.stringify(abortBullets)}`,
    )

    // A.3 — the moved condition must be gone from the ABORT list. The section as a whole names
    // `unresolved decisions` in the decide-and-record group, so this exclusion is only meaningful
    // over the ABORT bullets.
    assert.doesNotMatch(
      abortList,
      /unresolved\s+decisions/,
      `${dir}/SKILL.md: a plan with unresolved decisions must not remain in the hard-ABORT list`,
    )

    // A.4 — two open lists let a run facing a novel condition honestly read either one. The
    // ABORT list has to declare itself closed for the decide-and-record default to have force.
    // Match the CLAIM, not the word: a bare /exhaustive/ is satisfied by `not exhaustive` — the
    // exact inversion of the property being pinned — and by any incidental later use of the word.
    // The sentence hard-wraps as `— this list\nis exhaustive:`, so span the wrap with \s+.
    assert.match(
      abortList,
      /this\s+list\s+is\s+exhaustive/,
      `${dir}/SKILL.md: Decide vs ABORT must declare the hard-ABORT list exhaustive`,
    )

    // A.5 — the decide-and-record group, sliced, must carry the moved condition AND a recording
    // home. "Decide" without "record where" is the inert half of this change.
    // This group runs to the END of the section, and inventing an end marker would pin a boundary
    // this assertion does not care about and fail on an ordinary edit after the group. BOS-737:
    // that used to force a hand-rolled `indexOf` + `!== -1` guard, because the local helper
    // required an end marker; `region()` takes a null end marker meaning "to the end of source",
    // so the guard is the helper's own throw now, and the label still names the mirror.
    const recordGroup = region(
      section,
      '**Decide and record, never abort**',
      null,
      `${dir}/SKILL.md: Decide vs ABORT`,
    )
    assert.match(
      recordGroup,
      /a\s+plan\s+with\s+unresolved\s+decisions/,
      `${dir}/SKILL.md: the decide-and-record group must name a plan with unresolved decisions`,
    )
    assert.match(
      recordGroup,
      /rationale/,
      `${dir}/SKILL.md: the decide-and-record group must require the decision's rationale, not just the decision`,
    )
    assert.match(
      recordGroup,
      /`## Autonomous\s+decisions`/,
      `${dir}/SKILL.md: the decide-and-record group must name \`## Autonomous decisions\` as the recording home`,
    )
    assert.match(
      recordGroup,
      /continue/,
      `${dir}/SKILL.md: the decide-and-record group must say the run continues`,
    )

    // A.6 — the anti-relocation pin. This split must NOT take the acceptance-criteria half of
    // the required-deferred rule with it: until a PARTIAL terminal state exists there are only
    // two landing states, so an unsatisfied criterion freed from BLOCKED falls through to
    // REVIEW_READY — strictly worse than aborting. The sibling ticket owns moving this; when it
    // does, this assertion is the one it must deliberately update.
    const hardRules = region(body, '## Hard rules', '## Trust rules', `${dir}/SKILL.md`)
    assert.match(
      hardRules,
      /any\s+in-scope\s+acceptance\s+criterion\s+left\s+unsatisfied/,
      `${dir}/SKILL.md: the Hard-rules required-deferred bullet must keep the acceptance-criterion clause`,
    )
    assert.match(
      hardRules,
      /partial\s+implementation\s+is\s+not\s+complete/,
      `${dir}/SKILL.md: the Hard-rules required-deferred bullet must keep "partial implementation is not complete"`,
    )

    // A.7 — the referring phrase, everywhere else in the body. `## Decide vs ABORT` now names TWO
    // lists and one of them is explicitly never an abort, so "a Decide-vs-ABORT condition" stopped
    // denoting anything determinate the moment the split landed. That phrase carried the
    // stop-and-report instruction handed verbatim to dispatched subagents — in text they read in
    // isolation from this section — and a *reported* condition is routed straight to BLOCKED
    // without re-checking which list it came from. Left alone it reinstates the exact defect this
    // ticket removes, one dispatch deeper. Every stop-and-report instruction must name the
    // hard-ABORT list instead. Normalize whitespace before the negative match, exactly as the
    // reference and extension scans below do: the body hard-wraps and nothing enforces its wrap
    // width (the skillinstall tree sits outside the `lint:docs` glob, and `.prettierrc` keeps
    // `proseWrap: "preserve"`), so a raw-text `doesNotMatch` goes quietly green on a re-wrap that
    // splits `Decide-vs-ABORT` from `condition` — i.e. precisely when the stale phrase is still
    // being read by the subagent this assertion protects.
    assert.doesNotMatch(
      body.replace(/\s+/g, ' '),
      /Decide-vs-ABORT\s+condition/,
      `${dir}/SKILL.md: stop-and-report instructions must name a hard-ABORT condition, not the two-list section`,
    )
    // The references are read by the same dispatched subagents, and `core-spine.md` restates the
    // very step whose brief carries the instruction — so a reference is a live route back to the
    // ambiguous phrase that the body-only exclusion above would never see.
    const refDir = path.join(rootDir, dir, 'references')
    for (const ref of fs.readdirSync(refDir).filter((f) => f.endsWith('.md'))) {
      const flat = fs.readFileSync(path.join(refDir, ref), 'utf8').replace(/\s+/g, ' ')
      assert.doesNotMatch(
        flat,
        /Decide-vs-ABORT\s+condition/,
        `${dir}/references/${ref}: stop-and-report instructions must name a hard-ABORT condition, not the two-list section`,
      )
    }
    assert.match(
      region(
        body,
        'Return only the fixed short task-contract:',
        '## Step 6: Whole-branch review',
        `${dir}/SKILL.md`,
      ),
      /If\s+a\s+hard-ABORT\s+condition\s+appears,\s+stop\s+and\s+report\s+it/,
      `${dir}/SKILL.md: the tier-3 dispatch brief must tell the subagent to report hard-ABORT conditions`,
    )
  }
})

// BOS-841: the core is not the last reader of either half of this change. Tier 1 dispatches the
// repo-local methodology extension, and a subagent under it reads its stop-and-report instruction
// and its return schema from THAT file, in isolation from the core's `## Decide vs ABORT` section.
// So both halves have to reach it: the ambiguous referring phrase must be gone (the core routes a
// *reported* condition straight to BLOCKED without re-checking which list it came from, so leaving
// it reinstates the ticket's headline defect one dispatch deeper), and the closed return object
// must name the decisions element (a field the schema omits is a field a subagent is told not to
// return, which makes `## Autonomous decisions` unreachable from the tier that actually runs here).
// The count is per-file and exact: `boss-build-ce` states the instruction twice (the ce-work
// boundary bullet and the Contract section), `boss-build-knowledge` once. A bare token match would
// stay green when one of the two ce instructions is deleted outright, so pin how many there are.
const DISPATCHED_EXTENSION_DIRS = [
  ...METHODOLOGY_EXTENSION_DIRS.map((skillDir) => ({ skillDir, instructions: 2 })),
  ...KNOWLEDGE_EXTENSION_DIRS.map((skillDir) => ({ skillDir, instructions: 1 })),
]

test('BOS-841: dispatched extensions name the hard-ABORT list, not the two-list section', () => {
  for (const { skillDir, instructions: expected } of DISPATCHED_EXTENSION_DIRS) {
    // These files are hand-wrapped, so the phrase can straddle a newline. Normalize BEFORE the
    // negative match too: a raw-text `doesNotMatch` would go quietly green on a re-wrap that split
    // `Decide-vs-ABORT` from `condition`, i.e. exactly when the stale phrase is still being read.
    const flat = fs.readFileSync(path.join(skillDir, 'SKILL.md'), 'utf8').replace(/\s+/g, ' ')
    assert.doesNotMatch(
      flat,
      /Decide-vs-ABORT\s+condition/,
      `${skillDir}/SKILL.md: a dispatched brief must tell the subagent to report a hard-ABORT condition, not the two-list section`,
    )
    const instructions =
      flat.match(/hard-ABORT\s+condition (instead\s+of|rather\s+than) guessing/g) ?? []
    assert.strictEqual(
      instructions.length,
      expected,
      `${skillDir}/SKILL.md must carry ${expected} stop-and-report instruction(s) naming the hard-ABORT list, found ${instructions.length}`,
    )
  }
})

test('BOS-841: the tier-1 return schema carries the decisions element', () => {
  for (const skillDir of METHODOLOGY_EXTENSION_DIRS) {
    const skill = fs.readFileSync(path.join(skillDir, 'SKILL.md'), 'utf8')
    // Anchor on the sentence that introduces the schema rather than taking the file's FIRST json
    // fence: an example block added ahead of it would silently move every assertion below onto the
    // wrong object while staying green.
    const intro = skill.indexOf('Return only the fixed short task contract expected by the core:')
    assert.ok(
      intro !== -1,
      `${skillDir}/SKILL.md must still introduce the return object as the fixed short task contract`,
    )
    const open = skill.indexOf('```json', intro)
    assert.ok(
      open !== -1,
      `${skillDir}/SKILL.md must still state the return object as a JSON block`,
    )
    const close = skill.indexOf('```', open + 7)
    assert.ok(close !== -1, `${skillDir}/SKILL.md return-object JSON block must be closed`)
    const returnObject = skill.slice(open, close)
    assert.match(
      returnObject,
      /"decisionsRecorded"/,
      `${skillDir}/SKILL.md return object must carry the decisions element the core collects into ## Autonomous decisions`,
    )
    // The field is inert unless the extension says where it goes; a subagent that reads only an
    // empty array in a schema has no reason to populate it.
    assert.match(
      skill.replace(/\s+/g, ' '),
      /`decisionsRecorded` is\s+every\s+ordinary\s+ambiguity\s+this\s+dispatch\s+decided\s+instead\s+of\s+asking/,
      `${skillDir}/SKILL.md must say what decisionsRecorded holds`,
    )
    assert.match(
      skill.replace(/\s+/g, ' '),
      /collects\s+the\s+field\s+from\s+every\s+task\s+contract\s+into\s+the\s+PR\s+body's `## Autonomous\s+decisions` section/,
      `${skillDir}/SKILL.md must say decisionsRecorded is what reaches the PR body`,
    )
  }
})

// BOS-841: "record the decision" is inert unless a decision made inside a dispatched implementer
// can reach the orchestrator that writes the PR body. The fixed short task-contract is a CLOSED
// enumeration stated in two places, and a subagent returning a field the contract does not list
// is returning something the orchestrator is told not to thread. Both enumerations must name the
// decisions element, and the Step 7 template must still carry the section it lands in.
test('BOS-841: a decision made inside a dispatch reaches the PR body (both mirrors)', () => {
  // The body is hard-wrapped, and the two enumerations wrap this phrase at different points, so
  // match across the wrap rather than pinning one incidental line break.
  const decisionsElement = /decisions\s+recorded\s+\(decision\s+\+\s+rationale\)/
  for (const dir of BUILD_MIRRORS) {
    const body = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')

    // B.1a — the Step 5 overlay statement of the contract.
    const overlay = region(
      body,
      '**boss-build overlay:**',
      '**Commit-before-return contract.**',
      `${dir}/SKILL.md`,
    )
    assert.match(
      overlay,
      decisionsElement,
      `${dir}/SKILL.md: the Step 5 contract overlay must name the decisions element`,
    )

    // B.1b — the tier-3 restatement of the same contract. Two enumerations that disagree are how
    // a dispatched subagent reads the one that omits the element it was told to record.
    const restatement = region(
      body,
      'Return only the fixed short task-contract:',
      '## Step 6: Whole-branch review',
      `${dir}/SKILL.md`,
    )
    assert.match(
      restatement,
      decisionsElement,
      `${dir}/SKILL.md: the tier-3 contract restatement must name the decisions element in the same words`,
    )

    // B.2 — the destination. The decide-and-record group names this section by title; a template
    // that lost it would send every recorded decision to a heading that does not exist. Anchor on
    // the heading AND its placeholder line at the start of a line: Step 7 prose now cites
    // `## Autonomous decisions` inline (see B.3), so a bare substring match would be satisfied by
    // the citation and could no longer be falsified by deleting the template heading it names.
    const step7 = region(body, '## Step 7: PR gate', '## Steps 8-12:', `${dir}/SKILL.md`)
    assert.match(
      step7,
      /^## Autonomous[ ]decisions\n- <decision \+ rationale>$/m,
      `${dir}/SKILL.md: the Step 7 PR-body template must still carry the ## Autonomous decisions section and its decision + rationale placeholder`,
    )

    // B.3 — the join. B.1a/B.1b prove the contract carries the element and B.2 proves the section
    // exists, but neither makes the orchestrator transfer one into the other: the overlay describes
    // the contract as input to the NEXT dispatch only, so a decision could ride the contract the
    // whole way and still never be written down. Step 7 must state that the section collects every
    // task contract's decisions element, not only the orchestrator's own.
    assert.match(
      step7,
      /collects\s+the\s+decisions-recorded\s+element\s+of \*\*every\*\*\s+task\s+contract/,
      `${dir}/SKILL.md: Step 7 must say ## Autonomous decisions collects every task contract's decisions element`,
    )
  }
})

test('BOS-240: review-stack adds a conditional API-surface required check (both mirrors)', () => {
  for (const mirror of Object.keys(RESIDENT_BODIES)) {
    const reviewStack = readRef(mirror, 'review-stack.md')
    assert.match(
      reviewStack,
      /API-surface\s+check/,
      `${mirror}: review-stack must add the conditional API-surface check`,
    )
    assert.match(
      reviewStack,
      /proto\/bossanova\/v1/,
      `${mirror}: API-surface check must trigger on proto/bossanova/v1 paths`,
    )
    assert.match(
      reviewStack,
      /lib\/bossalib\/apiversion/,
      `${mirror}: API-surface check must reference the apiversion registry`,
    )
    // A missing version bump is a required must-fix, and a deferred one routes to BLOCKED.
    assert.match(
      reviewStack,
      /required-deferred/,
      `${mirror}: a missing required version bump must be a required-deferred item`,
    )
    assert.match(
      reviewStack,
      /BLOCKED[^\n]*never\s+REVIEW_READY/,
      `${mirror}: a deferred required version bump routes to BLOCKED, never REVIEW_READY`,
    )
  }
})

test('BOS-303: an empty/bootstrap draft PR placeholder is adopted and resumed, not a stop condition', () => {
  // boss-epic (BOS-303) routes an empty draft PR placeholder to the child
  // boss-build to continue from existing branch/session state. This pins the
  // boss-build side of that contract: an existing empty bootstrap/draft PR is
  // adopted (Step 2.5 → fresh reuse / resume), never treated as completed work
  // and never a stop condition merely because a PR number exists.
  const skill = claudeBody()
  assert.match(
    skill,
    /bossd's\s+bootstrap\s+draft, an\s+empty\s+PR[^\n]*is \*\*adopted\s+and\s*\n?resumed\*\*, not\s+a\s+stop\s+condition/,
    'boss-build must state an existing empty/bootstrap draft PR is adopted and resumed, not a stop condition',
  )
  const step25 = region(skill, '## Step 2.5:', '## Step 3:')
  assert.match(
    step25,
    /empty\s+bootstrap\s+PR\s+is\s+adoptable, never\s+foreign/,
    'Step 2.5 must classify an empty bootstrap PR as adoptable, never foreign',
  )
  assert.match(
    step25,
    /the\s+bootstrap\s+PR \(no\s+create\)/,
    'Step 2.5 must route a bootstrap-only PR to fresh-reuse (adopt), not restart',
  )
})

test('BOS-914: bootstrap artifacts do not decide claims, and closed PRs are probed for salvage', () => {
  for (const dir of BUILD_MIRRORS) {
    const skill = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')
    const step25 = region(skill, '## Step 2.5:', '## Step 3:', `${dir}: Step 2.5`)
    const step3 = region(skill, '## Step 3:', '## Step 4:', `${dir}: Step 3`)
    const ref = claimAndEligibility(dir)

    assert.match(
      step25,
      /references\/claim-and-eligibility\.md/,
      `${dir}: Step 2.5 must point at the claim-and-eligibility reference`,
    )
    assert.match(
      step3,
      /references\/claim-and-eligibility\.md/,
      `${dir}: Step 3 must point at the claim-and-eligibility reference`,
    )
    assert.match(
      ref,
      /in-progress\s+tracker\s+state[\s\S]*draft\s+PR\s+on\s+the\s+session\s+branch[\s\S]*carry\s+no\s+claim\s+weight/i,
      `${dir}/${CLAIM_ELIGIBILITY_REF}: bootstrap tracker/PR artifacts must carry no claim weight`,
    )
    assert.match(
      ref,
      /claim\s+decision\s+is\s+based\s+on\s+the\s+claim\s+comment\s+set\s+plus\s+peer-liveness\s+evidence/i,
      `${dir}/${CLAIM_ELIGIBILITY_REF}: claim weight must come from comments plus liveness`,
    )
    assert.match(
      ref,
      /in-progress\s+with\s+no\s+claim\s+comment\s+is\s+a\s+dead\s+run's\s+residue,\s+not\s+a\s+live\s+peer/i,
      `${dir}/${CLAIM_ELIGIBILITY_REF}: no-claim in-progress residue must not imply a live peer`,
    )
    assert.ok(
      precedes(
        ref,
        'Those bootstrap artifacts carry no claim weight',
        'The claim decision is based',
        `${dir}/${CLAIM_ELIGIBILITY_REF}`,
      ),
      `${dir}/${CLAIM_ELIGIBILITY_REF}: bootstrap-artifact rule must precede the claim decision`,
    )
    assert.match(
      ref,
      /When\s+no\s+open\s+PR\s+exists\s+for\s+the\s+session\s+branch[\s\S]*multiple\s+PR\s+attachments\s+with\s+zero\s+claim\s+comments[\s\S]*recently\s+closed\s+PR\s+on\s+the\s+same\s+session\s+branch\s+and\s+list\s+its\s+commits/i,
      `${dir}/${CLAIM_ELIGIBILITY_REF}: closed-PR probe must cover no-open-PR and multi-attachment residue`,
    )
    assert.match(
      ref,
      /closedAt[\s\S]*commit\s+count[\s\S]*bootstrap-only[\s\S]*nothing\s+to\s+resume[\s\S]*non-bootstrap\s+commits[\s\S]*report\s+the\s+salvageable\s+commits/i,
      `${dir}/${CLAIM_ELIGIBILITY_REF}: closedAt plus commit-count discriminator must be stated`,
    )
    assert.match(
      ref,
      /Salvageable\s+commits\s+are\s+evidence\s+to\s+report\s+and\s+assess,\s+not\s+claim\s+ownership/i,
      `${dir}/${CLAIM_ELIGIBILITY_REF}: salvageable commits must not constitute a claim`,
    )
    assert.match(
      ref,
      /plain\s+`ACQUIRED`\s+rather\s+than\s+`TOOK_OVER_STALE`[\s\S]*corroborating\s+a\s+dead\s+prior\s+run,\s+never\s+as\s+decisive/i,
      `${dir}/${CLAIM_ELIGIBILITY_REF}: ACQUIRED must corroborate rather than decide`,
    )
  }
})

test('BOS-495: up-front callback reflex + callbacksAvailable gate in both mirrors', () => {
  // The awareness fix: "prefer a callback over blind polling" is an up-front Hard-rules
  // reflex, gated on the single `callbacksAvailable(env)` signal, present byte-identically
  // in BOTH Go mirrors, and the callback reference frames graceful degradation around the
  // gate (gate false ⇒ skip registerWatch → fallbackPoll, never a failed wait). Pin all
  // three so the discoverability fix can never silently regress to a buried wait-step hint.
  for (const dir of BUILD_MIRRORS) {
    const skill = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')
    const hardRules = region(skill, '## Hard rules', '## Trust rules')
    assert.match(
      hardRules,
      /Prefer\s+a\s+callback\s+over\s+blind\s+polling/i,
      `${dir}/SKILL.md Hard rules must carry the up-front "prefer a callback over blind polling" reflex`,
    )
    assert.ok(
      hardRules.includes('callbacksAvailable'),
      `${dir}/SKILL.md Hard rules reflex must gate on callbacksAvailable`,
    )

    // The callback reference names the gate and frames degradation around it.
    const ref = fs.readFileSync(path.join(rootDir, dir, 'references/callback-watches.md'), 'utf8')
    assert.ok(
      ref.includes('callbacksAvailable'),
      `${dir}/references/callback-watches.md must name the callbacksAvailable gate`,
    )
    assert.match(
      ref,
      /skip `registerWatch`/,
      `${dir}/references/callback-watches.md must say gate false ⇒ skip registerWatch`,
    )
    assert.match(
      ref,
      /Graceful\s+degradation\s+gated\s+on `callbacksAvailable`/,
      `${dir}/references/callback-watches.md must frame degradation around the gate`,
    )
  }

  // The "byte-identical in BOTH Go mirrors" claim above is only real if something
  // diffs the two copies: the per-mirror phrase checks pass even if one mirror drifts
  // in whitespace/wording or a `make copy-skills` is skipped. Enforce it directly.
  const [canonicalDir, pluginDir] = BUILD_MIRRORS
  for (const rel of [
    'SKILL.md',
    'references/callback-watches.md',
    'references/proof-capture.md',
    FINALIZE_REF,
  ]) {
    assert.equal(
      fs.readFileSync(path.join(rootDir, pluginDir, rel), 'utf8'),
      fs.readFileSync(path.join(rootDir, canonicalDir, rel), 'utf8'),
      `${pluginDir}/${rel} must be byte-identical to the canonical mirror (run \`make copy-skills\`)`,
    )
  }
})

test('BOS-470: CI/PR waits adopt one-shot callbacks with authoritative reconciliation + safe fallback', () => {
  // The wait steps (green gate Step 8, re-inject Step 9) must arm a grouped one-shot GitHub
  // callback, reconcile against real PR state before acting, dedup at-least-once delivery, re-arm
  // while still waiting, and degrade to a bounded poll when callbacks are unavailable. Pin the
  // contract in the resident body + the deep-dive reference so it can never regress to a naked poll.
  const skill = claudeBody()
  const bodyTokens = [
    'resolveCallbackAdapter', // the callback-notifier adapter seam
    'toolbox/callback/adapter.mjs', // its path
    'boss callback add', // the generic register CLI (project-agnostic host interface)
    'policy.watchTriggers', // the grouped trigger set lives in policy, not hard-coded prose
    'reconcile against real', // authoritative reconciliation before acting
    'policy.fallbackPoll', // bounded fallback when callbacks are unavailable
  ]
  // BOS-674: the wait *sites* (Steps 8/9) moved to references/finalize-and-stop.md, so the
  // per-site tokens are pinned there; the reflex + adapter seam stay in the resident body.
  const stepsRef = finalizeAndStop()
  for (const token of bodyTokens) {
    assert.ok(
      skill.includes(token) || stepsRef.includes(token),
      `boss-build must document callback token "${token}" in SKILL.md or ${FINALIZE_REF}`,
    )
  }
  // Both wait points (Step 8 green gate, Step 9 re-inject) point at the callback reference.
  // The pointer is sibling-relative: these steps now live inside `references/` themselves, so a
  // `references/`-prefixed target would resolve to `references/references/callback-watches.md`.
  // The link must therefore NOT carry that prefix — assert the resolvable form.
  const step8 = region(stepsRef, '## Step 8:', '## Step 9:')
  const step9 = region(stepsRef, '## Step 9:', '## Step 10:')
  for (const [name, step] of [
    ['Step 8', step8],
    ['Step 9', step9],
  ]) {
    assert.match(
      step,
      /\]\(callback-watches\.md\)/,
      `${name} must point the CI/PR wait at the sibling-relative callback-watches.md`,
    )
    assert.doesNotMatch(
      step,
      /\]\(references\/callback-watches\.md\)/,
      `${name} must not use a references/-prefixed link from inside references/ (resolves to references/references/…)`,
    )
  }

  // The reference nails the four hard invariants: grouped triggers, reconcile-before-act,
  // idempotent under duplicate delivery, and graceful degradation to the poll.
  const ref = fs.readFileSync(path.join(rootDir, CORE, 'references/callback-watches.md'), 'utf8')
  assert.match(
    ref,
    /checks_passed[\s\S]*checks_failed[\s\S]*merged/,
    'reference must name the grouped triggers',
  )
  assert.match(ref, /Reconcile\s+before\s+act/i, 'reference must state reconcile-before-act')
  assert.match(
    ref,
    /Idempotent\s+under\s+duplicate/i,
    'reference must state idempotent-under-duplicate delivery',
  )
  assert.match(
    ref,
    /Graceful\s+degradation/i,
    'reference must state graceful degradation to the poll',
  )
  assert.match(
    ref,
    /gh\s+pr\s+checks .*--watch --fail-fast/,
    'reference must keep the bounded fallback poll',
  )
  // Published-core invariant: no host-specific tracker/MCP identity leaks into the reference.
  assert.doesNotMatch(
    ref,
    /bossanova-(linear|sentry)/,
    'reference must stay project-agnostic (no project MCP names)',
  )
})

test('BOS-752: callback waits use per-trigger groups, guarded re-arm, and three-way reconcile', () => {
  for (const dir of BUILD_MIRRORS) {
    const skill = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')
    const ref = fs.readFileSync(path.join(rootDir, dir, 'references/callback-watches.md'), 'utf8')
    const finalizer = fs.readFileSync(path.join(rootDir, dir, FINALIZE_REF), 'utf8')
    const prose = `${skill}\n${ref}\n${finalizer}`.replace(/\s+/g, ' ')

    assert.match(
      skill,
      /per-trigger\s+\*\*groups\*\*/i,
      `${dir}/SKILL.md must say PR wait triggers use per-trigger groups`,
    )
    assert.match(
      ref,
      /--group "buildwait-\$PR-\$T"/,
      `${dir}/references/callback-watches.md must arm each trigger with a per-trigger group`,
    )
    assert.doesNotMatch(
      ref,
      /--group "buildwait-\$PR"(?!-\$T)/,
      `${dir}/references/callback-watches.md must not use one shared buildwait group`,
    )
    assert.match(
      prose,
      /group\s+(?:two\s+)?triggers\s+only\s+when\s+at\s+most\s+one\s+of\s+them\s+can\s+ever\s+be\s+satisfied/i,
      `${dir} must state the mutual-exclusivity rule for callback groups`,
    )
    assert.doesNotMatch(
      finalizer,
      /one-shot\s+callback\s+group|group's\s+live\s+watches/i,
      `${dir}/${FINALIZE_REF} must not describe the PR wait as one shared callback group`,
    )

    for (const outcome of ['ready', 'not-yet', 'could-not-evaluate']) {
      assert.match(
        ref,
        new RegExp(`\\b${outcome}\\b`),
        `${dir}/references/callback-watches.md must define the ${outcome} reconcile outcome`,
      )
    }
    assert.match(
      ref,
      /mergeStateStatus\s*==\s*"CLEAN"/,
      `${dir}/references/callback-watches.md ready outcome must require mergeStateStatus == "CLEAN"`,
    )
    assert.match(
      ref,
      /check\s+count\s+of\s+zero\s+is\s+not\s+a\s+pass/i,
      `${dir}/references/callback-watches.md must say an empty rollup is not green`,
    )
    assert.match(
      ref,
      /empty\s+commit\s+that\s+skips\s+CI/i,
      `${dir}/references/callback-watches.md must name the project-agnostic vacuous-green motivation`,
    )

    assert.match(
      ref,
      /Re-arm\s+a\s+trigger\s+only\s+when[\s\S]{0,180}condition\s+as\s+\*\*false\*\*/i,
      `${dir}/references/callback-watches.md must guard re-arm on a false condition`,
    )
    assert.match(
      ref,
      /record\s+the\s+skip\s+by\s+name/i,
      `${dir}/references/callback-watches.md must record skipped re-arm triggers by name`,
    )
    assert.match(
      ref,
      /could-not-evaluate[\s\S]{0,80}arm\s+nothing/i,
      `${dir}/references/callback-watches.md must arm nothing when reconcile could not evaluate`,
    )
  }
})

