test('BOS-742: the added Step 6/6b prose stays project-agnostic (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = readReviewStack(dir)
    const step6 = region(
      reviewStack,
      '## Step 6:',
      '### Mechanical remediation',
      `${dir}/references/review-stack.md`,
    )
    const step6b = region(
      reviewStack,
      '## Step 6b:',
      '## Step 6c:',
      `${dir}/references/review-stack.md`,
    )
    for (const [label, slice] of [
      [`${dir}/references/review-stack.md Step 6`, step6],
      [`${dir}/references/review-stack.md Step 6b`, step6b],
    ]) {
      assert.doesNotMatch(slice, /bossanova|linear|BOS-\d+/i, `${label} must stay project-agnostic`)
    }
  }
})
// BOS-758: Step 6 was all-or-nothing — the full stack (loop + 6b + 6c) or no review at all — so the
// first wall-clock overrun removed 100% of review coverage rather than degrading it, and runs were
// observed improvising an undocumented reduced tier while still reporting REVIEW_READY. The named
// degraded tier is the documented middle, chosen at a phase boundary and recorded either way.
const reviewStackFor = (dir) =>
  fs.readFileSync(path.join(rootDir, dir, 'references/review-stack.md'), 'utf8')

test('BOS-758: review-stack names a degraded tier picked at Step 6 entry (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)

    // (a) A selection point at Step 6 ENTRY, driven by the remaining wall clock — not an
    // overrun-only fallback discovered mid-loop.
    assert.match(
      reviewStack,
      /^#{2,3} Step\s+6\s+entry — review\s+tier\s+selection\s*$/m,
      `${dir}/references/review-stack.md must carry a Step 6 entry tier-selection section`,
    )
    assert.match(
      reviewStack,
      /Step\s+6\s+entry[\s\S]{0,900}remaining\s+wall\s+clock/i,
      `${dir}: the tier must be chosen at Step 6 entry from the remaining wall clock`,
    )
    // The threshold must be ARITHMETIC an autonomous runner can evaluate, not a judgement call.
    // Naming "remaining wall clock" alone is not enough: a mutant reading "if the budget seems
    // low, pick the degraded tier" satisfies the assertion above while restoring exactly the
    // argue-it-either-way selection the section exists to eliminate. Pin the named budget, the
    // round cap it is derived from, and both comparison directions.
    const tierSelection = region(
      reviewStack,
      '## Step 6 entry — review tier selection',
      '## Step 6: Whole-branch review loop',
    )
    for (const [pattern, why] of [
      [/FULL_TIER_MINUTES/, 'the threshold must be a named, computed budget'],
      [
        /`REMAINING_MINUTES`/,
        'the reference must name the input it consumes — the producer side alone is half a contract',
      ],
      [
        // This paragraph has regressed on three consecutive edits, each fix relocating the defect:
        // subagent-has-no-deadline → reference-never-names-the-input → inline-reader-has-no-brief.
        // The last of those is closed only by these six lines, and reverting them alone left every
        // other assertion green. Pin the inline reader's instruction, not just the dispatched one's.
        /\*\*inline\s+fallback\*\*[\s\S]{0,240}compute `REMAINING_MINUTES` yourself/i,
        'the inline fallback reader IS the orchestrator and must compute the budget, not take the absent-input fail-safe',
      ],
      [
        /\$MAX_ROUNDS/,
        'the budget must be derived from the effective round cap, not a magic number',
      ],
      [
        // Both comparison directions now carry the post-review reserve. Review is not the last
        // phase: at exactly FULL_TIER_MINUTES the worst legal path consumes the entire remaining
        // Preflight budget and Steps 7-12 (push, PR, CI/repair, proof, finalize) get nothing, so a
        // tier deemed affordable still leaves the build unable to finish. `\s+` between the terms,
        // not literal spaces — prettier reflows this list at 100 columns.
        /≥\s*`?FULL_TIER_MINUTES\s*\+\s*POST_REVIEW_RESERVE_MINUTES`?[\s\S]{0,120}full\s+tier/i,
        'at-or-above the threshold PLUS the post-review reserve must select the full tier',
      ],
      [
        /<\s*`?FULL_TIER_MINUTES\s*\+\s*POST_REVIEW_RESERVE_MINUTES`?[\s\S]{0,220}degraded\s+tier/i,
        'below the reserved threshold (but above the floor) must select the degraded tier',
      ],
      [
        /was\s+not\s+supplied[\s\S]{0,200}full\s+tier/i,
        'an absent budget input must fail safe to the full tier — ambiguity resolves toward more coverage',
      ],
      [
        // The fail-safe must be scoped to the ABSENT INPUT, never to the subagent's own inability
        // to see a clock — that is true on every run by construction, so the looser reading fires
        // always and makes the degraded tier unreachable.
        /Two\s+readings\s+are \*\*wrong\*\*[\s\S]{0,320}cannot\s+see\s+a\s+clock[\s\S]{0,220}inline\s+fallback/i,
        'the fail-safe must rule out BOTH always-true misreadings: "the subagent has no clock", and "no brief on the inline path, so the input is absent"',
      ],
    ]) {
      assert.match(
        tierSelection,
        pattern,
        `${dir}: the Step 6 entry threshold must be decidable — ${why}`,
      )
    }
    // (a2) The ladder needs BOTH ends of the comparison: a floor under it and a reserve above it.
    //
    // Without a floor, "< FULL_TIER_MINUTES → degraded tier" is total over the reals: zero or
    // negative remaining minutes compares below the threshold and selects the degraded tier, so a
    // run already at or past the Preflight deadline starts another ~10-minute reviewer — the exact
    // overrun the ladder exists to prevent, merely at the cheap tier instead of the full one.
    // Without a reserve, "≥ FULL_TIER_MINUTES → full tier" spends the WHOLE remaining budget on
    // review: at exactly 145 the worst legal path costs 145 and Steps 7-12 (push, PR, CI/repair,
    // proof, finalize) inherit nothing, so a tier deemed affordable still cannot finish the build.
    // Both numbers must be priced, not hand-waved, or the comparison stops being decidable.
    assert.match(
      tierSelection,
      /POST_REVIEW_RESERVE_MINUTES\s*=[\s\S]{0,400}=\s*25\s+minutes/,
      `${dir}: the ladder must reserve a priced, numeric post-review budget for Steps 7-12`,
    )
    assert.match(
      tierSelection,
      /DEGRADED_REVIEWER_MINUTES\s*=\s*10/,
      `${dir}: the floor must price the degraded whole-branch reviewer`,
    )
    assert.match(
      tierSelection,
      /DEGRADED_API_CHECK_MINUTES\s*=\s*5/,
      `${dir}: the floor must price the conditional degraded API check`,
    )
    assert.match(
      tierSelection,
      /DEGRADED_TIER_MINUTES\s*=\s*\$DEGRADED_REVIEWER_MINUTES[\s\S]{0,100}\+\s*\$DEGRADED_API_CHECK_MINUTES/,
      `${dir}: the degraded tier price must include both its reviewer and API-gate allowances`,
    )
    // The negative that matters: a later edit can satisfy every positive above and still restore
    // the whole-budget threshold by dropping the reserve from the comparison itself.
    assert.doesNotMatch(
      tierSelection,
      /≥\s*`?FULL_TIER_MINUTES`?(?!\s*\+\s*POST_REVIEW_RESERVE_MINUTES)/,
      `${dir}: no full-tier comparison may spend the entire remaining budget — every FULL_TIER_MINUTES threshold must add the post-review reserve`,
    )
    // The floor branch itself: a named non-tier outcome that dispatches nothing and routes to
    // BLOCKED, with zero/negative explicitly landing on it rather than on the degraded tier.
    assert.match(
      tierSelection,
      /<\s*`?DEGRADED_TIER_MINUTES\s*\+\s*POST_REVIEW_RESERVE_MINUTES`?[\s\S]{0,120}no\s+tier\s+at\s+all/i,
      `${dir}: below the degraded tier plus the reserve there must be NO tier, not a cheap one`,
    )
    assert.match(
      tierSelection,
      /no\s+tier\s+at\s+all[\s\S]{0,400}\*\*BLOCKED\*\*/i,
      `${dir}: the floor branch must route to BLOCKED, not merely decline the full tier`,
    )
    assert.match(
      tierSelection,
      /Zero\s+and\s+negative\s+values\s+land\s+here/i,
      `${dir}: the floor branch must name zero/negative remaining minutes as landing on it`,
    )
    // Order is load bearing. The absent-input fail-safe must resolve BEFORE the floor: a missing
    // value is not a small one, and a floor evaluated first would block every run whose
    // orchestrator forgot to pass the number instead of reviewing it at the full tier.
    const absentIdx = tierSelection.search(/was\s+not\s+supplied/)
    const floorIdx = tierSelection.search(
      /DEGRADED_TIER_MINUTES\s*\+\s*POST_REVIEW_RESERVE_MINUTES/,
    )
    assert.ok(
      absentIdx >= 0 && floorIdx > absentIdx,
      `${dir}: the absent-input fail-safe must be evaluated before the budget floor`,
    )
    // Gate the hand-off. Only the orchestrator can decline to dispatch, so a floor that only the
    // dispatched subagent evaluates fires AFTER the dispatch it exists to prevent — inert, with
    // every prose assertion above still green. Pin the owner in the reference and the gate itself
    // in the resident body.
    assert.match(
      tierSelection,
      /Only\s+the\s+orchestrator\s+can\s+decline\s+to\s+dispatch[\s\S]{0,300}\*\*before\*\*\s+the\s+dispatch/i,
      `${dir}: the floor branch must be owned by the orchestrator, pre-dispatch`,
    )
    assert.match(
      readSkill(`${dir}/SKILL.md`),
      /budget\s+floor\s+before\s+you\s+dispatch[\s\S]{0,400}dispatch\s+\*\*nothing\*\*/i,
      `${dir}/SKILL.md: Step 6 must apply the budget floor before dispatching, or the floor is inert`,
    )
    // The shouldn't-happen path still has to route somewhere REAL — and the sentinel has to be
    // GENERATED, not transcribed. `matchSentinel` only classifies a capped line carrying the
    // helper's `after <N> rounds.` tail, so the literal `bs-review capped: 1` this paragraph used
    // to instruct is exactly as unmatchable as `capped: 0`: it silently downgrades the route to a
    // `dispatch-failure` whose token claims the verdict was *unreadable* — when the runner knows
    // no reviewer ran at all. Pin the helper invocation, and forbid the literal outright: a prose
    // fix that merely mentions the literal as a counter-example would leave a positive-only
    // assertion green while a reader still copies it.
    // GENERATING it is only half the instruction: `bs-review-caps.mjs` prints to stdout and writes
    // nothing, so a bare helper invocation leaves the run file ABSENT — a *missing* sentinel, which
    // is the same `dispatch-failure` by the other sub-case. Pin the persist half explicitly; the
    // executable gate below proves both halves actually work.
    //
    // BOUND THE WINDOW at the degraded tier's own `### ` heading. `### Degraded tier (minimal)` is
    // a SUBSECTION of the tier-selection section, so `tierSelection` runs straight through it — and
    // the degraded tier carries its own copy of this command. Unbounded, reverting the below-floor
    // route to a bare print-only helper leaves this assertion satisfied by the OTHER route's block.
    // BOS-737: the bound the paragraph above calls load-bearing was itself fail-OPEN. Raw, a
    // renamed heading made `indexOf` return -1 and `slice(0, -1)` hand back nearly all of
    // `tierSelection` — the degraded tier's own copy of this command included — so both
    // positive assertions below would have been satisfied by the very route this window exists
    // to exclude. `assert.ok(belowFloor.length > 0)` could not catch it either: a near-whole
    // region has length. `region()` throws on the renamed heading instead.
    // Scoped to `tierSelection`, not to the whole `reviewStack`: the paragraph above says the
    // bound exists to keep the degraded tier's own copy of this command out of the window, and
    // searching the whole file re-opens exactly that. Renamed, both forms throw; MOVED past
    // `## Step 6: Whole-branch review loop`, the whole-file form still finds it and hands back a
    // cross-section window, while this one throws because the marker has left the section.
    // Byte-identical today — `tierSelection` begins at the start marker, so its index is 0.
    const belowFloor = region(
      tierSelection,
      '## Step 6 entry — review tier selection',
      '### Degraded tier (minimal)',
    )
    assert.match(
      belowFloor,
      /node\s+"\$RUN_SENTINEL"\s+write\s+"\$RUN_DIR"\s+"\$RUN_ID"\s+review[\s\S]{0,160}sentinel\s+capped\s+1/,
      `${dir}: the below-floor fallback must PERSIST the generated sentinel through bs-run-sentinel.mjs write, not merely print it`,
    )
    assert.match(
      belowFloor,
      /requires\s+a\s+\*\*positive\*\*\s+round\s+count/i,
      `${dir}: the below-floor fallback must say why the round count is 1, not 0`,
    )
    assert.doesNotMatch(
      tierSelection,
      /`bs-review\s+capped:\s*\d+`/,
      `${dir}: no hand-written capped sentinel literal — matchSentinel rejects it; generate it with \`sentinel capped <N>\``,
    )
    assert.match(
      reviewStack,
      /^#{3,4} Degraded\s+tier \(minimal\)\s*$/m,
      `${dir}: the degraded tier must be a named subsection, not improvised prose`,
    )

    // (b) Exactly what it runs, and exactly what it skips — named, by policy.
    //
    // BOUND THE WINDOW at the next `## ` heading. A one-argument `slice()` would run to EOF, so
    // the "degraded tier" window would really be the tier PLUS Steps 6, 6b and 6c — and four of
    // the assertions below (`code-reviewer-template.md`, `$REVIEW_BASE...HEAD`,
    // `bs-review capped:`, `BLOCKED`) all appear downstream in the full tier's own prose. Unbounded,
    // a mutant that deletes the whole tier body and replaces it with "an open must-fix is deferred
    // and the run proceeds to REVIEW_READY" still passes every one of them — i.e. the two
    // assertions guarding against exactly that coverage laundering are the ones that cannot fail.
    const degradedRest = region(reviewStack, '### Degraded tier (minimal)')
    const degradedEnd = degradedRest.search(/\n## /)
    const degraded = degradedEnd === -1 ? degradedRest : degradedRest.slice(0, degradedEnd)
    assert.match(
      degraded,
      /code-reviewer-template\.md/,
      `${dir}: the degraded tier must reuse the existing whole-branch reviewer template`,
    )
    assert.match(
      degraded,
      /\$REVIEW_BASE\.\.\.HEAD/,
      `${dir}: the degraded reviewer must still read the whole branch`,
    )
    // BOS-859 RE-SCOPED these two. The tier may now spend ONE bounded repair round, so "the tier is
    // a single round" and "there is no fix→re-review loop" are no longer the invariants — but both
    // bounds they carried are still owed, so neither assertion is dropped, each is narrowed to what
    // is still true and joined by the companion the narrowing would otherwise lose.
    //
    // (i) DETECTION is still exactly one round. A bare /single round/ would now be satisfied by the
    // repair round's own cap, so pin the detection clause itself.
    assert.match(
      degraded,
      /\*\*Detection\s+is\s+a\s+single\s+round\.?\*\*/i,
      `${dir}: the degraded tier's DETECTION pass must still be bounded to a single round`,
    )
    // (ii) …and the companion bound: the repair round is capped at one too, so neither pass
    // iterates. Without this, re-scoping (i) to "detection" would silently license an unbounded
    // repair loop in a tier selected precisely because the clock is short.
    assert.match(
      degraded,
      /at\s+most\s+\*\*one\*\*\s+bounded\s+repair\s+round/i,
      `${dir}: the degraded tier's repair round must itself be capped at one`,
    )
    // (iii) The replacement for "no fix→re-review loop": repair is permitted, but ONLY behind both
    // gates. Pin the conditionality rather than the old prohibition — a mutant that permits repair
    // unconditionally (the actual regression risk now) reds here, where the old assertion would
    // have been merely deleted.
    assert.match(
      degraded,
      /Repair\s+is\s+permitted\s+\*\*only\*\*\s+behind\s+both\s+gates/i,
      `${dir}: degraded-tier repair must be permitted only behind the eligibility and affordability gates`,
    )
    assert.match(
      degraded,
      /Step\s+6b[\s\S]{0,200}Step\s+6c[\s\S]{0,200}skipped\s+by\s+policy/i,
      `${dir}: the degraded tier must name Steps 6b and 6c as skipped by policy`,
    )
    // Skipping Step 6b does not excuse the OTHER never-omit PR-body section. Step 7 makes
    // `## Cross-model review` mandatory so silence cannot read as "passed clean", and the degraded
    // tier skips the pass that fills it — so the tier must state the token to emit, and Step 6b's
    // own closed token list must recognise it. Otherwise a degraded run either omits a mandatory
    // section or invents a value, which is the improvised-reduced-tier failure this all exists to
    // close.
    assert.match(
      reviewStack,
      /`## Cross-model\s+review`[\s\S]{0,400}`skipped: degraded\s+tier`/i,
      `${dir}: a degraded run must be told which \`## Cross-model review\` token to emit`,
    )
    assert.match(
      reviewStack,
      /`skipped: <reason>`[\s\S]{0,200}`degraded\s+tier`/i,
      `${dir}: Step 6b's outcome-token list must recognise the degraded-tier skip reason`,
    )
    // The `dispatch-failure` route runs NO tier at all, so neither `full` nor `degraded:` is an
    // honest value — yet the section is mandatory and its absence reads as full coverage. Without a
    // sanctioned token the orchestrator must omit or improvise on the one route where zero review
    // happened. Pin the token in the reference AND its use on the routing branch in the body.
    assert.match(
      reviewStack,
      /`none: review\s+stack\s+did\s+not\s+run \(<reason>\)`/,
      `${dir}: the coverage-token list must cover the dispatch-failure route, where no tier ran`,
    )
    // The tier rule is evaluated by the SUBAGENT, but only the orchestrator holds the Preflight
    // deadline — no env var or file carries it. If the Step 6 dispatch brief does not hand over the
    // remaining budget, the reference's own `cannot be determined → full tier` fail-safe fires on
    // every dispatched run and the degraded tier is unreachable on its primary path: the feature
    // ships inert while every other gate here stays green, because they all pin the reference's
    // prose rather than the brief's contents. Pin the input at the brief.
    assert.match(
      readSkill(`${dir}/SKILL.md`),
      /`REMAINING_MINUTES`/,
      `${dir}/SKILL.md: Step 6's dispatch brief must pass the remaining budget the tier rule needs`,
    )
    assert.match(
      readSkill(`${dir}/SKILL.md`),
      /REMAINING_MINUTES[\s\S]{0,400}Preflight\s+deadline/i,
      `${dir}/SKILL.md: the brief must define REMAINING_MINUTES against the Preflight deadline`,
    )
    // The token text lives in the reference (the resident body carries the routing decision and a
    // pointer), so pin the pointer here and the token there — and pin that the two sub-cases are
    // distinguished, since collapsing them publishes "did not run" over a review that did.
    assert.match(
      readSkill(`${dir}/SKILL.md`),
      /`dispatch-failure`[\s\S]{0,400}do \*\*not\*\*\s*\n?\s*share\s+a\s+coverage\s+token/i,
      `${dir}/SKILL.md: the dispatch-failure branch must say its two sub-cases take different coverage tokens`,
    )
    assert.match(
      reviewStack,
      /present\s+but\s+unmatchable[\s\S]{0,600}`none: review\s+verdict\s+unreadable \(<reason>\)`/i,
      `${dir}: a present-but-unmatchable sentinel must not publish "review stack did not run"`,
    )
    // …and the OTHER sub-case had the same defect. The sentinel write is the subagent's LAST
    // action, so a kill/timeout/crash anywhere in the stack leaves it missing — including one that
    // struck after a reviewer, or several, had already reported. Publishing `did not run` there
    // asserts an absence the evidence does not support and hides partial coverage, which is the
    // ambiguity this whole section exists to expose. Pin the token this branch must publish AND
    // that the forbidden one is named as forbidden; the earlier wording said exactly the opposite.
    const missingIdx = reviewStack.indexOf('**Missing/stale sentinel**')
    const unmatchableIdx = reviewStack.indexOf('**Present but unmatchable sentinel**')
    assert.ok(
      missingIdx >= 0 && unmatchableIdx > missingIdx,
      `${dir}: the BLOCKED-route publication list must keep both dispatch-failure sub-cases, missing/stale first`,
    )
    const missingBullet = reviewStack.slice(missingIdx, unmatchableIdx)
    assert.match(
      missingBullet,
      /`none: review\s+coverage\s+unknown \(<reason>\)`/,
      `${dir}: a missing/stale sentinel must publish the unknown-coverage token`,
    )
    assert.match(
      missingBullet,
      /Do \*\*not\*\*\s+write\s+`did\s+not\s+run`/i,
      `${dir}: the missing/stale branch must forbid the "did not run" token by name`,
    )
    assert.doesNotMatch(
      missingBullet,
      /=\s*`none: review\s+stack\s+did\s+not\s+run/,
      `${dir}: a missing/stale sentinel must not be told to publish "review stack did not run"`,
    )
    // The token itself is therefore re-scoped to the only route that can honestly claim it — and
    // the actor who must decide it has to be handed an input that can decide it. The sentinel
    // cannot: "missing" is equally consistent with a stack that ran and died. The orchestrator's
    // own dispatch record can, so the entry must send it there.
    const didNotRunIdx = reviewStack.indexOf('- `none: review stack did not run (<reason>)`')
    const tokenListEndIdx = reviewStack.indexOf('Emit a `full` token on a full-tier run too')
    assert.ok(
      didNotRunIdx >= 0 && tokenListEndIdx > didNotRunIdx,
      `${dir}: the coverage-token list must keep a "review stack did not run" entry before its closing note`,
    )
    const didNotRunEntry = reviewStack.slice(didNotRunIdx, tokenListEndIdx)
    assert.match(
      didNotRunEntry,
      /never\s+entered/i,
      `${dir}: "review stack did not run" must be reserved for a stack that was never entered`,
    )
    assert.match(
      didNotRunEntry,
      /never\s+from\s+the\s+sentinel/i,
      `${dir}: the orchestrator must decide "did not run" from its own record, never from the sentinel`,
    )
    // Re-scoping the token relocates its defect unless the publication section gains the route
    // that now owns it: with both dispatch-failure bullets forbidden from writing `did not run`,
    // a BLOCKED run where review genuinely never started would otherwise have no branch to follow
    // and would reach for the nearest bullet. Name the third route where the reader is standing.
    assert.match(
      reviewStack,
      /`none: review\s+stack\s+did\s+not\s+run \(<reason>\)` belongs\s+to\s+neither\s+bullet[\s\S]{0,320}never\s+entered/i,
      `${dir}: the BLOCKED-route publication section must name the never-entered route that owns "did not run"`,
    )
    assert.match(
      reviewStack,
      /BLOCKED-route\s+publication[\s\S]{0,700}gh\s+pr\s+edit --body-file/i,
      `${dir}: the BLOCKED routes must publish the coverage token themselves — they never reach Step 7`,
    )
    // …and the no-PR branch has to publish BOTH mandatory sections, not just coverage. Its own
    // opening sentence calls `## Review coverage` and `## Cross-model review` mandatory and says
    // both are guaranteed absent on these routes; telling the orchestrator to comment only the
    // coverage token then loses whether the cross-model pass ran, was skipped, or errored — on the
    // one route (a fresh run that caps before Step 7) where there is no PR body to fall back on.
    // `\s+` between the words: prettier reflows this paragraph at 100 columns.
    const noPrIdx = reviewStack.search(/when\s+no\s+PR\s+exists\s+yet/i)
    assert.ok(noPrIdx >= 0, `${dir}: §BLOCKED-route publication must cover the no-PR case`)
    const noPrClause = reviewStack.slice(noPrIdx, noPrIdx + 700)
    assert.match(
      noPrClause,
      /put\s+\*\*both\*\*\s+tokens\s+verbatim\s+in\s*\n?\s*the\s+BLOCKED\s+blocker\s+comment/i,
      `${dir}: the no-PR BLOCKED comment must carry both mandatory tokens, not only the coverage one`,
    )
    assert.match(
      noPrClause,
      /`## Review\s+coverage`\s+and\s+`## Cross-model\s+review`/,
      `${dir}: the no-PR comment must label both sections exactly as the PR-body path does`,
    )
    assert.doesNotMatch(
      noPrClause,
      /put\s+the\s+coverage\s+token\s+verbatim/i,
      `${dir}: the no-PR branch must not publish the coverage token alone`,
    )
    // Re-scoping a token relocates its defect: the never-entered route is the one route with no
    // later step to supply a cross-model outcome (Step 6b lives INSIDE the stack that never ran),
    // so unless this branch names a value the blocker comment silently drops the section — and an
    // absent mandatory section reads as "passed clean", the exact failure it exists to prevent.
    const thirdRouteIdx = reviewStack.indexOf(
      '`none: review stack did not run (<reason>)` belongs to neither bullet',
    )
    const thirdRoute = reviewStack.slice(thirdRouteIdx, thirdRouteIdx + 900)
    assert.match(
      thirdRoute,
      /`## Cross-model\s+review`\s*=\s*`skipped: <reason>`/,
      `${dir}: the never-entered route must name a cross-model token, not just a coverage one`,
    )
    assert.match(
      thirdRoute,
      /not\s+an\s+`error: <reason>`/i,
      `${dir}: a stack that never ran is a policy skip, not a failed pass`,
    )
    // The floor branch is the reachable producer of `did not run`, so the token's own definition
    // has to admit it — otherwise the orchestrator applies a gate whose outcome no token covers.
    assert.match(
      didNotRunEntry,
      /budget\s+floor[\s\S]{0,160}before\s+any\s+reviewer\s+was\s+started/i,
      `${dir}: the "did not run" token must cover the Step 6 entry budget floor route`,
    )
    // The Step 7 template is what a run copies from, so an enumeration missing the failure-path
    // token sends the one route where no review ran looking for a value it cannot find. Pinning
    // only the reference's list and the routing branch left this byte free to drift.
    assert.match(
      readSkill(`${dir}/SKILL.md`),
      // Not `[^>]*` — the enumeration itself contains `<pass list>` and `<reason>` placeholders,
      // so a negated-`>` class stops at the first one and never reaches the token being pinned.
      /<review-coverage[ ]token:[\s\S]{0,300}none: review[ ]stack[ ]did[ ]not[ ]run[\s\S]{0,120}none: review[ ]verdict[ ]unreadable/i,
      `${dir}/SKILL.md: Step 7's coverage-token template must enumerate the \`none:\` form too`,
    )
    // The missing/stale-sentinel branch needs a sanctioned value in the template it copies from,
    // or the one route where coverage is genuinely unknown has nowhere honest to land and falls
    // back to the false `did not run`.
    assert.match(
      readSkill(`${dir}/SKILL.md`),
      /<review-coverage[ ]token:[\s\S]{0,400}none: review[ ]coverage[ ]unknown \(<reason>\)/i,
      `${dir}/SKILL.md: Step 7's coverage-token template must enumerate the unknown-coverage form`,
    )
    // …and the resident routing bullet must not point either dispatch-failure sub-case at
    // `did not run`. `\s+` between words, not literal spaces: prettier reflows this at 100 columns.
    assert.match(
      readSkill(`${dir}/SKILL.md`),
      /`dispatch-failure`[\s\S]{0,600}\*\*neither\*\*\s+of\s+them\s+is\s+`none:\s+review\s+stack\s+did\s+not\s+run`/i,
      `${dir}/SKILL.md: neither dispatch-failure sub-case may publish "review stack did not run"`,
    )

    // (c) Reduced coverage, never a reduced gate: must-fix still routes through the run-file
    // sentinel to BLOCKED. Without this the cheap tier becomes a coverage-laundering path.
    assert.match(
      degraded,
      /bs-review\s+capped:/,
      `${dir}: degraded must-fix findings must route through the same run-file sentinel`,
    )
    assert.match(
      degraded,
      /BLOCKED/,
      `${dir}: an open must-fix from the degraded tier must still reach BLOCKED`,
    )
    // BOS-859 REPLACED "detector, not a repairer" with the narrower rule that is now true. The old
    // sentence forbade repair as such; the argument underneath it was never about repair, it was
    // about SELF-certification — repair without an independent witness. Pin that, because it is the
    // property the repair pass must not erode, and deleting the old assertion outright would have
    // left the cheap tier free to launder an unverified fix into REVIEW_READY.
    assert.match(
      degraded,
      /may\s+repair,\s+but\s+it\s+may\s+never\s+self-certify/i,
      `${dir}: the degraded tier must forbid self-certification, not merely detection-only`,
    )
    // …and it must KEEP the reasoning the replaced paragraph carried. That reasoning is exactly why
    // the independent verification round, and not the change gate, is the evidence — a replacement
    // that dropped it would leave the new rule looking arbitrary and re-openable.
    assert.match(
      degraded,
      /change\s+gate\s+re-runs\s+`make`\s+targets,\s+which\s+cannot\s+confirm\s+a\s+_semantic_\s+finding/i,
      `${dir}: the self-certification rule must keep the change-gate reasoning it replaced`,
    )
    // The dead-reviewer rule is the tier's single-point-of-failure guard: with one reviewer and no
    // second opinion, an errored/timed-out/empty dispatch yields zero findings and would otherwise
    // read as a clean pass. Pin the RULE, not just the adjacent clean-sentinel wording — deleting
    // this paragraph outright previously left every gate green.
    assert.match(
      degraded,
      /errors,\s+times\s+out,\s+or\s+returns\s+no\s+structured\s+findings[\s\S]{0,220}sentinel\s+capped\s+1/i,
      `${dir}: a degraded reviewer that did not report must cap to BLOCKED via the generated sentinel, not read as zero must-fix`,
    )
    // ...and PERSIST it. The previous round traded an unmatchable-but-written literal for a
    // matchable-but-unwritten helper invocation: same `dispatch-failure`, opposite sub-case.
    assert.match(
      degraded,
      /node\s+"\$RUN_SENTINEL"\s+write\s+"\$RUN_DIR"\s+"\$RUN_ID"\s+review[\s\S]{0,160}sentinel\s+capped\s+1/,
      `${dir}: the dead-reviewer rule must PERSIST the generated sentinel through bs-run-sentinel.mjs write, not merely print it`,
    )
    // Same relocation guard as the below-floor route: the generated line is the only one
    // `matchSentinel` accepts, so a hand-written literal here would route to `dispatch-failure`
    // instead of BLOCKED and quietly change the tier's terminal state.
    assert.doesNotMatch(
      degraded,
      /`bs-review\s+capped:\s*\d+`/,
      `${dir}: the degraded tier must not hand-write a capped sentinel literal — generate it with \`sentinel capped <N>\``,
    )
    assert.match(
      degraded,
      /\*\*any\*\* must-fix\s+finding\s+is\s+recorded[\s\S]{0,240}`bs-review\s+capped:` → \*\*BLOCKED\*\*/i,
      `${dir}: ANY degraded-tier must-fix must route to BLOCKED, not just one left open after a fix`,
    )
    // `\s+` between words, not a literal space: prettier reflows this prose at 100 columns, so any
    // inter-word gap in the shipped markdown may be a newline.
    assert.match(
      degraded,
      /ran\s+to\s*\n?\s*completion\s+and\s+found\s+zero\*\*\s+must-fix\s+writes\s+`bs-review\s+clean:`/i,
      `${dir}: only a zero-must-fix degraded pass may write the clean sentinel`,
    )
    assert.match(
      degraded,
      /reduces\s+\*?\*?coverage\*?\*?,?\s+never\s+the\s+\*?\*?gate/i,
      `${dir}: the degraded tier must state it reduces coverage, never the gate`,
    )

    // (d) The existing inline dispatch-tool-error fallback runs the degraded tier when the budget
    // cannot fund the full one — while the missing/stale-sentinel route is untouched.
    assert.match(
      reviewStack,
      /if\s+that\s+dispatch\s+fails \(a\s+tool\s+error\)[\s\S]{0,400}degraded/i,
      `${dir}: the inline dispatch-error fallback must be able to run the degraded tier`,
    )
    assert.match(
      reviewStack,
      /missing[\s\S]{0,120}sentinel[\s\S]{0,200}dispatch-failure/i,
      `${dir}: a missing sentinel must still synthesize dispatch-failure`,
    )

    // (e) The returned outcome token, so the orchestrator can publish the tier.
    assert.match(
      reviewStack,
      /`## Review\s+coverage`/,
      `${dir}: the subagent's return contract must carry a \`## Review coverage\` token`,
    )
    assert.match(
      reviewStack,
      /`full`[\s\S]{0,400}`degraded: <reason> \(skipped: <pass\s+list>\)`/,
      `${dir}: the coverage token must distinguish full from degraded plus its skipped passes`,
    )
  }

  const [canonicalDir, pluginDir] = BUILD_MIRRORS
  assert.equal(
    reviewStackFor(pluginDir),
    reviewStackFor(canonicalDir),
    `${pluginDir}/references/review-stack.md must be byte-identical to the canonical mirror (run \`make copy-skills\`)`,
  )
})

// ---------------------------------------------------------------------------
// BOS-859. The degraded tier used to stop at DETECTION: it located must-fix findings at `file:line`
// and was then forbidden to fix them, so an otherwise finished run BLOCKED with pushed work
// stranded behind minutes of mechanical repair the tier had already specified precisely. It now
// gets ONE bounded repair round — eligibility-gated, affordability-gated, and witnessed by a fresh
// independent whole-branch reviewer that did not write the fix.
//
// The assertion class that matters most here is the HAND-OFF, not the prose: this exact tier once
// shipped a budget its dispatch brief never carried, with every prose gate green and three
// independent reviewers needed to catch it. A prose-presence pin on the clamp would not have caught
// that, so every leg below is asserted to state its own budget into the template slot.
// ---------------------------------------------------------------------------

// The repair pass is an H4 inside `### Degraded tier (minimal)`, so bound it at the next heading of
// ANY level at or above H3 — unbounded, `### BLOCKED-route publication` and the full tier's prose
// downstream would satisfy assertions the repair pass itself had lost.
const degradedRepairOf = (dir) => {
  const reviewStack = reviewStackFor(dir)
  const at = reviewStack.indexOf('#### Bounded repair pass (conditional)')
  assert.ok(at >= 0, `${dir}: review-stack.md must carry the bounded repair pass subsection`)
  const rest = reviewStack.slice(at + 1)
  const end = rest.search(/\n#{1,3} /)
  return end === -1 ? rest : rest.slice(0, end)
}

// The fix leg as a REGION — `**Fix leg.**` through `**Verification leg.**` — never a single
// paragraph. The fix leg is multi-paragraph, and a per-paragraph slice silently covers only the
// first: that exact narrowing shipped green against a fix-leg→`clean` route appended to the second
// paragraph. Region-slicing also closes the sibling hole where a mutant routes the fixer through the
// reviewer template without naming `DEGRADED_REPAIR_FIX_SECONDS`, which a constant-keyed paragraph
// filter would never see.
const sliceFixLeg = (repair) => {
  const from = repair.search(/\*\*Fix\s+leg\.\*\*/)
  assert.ok(from >= 0, 'the repair pass must carry a fix leg')
  const rest = repair.slice(from)
  const to = rest.search(/\*\*Verification\s+leg\.\*\*/)
  return to === -1 ? rest : rest.slice(0, to)
}

// The hard-ABORT set, as one run. Asserted as a single sequence rather than term-by-term so that
// dropping ONE term reds — a per-term `includes` would stay green on a set that silently lost
// `credentials` to a neighbouring word elsewhere in the section.
const HARD_ABORT_SET =
  /auth,\s+secrets,\s+credentials,\s+migrations,\s+production\/deploy\s+configuration,\s+dependencies,\s+or\s+an\s+observable\s+public\s+API\s+change/i

test('BOS-859: the degraded repair pass is eligibility-gated and cites the abort set unchanged (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const repair = degradedRepairOf(dir)

    // Both gates exist and are named. Two separate pins, not one distance window: the prose between
    // them grows, and a `[\s\S]{0,N}` span over it starts failing for reasons unrelated to the gate.
    assert.match(
      repair,
      /\*\*Eligibility\s+—\s+cited,\s+never\s+restated\.\*\*/i,
      `${dir}: the repair pass must carry an eligibility gate`,
    )
    assert.match(
      repair,
      /\*\*Affordability\s+gate\.\*\*/i,
      `${dir}: the repair pass must carry an affordability gate`,
    )

    // Eligibility is REUSED, not restated — two copies drift and the abort set is the costly half
    // to drift. Pin the citation of the full tier's predicate…
    assert.match(
      repair,
      /Mechanical\s+remediation\s+extension\s+\(after\s+the\s+default\s+cap\)/i,
      `${dir}: the repair pass must cite the full tier's mechanical-remediation eligibility predicate`,
    )
    // …and the abort set itself, in BOTH places: the citation would be worthless if the cited
    // predicate quietly lost a term, and the repair pass would be unsafe if its own copy did.
    assert.match(repair, HARD_ABORT_SET, `${dir}: the repair pass must carry the hard-ABORT set`)
    const extension = region(
      reviewStack,
      '### Mechanical remediation',
      '### API-surface check',
      `${dir}: review-stack.md`,
    )
    assert.match(
      extension,
      HARD_ABORT_SET,
      `${dir}: the cited mechanical-remediation predicate must keep the hard-ABORT set unchanged`,
    )

    // One ineligible finding disqualifies the WHOLE pass — a per-finding gate would let the tier
    // repair the easy half of a mixed set and then present a partially repaired branch for
    // verification, which is not the thing the verification round is evidence for.
    assert.match(
      repair,
      /\*\*One\*\*\s+ineligible\s+open\s+finding[\s\S]{0,120}disqualifies\s+the\s+whole\s+pass/i,
      `${dir}: a single ineligible finding must disqualify the entire repair pass`,
    )
    // …and Critical is never mechanical, exactly as the cited extension has it. Pin the EXCLUSION,
    // not the bare token: a mere /\*\*Critical\*\*/ presence check is satisfied by prose that says
    // the opposite ("…excluding any **Critical** one, which this pass MAY repair"), so it defends
    // nothing. Match the clause that actually disqualifies the pass.
    assert.match(
      repair,
      /including\s+any\s+\*\*Critical\*\*\s+one/i,
      `${dir}: the repair pass must exclude Critical findings, as the cited predicate does`,
    )
  }
})

test('BOS-859: the degraded repair pass is priced without moving the branch-2 floor (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const repair = degradedRepairOf(dir)

    // Named constants, in the DEGRADED_REPAIR_*_MINUTES shape, pinned as named numbers exactly as
    // `DEGRADED_REVIEWER_MINUTES = 10` is pinned above — both in the runnable clamp and beside the
    // prose that explains what each leg buys.
    for (const name of ['DEGRADED_REPAIR_FIX_MINUTES', 'DEGRADED_REPAIR_VERIFY_MINUTES']) {
      assert.match(
        repair,
        new RegExp(`${name}\\s*=\\s*10\\b`),
        `${dir}: ${name} must be priced as a named constant in the repair clamp`,
      )
      assert.match(
        repair,
        new RegExp('`' + name + '`\\s*\\(10\\)'),
        `${dir}: ${name} must be named beside its value in the prose, not only inside the clamp`,
      )
    }

    // THE FLOOR DID NOT MOVE. This is the gate that stops a later edit "tidying" the repair price
    // into the tier price: `DEGRADED_TIER_MINUTES` feeds the branch-2 floor, so folding either
    // constant in would lift that floor by 20 minutes and hand every run in the gap NO review at
    // all — strictly worse than the detect-only review this whole change exists to improve on.
    const tierPrice = region(
      reviewStack,
      'DEGRADED_TIER_MINUTES = $DEGRADED_REVIEWER_MINUTES',
      '# Review is NOT the last phase',
      `${dir}: review-stack.md`,
    )
    assert.doesNotMatch(
      tierPrice,
      /DEGRADED_REPAIR_/,
      `${dir}: the repair constants must NOT be summed into DEGRADED_TIER_MINUTES — that lifts the branch-2 floor`,
    )
    assert.match(
      repair,
      /Neither\s+is\s+summed\s+into\s+`DEGRADED_TIER_MINUTES`/i,
      `${dir}: the repair pass must say its constants stay out of the tier price`,
    )
    assert.match(
      repair,
      /branch-2\s+floor\s+stays\s+at\s+40/i,
      `${dir}: the repair pass must state that the branch-2 floor is unchanged`,
    )
  }
})

test('BOS-859: the degraded repair clamp is runnable and refuses a non-positive budget (both mirrors)', () => {
  // EXECUTED, not pattern-matched — the precedent in this file is that an executed gate catches the
  // unwritten/unmatchable pairs a regex over the same block sails past. A clamp that computes 0 for
  // every run reads identically to a correct one in prose.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const repair = degradedRepairOf(dir)

    const clamp = bashBlocksOf(repair).find((b) => /^DEGRADED_REPAIR_FIX_SECONDS=/m.test(b))
    assert.ok(clamp, `${dir}: the repair pass must ship an executable deadline clamp`)

    // Constants assigned above the arithmetic that reads them: the budget block near the top of the
    // file is a pricing FORMULA, not a script, so an unset name is ZERO inside `$(( ))`.
    const arithmeticAt = clamp.search(/^DEGRADED_REPAIR_FIX_SECONDS=/m)
    for (const name of [
      'DEGRADED_REPAIR_FIX_MINUTES',
      'DEGRADED_REPAIR_VERIFY_MINUTES',
      'DEGRADED_API_CHECK_MINUTES',
      'POST_REVIEW_RESERVE_MINUTES',
    ]) {
      const assignedAt = clamp.search(new RegExp(`^${name}=\\d+`, 'm'))
      assert.ok(
        assignedAt >= 0 && assignedAt < arithmeticAt,
        `${dir}: ${name} must be assigned in the repair clamp, above the arithmetic that reads it`,
      )
    }

    const fixMin = Number(/^DEGRADED_REPAIR_FIX_MINUTES=(\d+)/m.exec(clamp)?.[1])
    const verMin = Number(/^DEGRADED_REPAIR_VERIFY_MINUTES=(\d+)/m.exec(clamp)?.[1])
    const api = Number(/^DEGRADED_API_CHECK_MINUTES=(\d+)/m.exec(clamp)?.[1])
    const reserve = Number(/^POST_REVIEW_RESERVE_MINUTES=(\d+)/m.exec(clamp)?.[1])
    // The clamp's own constants must track the priced ones, not drift from them.
    assert.equal(
      api,
      Number(/DEGRADED_API_CHECK_MINUTES\s*=\s*(\d+)/.exec(reviewStack)?.[1]),
      `${dir}: the repair clamp's API allowance must equal the priced allowance`,
    )
    assert.equal(
      reserve,
      Number(/POST_REVIEW_RESERVE_MINUTES =[\s\S]{0,400}?=\s*(\d+) minutes/.exec(reviewStack)?.[1]),
      `${dir}: the repair clamp's reserve must equal the priced post-review reserve`,
    )

    const at = (minutes) => String(Math.floor(Date.now() / 1000) + minutes * 60)
    const fixSecs = (env) => Number(runBlock(clamp, env, '$DEGRADED_REPAIR_FIX_SECONDS').trim())
    const verSecs = (env) => Number(runBlock(clamp, env, '$DEGRADED_REPAIR_VERIFY_SECONDS').trim())

    // (a) No deadline set → the full priced allowances. Empty means "no cap", never zero.
    assert.equal(fixSecs({}), fixMin * 60, `${dir}: with no deadline the fix leg keeps its price`)
    assert.equal(
      verSecs({}),
      verMin * 60,
      `${dir}: with no deadline the verify leg keeps its price`,
    )

    // (b) Roomy deadline → allowances intact.
    const roomy = { PREFLIGHT_DEADLINE: at(reserve + api + verMin + fixMin + 5) }
    assert.equal(
      fixSecs(roomy),
      fixMin * 60,
      `${dir}: a roomy deadline must not shrink the fix leg`,
    )
    assert.equal(
      verSecs(roomy),
      verMin * 60,
      `${dir}: a roomy deadline must not shrink the verify leg`,
    )

    // (c) Squeezed → the fix leg clamps strictly below its allowance rather than spending the
    // verification, the API allowance, or the reserve.
    const squeezed = { PREFLIGHT_DEADLINE: at(reserve + api + verMin + fixMin - 6) }
    const gotFix = fixSecs(squeezed)
    assert.ok(
      gotFix > 0 && gotFix < fixMin * 60,
      `${dir}: a squeezed deadline must clamp the fix leg below its allowance, got ${gotFix}`,
    )

    // (d) THE REFUSAL. With only the reserve, the API allowance and the verification left there is
    // no fix time at all — and with only the reserve and the API allowance left, no verify time
    // either. A clamp that returns a positive number here funds an unbudgeted round out of the
    // post-review reserve, which is the mid-review overrun the whole tier ladder exists to prevent.
    assert.ok(
      fixSecs({ PREFLIGHT_DEADLINE: at(reserve + api + verMin) }) <= 0,
      `${dir}: the fix leg must go non-positive once only the verify, API and reserve allowances fit`,
    )
    assert.ok(
      verSecs({ PREFLIGHT_DEADLINE: at(reserve + api) }) <= 0,
      `${dir}: the verify leg must preserve the API allowance as well as the post-review reserve`,
    )

    // …and the prose must say what a non-positive budget means, or the arithmetic above is a number
    // nobody acts on.
    assert.match(
      repair,
      /Dispatch\s+a\s+leg\s+only\s+while\s+its\s+own\s+budget\s+is\s+\*\*positive\*\*/i,
      `${dir}: the repair pass must dispatch a leg only on a positive budget`,
    )
    assert.match(
      repair,
      /non-positive\s+budget\s+is\s+neither\s+a\s+clean\s+exit\s+nor\s+a\s+licence\s+for\s+an\s+unbudgeted\s+round/i,
      `${dir}: a non-positive repair budget must be neither a clean exit nor an unbudgeted round`,
    )
  }
})

test('BOS-859: both repair legs state their budget into the dispatch template slot (both mirrors)', () => {
  // THE HAND-OFF GATE. A budget its holder never states to the worker is inert while every other
  // instruction still reads as satisfied — this tier has shipped exactly that bug, and every prose
  // gate stayed green through it. Assert PER LEG and PER PARAGRAPH: one shared mention somewhere in
  // the section would let a mutant drop either leg's budget and stay green.
  //
  // The CARRIER differs per leg, and that is the invariant — not "both legs fill the template".
  // code-reviewer-template.md is a whole read-only REVIEWER brief that forbids mutating the tree, so
  // routing the FIX leg through its [TIME_BUDGET_SECONDS] slot dispatches a fixer forbidden to fix:
  // both legs' budget burns on a repair that can never land, which is worse than detect-only. The
  // rule is that every leg states its own budget to its own worker, in the carrier its brief allows.
  for (const dir of BUILD_MIRRORS) {
    const repair = degradedRepairOf(dir)
    const paragraphs = repair.split(/\n\s*\n/)

    // The FIX leg states its budget as PROSE, in its own paragraph, and never through the slot.
    const fixStated = paragraphs.filter(
      (p) => p.includes('DEGRADED_REPAIR_FIX_SECONDS') && /HARD\s+TIME\s+BUDGET/i.test(p),
    )
    assert.ok(
      fixStated.length > 0,
      `${dir}: the fix leg must state DEGRADED_REPAIR_FIX_SECONDS to its worker as a prose HARD TIME BUDGET in its own paragraph`,
    )
    // Scoped to the fix-leg REGION, not to paragraphs naming the constant: a mutant that routes the
    // fixer through the template WITHOUT naming DEGRADED_REPAIR_FIX_SECONDS would never appear in a
    // constant-keyed filter, and the fix leg is multi-paragraph so a per-paragraph slice covers only
    // its first. The one legitimate mention of the slot inside the region is the sentence that
    // REFUSES it, so match the refusal explicitly and forbid every other occurrence.
    const fixRegion = sliceFixLeg(repair)
    const slotMentions = fixRegion.match(/\[TIME_BUDGET_SECONDS\]/g) ?? []
    assert.match(
      fixRegion,
      /\*\*not\*\*\s+through\s+the\n?\[code-reviewer\s+prompt\s+template\]/i,
      `${dir}: the fix-leg region must explicitly refuse the reviewer template as its budget carrier`,
    )
    assert.ok(
      slotMentions.length <= 1,
      `${dir}: the fix leg must NOT carry its budget in the read-only reviewer template's [TIME_BUDGET_SECONDS] slot — that brief forbids mutating the tree`,
    )
    // …and the section must say so explicitly, so the next editor does not "restore symmetry".
    assert.match(
      repair,
      /read-only\s+_?reviewer_?\s+brief/i,
      `${dir}: the repair pass must state WHY the fix leg does not use the reviewer template (it is a read-only reviewer brief)`,
    )

    // The VERIFICATION leg is a reviewer, so it does fill the shared template's slot.
    const verifyStated = paragraphs.filter(
      (p) => p.includes('DEGRADED_REPAIR_VERIFY_SECONDS') && p.includes('[TIME_BUDGET_SECONDS]'),
    )
    assert.ok(
      verifyStated.length > 0,
      `${dir}: the verification leg must hand DEGRADED_REPAIR_VERIFY_SECONDS to the template's [TIME_BUDGET_SECONDS] slot in its own paragraph`,
    )
    // The slot is a real hand-off into the shared template, not a name invented here.
    assert.match(
      repair,
      /code-reviewer-template\.md/,
      `${dir}: the verification leg must brief through the shared code-reviewer template`,
    )
  }
})

test('BOS-859: the tier lead bullet scopes "exactly one" to detection, not to its reviewer count', () => {
  // RESIDUAL-PROSE GATE. The tier's opening bullet described a detect-only tier: "Exactly one
  // awaited, read-only whole-branch reviewer". Once a repaired branch is read by the verification
  // leg the tier can dispatch TWO, and the unqualified sentence becomes a false cap that a reader
  // reaching this section first would enforce over the repair pass below — the same stale-lead
  // failure the rewrite already had to clear five times elsewhere in this subsection.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const at = reviewStack.indexOf('### Degraded tier (minimal)')
    assert.ok(at >= 0, `${dir}: review-stack.md must carry the degraded tier subsection`)
    // Slice to the NEXT bullet, not a character window: a distance window starts failing when the
    // prose it spans grows, which reds for a prose-growth reason rather than a defect one.
    const afterHeading = reviewStack.slice(at)
    const nextBullet = afterHeading.search(/\n- \*\*Detection\s+is\s+a\s+single\s+round\.\*\*/)
    const lead = nextBullet === -1 ? afterHeading.slice(0, 1200) : afterHeading.slice(0, nextBullet)

    // "Exactly one" must be bound to DETECTION, not left as a bare reviewer count.
    assert.match(
      lead,
      /\*\*Exactly\s+one\*\*\s+awaited,\s+read-only\s+whole-branch\s+\*\*detection\*\*\s+reviewer/i,
      `${dir}: the lead bullet's "exactly one" must be scoped to the detection reviewer`,
    )
    // …and the bullet must acknowledge the second reviewer a repaired branch gets, so the cap is
    // not re-read as the tier's total.
    assert.match(
      lead,
      /"Exactly\s+one"\s+bounds\s+detection,\s+never\s+the\s+tier'?s?\s+reviewer\s+count/i,
      `${dir}: the lead bullet must say "exactly one" bounds detection, never the tier's reviewer count`,
    )
  }
})

test('BOS-859: the reviewer template refuses to carry a fix leg budget (both mirrors)', () => {
  // The other half of the same defect: review-stack.md can be correct while the template still
  // advertises itself as the carrier for every budget. Pin the refusal at the template end too, so
  // neither file can drift back on its own.
  for (const dir of BUILD_MIRRORS) {
    const template = fs.readFileSync(
      path.join(rootDir, dir, 'references/code-reviewer-template.md'),
      'utf8',
    )
    assert.match(
      template,
      /DEGRADED_REPAIR_VERIFY_SECONDS/,
      `${dir}: the [TIME_BUDGET_SECONDS] slot must name the degraded repair verification leg as one of its suppliers`,
    )
    assert.match(
      template,
      /\*\*never\*\*\s+a\s+fix\s+leg'?s?\s+budget/i,
      `${dir}: the template must state that [TIME_BUDGET_SECONDS] is never a fix leg's budget`,
    )
    assert.match(
      template,
      /DEGRADED_REPAIR_FIX_SECONDS/,
      `${dir}: the template must name DEGRADED_REPAIR_FIX_SECONDS as a budget it does NOT carry`,
    )
  }
})

test('BOS-859: only an independent verification round may write clean on a repaired branch (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const repair = degradedRepairOf(dir)
    const paragraphs = repair.split(/\n\s*\n/)

    // The verification leg is FRESH, INDEPENDENT, WHOLE-BRANCH, and knows its own purpose. Drop any
    // of those and the "independent witness" that justifies repair at all stops existing.
    assert.match(
      repair,
      /Dispatch\s+\*\*one\*\*\s+fresh\s+independent\s+reviewer\s+over\s+`\$REVIEW_BASE\.\.\.HEAD`/i,
      `${dir}: verification must be one fresh independent reviewer over the whole branch`,
    )
    assert.match(
      repair,
      /\*\*verifying\s+fixes\s+it\s+did\s+not\s+write\*\*/i,
      `${dir}: the verification brief must name its verify-what-it-did-not-write purpose`,
    )
    // The tier's did-not-report rule is inherited VERBATIM: a verifier that produced nothing is not
    // a verifier that found nothing. Without this the cheapest possible failure — a dead dispatch —
    // reads as zero must-fix on a branch that was just modified.
    assert.match(
      repair,
      /verifier\s+that\s+errored,\s+timed\s+out,\s+or\s+returned\s+nothing\s+structured\s+is\s+\*\*not\*\*\s+a\s+verifier\s+that\s+found\s+zero\s+must-fix/i,
      `${dir}: a verifier that did not report must not be read as zero must-fix`,
    )

    // THE CLEAN EDGE. On a repaired branch there is exactly one route to `clean`, and it is
    // downstream of the reviewer that did not write the fix.
    assert.match(
      repair,
      /On\s+a\s+\*\*repaired\*\*\s+branch,\s+only\s+the\s+verification\s+reviewer\s+returning\s+\*\*zero\*\*\s+must-fix\s+writes\s+`bs-review\s+clean:`/i,
      `${dir}: only the verification reviewer may write clean on a repaired branch`,
    )
    assert.match(
      repair,
      /fixed-but-unverified\s+finding\s+is\s+a\s+\*\*capped\*\*\s+run,\s+not\s+a\s+clean\s+one/i,
      `${dir}: a fixed-but-unverified finding must route capped, not clean`,
    )
    // …and the pre-existing route is untouched: a detection reviewer finding zero must-fix still
    // reaches clean with no repair round, because there is nothing to verify.
    assert.match(
      repair,
      /detection\s+reviewer\s+that\s+found\s+zero\s+must-fix\s+reaches\s+`clean`\s+without\s+any\s+repair\s+round/i,
      `${dir}: the pre-existing zero-must-fix route must be preserved unchanged`,
    )

    // STRUCTURAL, not prose: the fix leg must not name the clean sentinel anywhere. This is the
    // property the control flow rests on — no path reaches clean from the fix leg directly.
    //
    // Slice the fix-leg REGION (`**Fix leg.**` through `**Verification leg.**`), never a single
    // paragraph. A paragraph-scoped version of this gate shipped green against a direct violation:
    // the fix leg is TWO paragraphs, and appending a `bs-review clean:` route to the second one
    // left the whole suite passing. Any edit that splits a leg silently halves a per-paragraph
    // gate's coverage, and the split is exactly what an editor does while "clarifying" prose.
    const fixLegRegion = sliceFixLeg(repair)
    assert.ok(
      /\*\*Fix\s+leg\.\*\*/.test(fixLegRegion),
      `${dir}: the repair pass must carry a fix leg`,
    )
    assert.doesNotMatch(
      fixLegRegion,
      /bs-review\s+clean:/,
      `${dir}: the fix leg may never reach the clean sentinel directly`,
    )
    // The capped route stays the GENERATED one; a hand-written literal is unmatchable and silently
    // downgrades the terminal state to `dispatch-failure`.
    assert.match(
      repair,
      /sentinel\s+capped\s+<N>[\s\S]{0,80}bs-run-sentinel\.mjs\s+write/i,
      `${dir}: the repair pass must route through the generated-and-persisted capped sentinel`,
    )
    // Exhaustion is a decision to stop paying, never a re-triage of the findings into noise.
    assert.match(
      repair,
      /record\s+every\s+unresolved\s+finding\s+by\s+`file:line`\s+and\s+BLOCK/i,
      `${dir}: an exhausted repair pass must record its unresolved findings and BLOCK`,
    )
  }
})

test('BOS-859: the degraded coverage token distinguishes a repaired run from a detect-only one', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    // A SUFFIX parenthetical, not an infix edit: the existing `degraded: <reason> (skipped: <pass
    // list>)` shape is pinned by its literal form above, so the repair outcome is appended.
    assert.match(
      reviewStack,
      /\(repaired:\s+<N>\s+finding\(s\),\s+verified\s+by\s+one\s+independent\s+whole-branch\s+reviewer\)/,
      `${dir}: a repaired degraded run must publish its repair outcome in the coverage token`,
    )
    // …and it must stop claiming it skipped the pass it just ran.
    assert.match(
      reviewStack,
      /drop\s+the\s+fix→re-review\s+loop\s+from\s+the\s+skipped\s+list/i,
      `${dir}: a repaired run's coverage token must not list the fix→re-review loop as skipped`,
    )
    // A repair pass that RAN and did not clear verification also "actually ran", so a token keyed
    // only on "ran" would publish `verified by one independent whole-branch reviewer` on the
    // BLOCKED route — an over-claim in the one section whose whole purpose is honesty, and a
    // reachable one, since §BLOCKED-route publication publishes on exactly that route. Pin the
    // separate failure form.
    assert.match(
      reviewStack,
      /\(repair\s+attempted:\s+<N>\s+finding\(s\),\s+verification\s+did\s+not\s+clear:\s+<outcome>\)/,
      `${dir}: a repaired-but-unverified degraded run must publish a distinct, non-over-claiming coverage token`,
    )
    // The sentinel's round count is not the same on both routes. The top-of-file rule prices the
    // degraded tier at exactly one round; once a repair round can run, a repaired-but-unverified
    // run reached two, and a reader falling back to the stale parenthetical emits `1` for it.
    assert.match(
      reviewStack,
      /`2`\s+once\s+the\s+fix\s+leg\s+was\s+dispatched\s+—\s+the\s+detection\s+round\s+plus\s+this\s+repair\s+round/i,
      `${dir}: the repaired capped route must state its own sentinel round count, not inherit the detect-only 1`,
    )
    // …and the COUNT IS COUNTED, not read off the paragraph that routed here. The eligibility and
    // affordability gate-outs both jump into the clean edge's capped command while having reached
    // only the detection round, so a flat `2` there over-reports a repair round that never ran.
    assert.match(
      reviewStack,
      /`1`\s+when\s+the\s+pass\s+never\s+started/i,
      `${dir}: a gated-out repair pass must emit the detection-only round count, not the repaired 2`,
    )
  }
})

test('BOS-758: Step 7 PR body requires a `## Review coverage` section (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const body = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')

    // Step 6 must point a reader at where the tier is chosen, or the body reads as if the full
    // stack is the only stack.
    const step6 = region(body, '## Step 6: Whole-branch review', '## Step 7:')
    assert.match(
      step6,
      /tier/i,
      `${dir}/SKILL.md Step 6 must point at the review-stack tier selection`,
    )

    const step7 = region(body, '## Step 7:', '## Steps 8-12:')
    assert.match(
      step7,
      /^## Review[ ]coverage$/m,
      `${dir}/SKILL.md Step 7 PR-body template must carry a \`## Review coverage\` section`,
    )
    // Same never-omit rule the `## Cross-model review` section carries: silence must not read as
    // full coverage.
    assert.match(
      step7,
      /`## Review\s+coverage`[\s\S]{0,400}never\s+omit\s+it/i,
      `${dir}: the \`## Review coverage\` section must carry the never-omit rule`,
    )
    assert.match(
      step7,
      /`## Review\s+coverage`[\s\S]{0,400}missing\s+section[\s\S]{0,120}full\s+coverage/i,
      `${dir}: a missing \`## Review coverage\` section must not read as full coverage`,
    )
    // Pin `**replace** both`, not a bare `**replace**`: the resume rule is shared prose covering
    // BOTH sections, and the `## Cross-model review` sentence already supplies a `**replace**`
    // inside the window. A gate anchored on the bare word stayed green against a mutant reading
    // "**replace** the cross-model section ...; **append** the coverage section" — i.e. it was
    // satisfied by text instructing the exact behaviour it exists to forbid.
    assert.match(
      step7,
      /`## Review\s+coverage`[\s\S]{0,500}\*\*replace\*\* both/i,
      `${dir}: \`## Review coverage\` must be replaced, not appended, on a resume`,
    )
    // …and no *positive* instruction to append it. Rejecting a bare /append/ would fire on the
    // legitimate "replace both rather than appending a duplicate", so drop the sanctioned
    // rather-than/instead-of forms first and require nothing to survive: what remains would be an
    // instruction to append, which is what the mutant added.
    // Slice FIRST, then replace: an index taken from `step7` is meaningless against the shortened
    // post-replacement string, and every sanctioned phrase removed ahead of the heading would drag
    // the window start forward and silently eat the head of the coverage section.
    const step7Appends = region(step7, '## Review coverage').replace(
      /(?:rather\s+than|instead\s+of|never|not)\s+append(?:ing|s|ed)?/gi,
      '',
    )
    assert.doesNotMatch(
      step7Appends,
      /\bappend(?:ing|s|ed)?\b/i,
      `${dir}: Step 7 must never instruct appending the \`## Review coverage\` section`,
    )
  }
})

test('BOS-758 P1: the pre-dispatch floor completes the reference push procedure before its capped sentinel (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const skill = readSkill(`${dir}/SKILL.md`)
    const floorStart = skill.indexOf('Apply the tier ladder’s budget floor')
    const fallbackStart =
      floorStart >= 0 ? floorStart : skill.indexOf("Apply the tier ladder's budget floor")
    const floorEnd = skill.indexOf('**What comes back', fallbackStart)
    assert.ok(
      fallbackStart >= 0 && floorEnd > fallbackStart,
      `${dir}/SKILL.md: Step 6 must bound the pre-dispatch floor route`,
    )

    const floor = skill.slice(fallbackStart, floorEnd)
    assert.match(
      floor,
      /references\/review-stack\.md[\s\S]{0,160}BLOCKED-route\s+publication[\s\S]{0,220}retry\/rebase\/rescue\s+procedure\s+must\s+yield `PUSHED=yes` before[\s\S]{0,120}`capped\s+1` sentinel/i,
      `${dir}/SKILL.md: the below-floor route must complete the reference retry/rebase/rescue procedure with PUSHED=yes before its generated capped 1 sentinel`,
    )
    assert.doesNotMatch(
      floor,
      /git\s+push\s+-u\s+origin\s+"\$SESSION_BRANCH"/,
      `${dir}/SKILL.md: the below-floor route must delegate its durable push procedure to the reference, not regress to a one-shot inline push`,
    )
    assert.match(
      floor,
      /do\s+(?:\*\*)?not(?:\*\*)?\s+fall\s+through[\s\S]{0,180}(?:generic|classifier|Step\s+7)/i,
      `${dir}/SKILL.md: the below-floor route must stop before generic sentinel classification`,
    )
    assert.match(
      floor,
      /publish\s+both\s+tokens, then\s+exit\s+cleanly\s+BLOCKED/i,
      `${dir}/SKILL.md: the below-floor route must explicitly exit after publication, not merely describe a terminal state`,
    )
  }
})

test('BOS-758 P1: every pre-Step-7 BLOCKED route pushes before it exits (both mirrors)', () => {
  // Step 7 is the ONLY step that runs `git push -u origin`, and Step 12 (Stop cleanly) deletes the
  // claim, drops the stop-hooks and releases the lock without pushing. Three routes stop at Step 12
  // WITHOUT passing Step 7 — the Step 6 budget floor, `capped`, and `dispatch-failure` — and all
  // three are reachable only AFTER Step 6 committed. Exiting on any of them unpushed strands
  // finished commits in a worktree that is later destroyed, violating the repo's completion
  // invariant. Pin the push on the shared section AND on both readers that route into it.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const skill = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')

    // Bound the window at the section heading so a push mentioned anywhere else cannot satisfy it.
    const secIdx = reviewStack.indexOf('### BLOCKED-route publication')
    assert.ok(
      secIdx >= 0,
      `${dir}: review-stack.md must carry the BLOCKED-route publication section`,
    )
    // Bound at the NEXT heading, not a magic byte count: the section grows as the rule is
    // hardened, and a fixed window silently starts excluding the clauses it is meant to pin.
    const secEndRel = reviewStack.slice(secIdx + 1).search(/\n#{2,3} /)
    const section = reviewStack.slice(
      secIdx,
      secEndRel === -1 ? reviewStack.length : secIdx + 1 + secEndRel,
    )

    assert.match(
      section,
      /git[ ]push[ ]-u[ ]origin[ ]"\$SESSION_BRANCH"/,
      `${dir}: the BLOCKED-route section must push the session branch before the terminal exit`,
    )
    // It must cover ALL THREE routes, not just the one the review flagged — the rationale
    // ("Step 7 is the only step that pushes") applies verbatim to the other two.
    assert.match(
      section,
      /all\s+three[\s\S]{0,300}budget\s+floor[\s\S]{0,140}`capped`[\s\S]{0,140}`dispatch-failure`/i,
      `${dir}: the push rule must apply to the budget-floor, capped, and dispatch-failure routes alike`,
    )
    // A bare `git push || echo` turns a failed push into a SUCCESSFUL command and walks on to
    // Step 12 with the commits still stranded — the very outcome the rule exists to prevent,
    // wearing a reassuring log line. The push must be retried, reconciling with rebase (never a
    // merge) between attempts, and the echo may only fire after the retries are exhausted.
    assert.match(
      section,
      /while \[ "\$attempts" -lt \d+ \][\s\S]{0,900}git[ ]rebase --no-fork-point[ ]FETCH_HEAD/,
      `${dir}: the BLOCKED-route push must retry and reconcile, not swallow the failure`,
    )
    assert.match(
      section,
      /last\s+resort \*\*after\*\* the\s+retries, never\s+a\s+substitute\s+for\s+them/i,
      `${dir}: the section must forbid treating the failure echo as the push itself`,
    )
    // `git pull --rebase … || break` is the same defect one level down: a transient reconcile
    // failure ends the loop after ONE push attempt while the message still claims three. The
    // reconcile must not terminate the loop, and any half-finished rebase must be aborted so the
    // next attempt starts clean.
    // Assert the CODE, not the prose: the section deliberately quotes the forbidden
    // `git pull --rebase … || break` shape to explain why it is wrong, so a negative assertion
    // over the whole section would fire on its own documentation.
    const pushBlock = [...section.matchAll(/```bash\n([\s\S]*?)```/g)]
      .map((m) => m[1])
      .find((b) => /git[ ]push -u[ ]origin/.test(b))
    assert.ok(pushBlock, `${dir}: the push rule must ship a runnable bash block`)
    // Matched against whichever reconcile form ships, so the rule survives a change of idiom —
    // the defect is `|| break` after the reconcile, not the particular git invocation.
    assert.doesNotMatch(
      pushBlock,
      /git (?:pull --rebase|rebase --no-fork-point)[^\n]*\|\|\s*break/,
      `${dir}: a failed reconcile must not end the push loop after a single attempt`,
    )
    assert.match(
      pushBlock,
      /git[ ]rebase --no-fork-point[ ]FETCH_HEAD \|\|\s*git[ ]rebase --abort/,
      `${dir}: a failed reconcile must abort any half-finished rebase and let the loop continue`,
    )
    // The reported attempt count must come from a counter, never a literal that can drift from
    // the number of attempts actually made.
    assert.doesNotMatch(
      pushBlock,
      /FAILED\s+after \d+ attempt/,
      `${dir}: the failure message must not hard-code an attempt count it cannot verify`,
    )
    assert.match(
      pushBlock,
      /FAILED[ ]after \$\{?attempts\}? attempt/,
      `${dir}: the failure message must report the counter's value`,
    )
    // The retry must span a real WINDOW, not three back-to-back failures: an outage that clears
    // in a minute must not cost the run its commits.
    assert.match(
      pushBlock,
      /sleep "\$delay"[\s\S]{0,120}delay=\$\(\(\s*delay \* 2\s*\)\)/,
      `${dir}: the push retry must back off, or the "window" is milliseconds wide`,
    )
    // Retrying cannot fix a DIVERGED ref however long it runs. A unique rescue ref is a create,
    // not a fast-forward, so it cannot be rejected for divergence — this is what actually stops
    // the commits dying with the worktree, and it is why the loop may be bounded at all.
    assert.match(
      pushBlock,
      /git[ ]push[ ]origin "HEAD:refs\/heads\/\$RESCUE"/,
      `${dir}: an unpushable session branch must fall back to a rescue ref, not to a local-SHA report`,
    )
    assert.match(
      section,
      /Locally-recorded\s+SHAs\s+are\s+a\s+poor\s+terminal\s+outcome/i,
      `${dir}: the section must push rather than settle for local SHAs`,
    )
    // The rule must NOT justify itself with "the worktree is about to be deleted" — Stop cleanly
    // does not delete it, and finalize pushes committed work / preserves the worktree when it
    // cannot. A false rationale invites a later round to "fix" cleanup by blocking Step 12, which
    // would hold the lock open forever and starve the very component that retries the push.
    assert.match(
      section,
      /Stop\s+cleanly\s+does\s+not\s+delete\s+the\s+worktree/i,
      `${dir}: the section must state that Stop cleanly does not delete the worktree`,
    )
    assert.match(
      section,
      /Do \*\*not\*\* refuse\s+to\s+reach\s+Step\s+12/i,
      `${dir}: an unpushable remote must not block terminal cleanup`,
    )
    // None of these routes rewrote history, so a force-push here would clobber a commit this run
    // did not author. The section must forbid it rather than leave the choice open.
    assert.match(
      section,
      /never\s+`--force`\/`--force-with-lease`|never\s+`--force`/i,
      `${dir}: the BLOCKED-route push must be plain, with force explicitly forbidden`,
    )

    // Reader 1: the budget-floor branch in the tier ladder.
    const floorIdx = reviewStack.indexOf(
      '**< `DEGRADED_TIER_MINUTES + POST_REVIEW_RESERVE_MINUTES`**',
    )
    assert.ok(floorIdx >= 0, `${dir}: review-stack.md must carry the budget-floor branch`)
    assert.match(
      reviewStack.slice(floorIdx, floorIdx + 900),
      /push\s+the\s+branch\s+first|push\s+the\s+session\s+branch/i,
      `${dir}: the budget-floor branch must tell its reader to push before exiting`,
    )

    // Reader 2: Step 6's pre-dispatch floor gate in SKILL.md, which is where the orchestrator
    // actually takes this exit.
    const gateIdx = skill.indexOf('Apply the tier ladder’s budget floor')
    const gateAt = gateIdx >= 0 ? gateIdx : skill.indexOf("Apply the tier ladder's budget floor")
    assert.ok(gateAt >= 0, `${dir}/SKILL.md: Step 6 must carry the budget-floor gate`)
    const floorGate = skill.slice(gateAt, gateAt + 900)
    assert.match(
      floorGate,
      /references\/review-stack\.md[\s\S]{0,160}BLOCKED-route\s+publication[\s\S]{0,220}retry\/rebase\/rescue\s+procedure\s+must\s+yield `PUSHED=yes` before[\s\S]{0,120}`capped\s+1` sentinel/i,
      `${dir}/SKILL.md: the Step 6 floor gate must complete the reference-backed push procedure before emitting capped/BLOCKED`,
    )
    assert.doesNotMatch(
      floorGate,
      /git\s+push\s+-u\s+origin\s+"\$SESSION_BRANCH"/,
      `${dir}/SKILL.md: the Step 6 floor gate must not replace the retry/rebase/rescue procedure with a one-shot inline push`,
    )
  }
})

test('BOS-758 P2: untimed fallback dispatches carry an execution bound, not just an entry gate', () => {
  // The admission gate can refuse to START an overrun but cannot stop one already running: an
  // awaited leg is not preemptible. Tier 1 has a second bound (BOSS_SKILL_EXTENSION_TIMEOUT_MS);
  // the Tier-2/Tier-3 fallbacks had none, so a slow fallback ran past the caller's deadline with
  // every gate still reading as satisfied. ARITHMETIC, not prose-pinning: lift the clamp out of
  // the shipped markdown and run it.
  //
  // ONE clock for both sides — see frozenClockPath() above. The clamp reads the wall clock itself
  // (`now=$(date +%s)`, exactly once, its only external command) while the deadline handed to it
  // is computed here, so without the shadow the answer is `remaining - spawn_latency` and the
  // assertions below could only be tolerances. Frozen, they are exact equality.
  const frozenPath = frozenClockPath()

  for (const dir of BUILD_MIRRORS) {
    const reviewSkill = fs.readFileSync(
      path.join(rootDir, dir.replace(/boss-build$/, 'boss-review'), 'SKILL.md'),
      'utf8',
    )
    const clamp = [...reviewSkill.matchAll(/```bash\n([\s\S]*?)```/g)]
      .map((m) => m[1])
      .find((b) => /^LEG_TIMEOUT_SECONDS=/m.test(b))
    assert.ok(clamp, `${dir}: boss-review must derive a per-dispatch LEG_TIMEOUT_SECONDS`)

    const budget = (remaining) => {
      // Supply the deadline the way `boss-build` documents it — under `STEP_6C_DEADLINE`. Setting a
      // bare `deadline` here would prove nothing about the hand-off, only about the arithmetic.
      const env = {
        ...process.env,
        DEADLINE_LEG_SECONDS: '300',
        deadline: '',
        PATH: frozenPath,
      }
      if (remaining !== null) {
        env.STEP_6C_DEADLINE = String(FROZEN_EPOCH + remaining)
      } else delete env.STEP_6C_DEADLINE
      return Number(
        execFileSync('bash', ['-c', `${clamp}\necho "$LEG_TIMEOUT_SECONDS"`], {
          encoding: 'utf8',
          env,
        }).trim(),
      )
    }

    assert.equal(budget(null), 300, `${dir}: with no caller deadline the bound is a full leg`)
    assert.equal(budget(3600), 300, `${dir}: a large budget is still capped at one leg`)
    // THE REPORTED DEFECT: less clock than a leg must shrink the dispatch, not admit a full one.
    // Exact, because the clock is frozen: 120s left budgets 120s, to the second.
    assert.equal(
      budget(120),
      120,
      `${dir}: with 120s left the dispatch must be bounded at exactly 120s, not a full 300s leg`,
    )
    assert.equal(budget(300), 300, `${dir}: exactly one leg remaining budgets exactly one leg`)

    // Every untimed fallback dispatch site must actually carry the bound.
    for (const tier of [
      '### Tier 2 — the lens entry',
      '### Tier 2 — host-native whole-diff review',
      '### Tier 3 — inline whole-diff rubric',
    ]) {
      const at = reviewSkill.indexOf(tier)
      assert.ok(at >= 0, `${dir}: boss-review must carry "${tier}"`)
      assert.match(
        reviewSkill.slice(at, at + 700),
        /`LEG_TIMEOUT_SECONDS`/,
        `${dir}: ${tier} is an untimed dispatch and must be bounded by LEG_TIMEOUT_SECONDS`,
      )
    }

    // The bound is only real if it reaches the worker.
    assert.match(
      reviewSkill,
      /HARD[ ]TIME[ ]BUDGET: <LEG_TIMEOUT_SECONDS> seconds[\s\S]{0,400}return/i,
      `${dir}: the reviewer template must state the budget to the worker as a hard return-by`,
    )
  }
})

test('BOS-758 P1b: the degraded reviewer is bounded on the wall clock, not just round count', () => {
  // The degraded tier is selected exactly when the clock is short (as low as the 40-minute floor).
  // A round cap of one is not a time bound: one hung awaited reviewer eats the whole 25-minute
  // post-review reserve, recreating the mid-review overrun at the tier meant to escape it.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const at = reviewStack.indexOf('### Degraded tier (minimal)')
    assert.ok(at >= 0, `${dir}: review-stack.md must carry the degraded tier section`)
    const degradedRest = reviewStack.slice(at)
    const degradedEnd = degradedRest.search(/\n## /)
    const section = degradedEnd === -1 ? degradedRest : degradedRest.slice(0, degradedEnd)
    assert.match(
      section,
      /`DEGRADED_REVIEWER_MINUTES`\s*\(10\)/,
      `${dir}: the degraded reviewer must be bounded at its ten-minute allowance`,
    )
    assert.match(
      section,
      /round\s+cap\s+of\s+one\s+is\s+not\s+a\s+time\s+bound/i,
      `${dir}: the degraded tier must say why a round cap does not bound the clock`,
    )
    // Expiry must land on the documented non-clean outcome, never a clean exit.
    assert.match(
      section,
      /on\s+expiry[\s\S]{0,220}`bs-review\s+capped:`[\s\S]{0,60}BLOCKED/i,
      `${dir}: a degraded reviewer stopped by its budget must route to capped/BLOCKED, never clean`,
    )
    assert.match(
      section,
      /`DEGRADED_API_CHECK_MINUTES`\s*\(5\)[\s\S]{0,420}15-minute\s+degraded-tier\s+price[\s\S]{0,220}re-measure[\s\S]{0,220}`PREFLIGHT_DEADLINE`[\s\S]{0,260}non-positive\s+clamp[\s\S]{0,120}BLOCKED/i,
      `${dir}: the conditional degraded API check must be priced, deadline-clamped, and fail closed`,
    )

    // BOS-737: this file carried three byte-identical copies of a hand-rolled
    // `apiStart >= 0 && apiEnd > apiStart` guard around the same extraction. `regionUntilNext()`
    // IS that form — the end marker searched from after the start — and it fails closed with a
    // message naming the heading that moved, which the guard's message could not. Checked per
    // site rather than assumed: against both mirrors' review-stack.md the extracted region is
    // byte-identical to the raw `slice(apiStart, indexOf('## Step 6b:', apiStart))` it replaces.
    // Labelled, per `region()`'s `@param label`: all three copies run inside a mirror loop, so an
    // unlabelled throw would name the heading that moved but not the mirror it moved in.
    const apiGate = regionUntilNext(
      reviewStack,
      '### API-surface check (conditional, required',
      '## Step 6b:',
      `${dir}/references/review-stack.md`,
    )
    const clamp = bashBlocksOf(apiGate).find((block) => /^API_CHECK_SECONDS=/m.test(block))
    assert.ok(clamp, `${dir}: the API gate must ship an executable degraded-tier deadline clamp`)
    assert.match(
      clamp,
      /DEGRADED_API_CHECK_MINUTES \* 60[\s\S]{0,320}PREFLIGHT_DEADLINE[\s\S]{0,320}POST_REVIEW_RESERVE_MINUTES \* 60/,
      `${dir}: the API clamp must price its own allowance and protect the post-review reserve`,
    )
    assert.match(
      apiGate,
      /only\s+while `API_CHECK_SECONDS` is\s+positive[\s\S]{0,220}capped\s+sentinel\s+and\s+BLOCKED\s+route/i,
      `${dir}: an expired required API gate must fail closed through capped/BLOCKED`,
    )
  }
})

test('BOS-758 P2b: the fallback bound is described as cooperative, not as a hard kill', () => {
  // The dispatch signature exposes no timeout and an awaited call cannot be preempted, so
  // LEG_TIMEOUT_SECONDS (and BOSS_SKILL_EXTENSION_TIMEOUT_MS) are cooperative budgets. Claiming
  // otherwise is the same unenforceable-cap defect one level up, and invites a future round to
  // "fix" it with a watchdog the harness cannot host.
  for (const dir of BUILD_MIRRORS) {
    const reviewSkill = fs.readFileSync(
      path.join(rootDir, dir.replace(/boss-build$/, 'boss-review'), 'SKILL.md'),
      'utf8',
    )
    assert.match(
      reviewSkill,
      /can\s+\*\*stop\*\*\s+a\s+worker\s+that\s+ignores\s+it[\s\S]{0,120}\*\*cooperative\*\*/i,
      `${dir}: boss-review must state that the fallback budget is cooperative, not a hard kill`,
    )
    assert.match(
      reviewSkill,
      /do\s+not\s+try\s+to "strengthen" this\s+with\s+an\s+external\s+watchdog/i,
      `${dir}: boss-review must rule out a watchdog an awaited dispatch cannot host`,
    )
    assert.match(
      reviewSkill,
      /admission\s+gate[\s\S]{0,320}clamp/i,
      `${dir}: boss-review must name the two controls that ARE enforceable`,
    )
  }
})

test('BOS-758 P2: the tier formula derives Step 6b from the configured cross-review timeout', () => {
  // The formula priced Step 6b at a flat `+ 10` — one review. Step 6b is a CHAIN: the Codex leg is
  // bounded by BOSS_CROSS_REVIEW_TIMEOUT_MS (skills-toolbox/codex-review.mjs resolveTimeoutMs,
  // default 300000 ms) and NOTHING else, and a Codex pass that times out or fails does not end the
  // step — review-stack.md's own §1 dispatches a separate awaited fallback reviewer after it. So a
  // 30-minute timeout can outspend the entire 25-minute post-review reserve inside a tier the
  // ladder just classified as affordable. Pin the DERIVATION, not a new constant.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const tierSelection = region(
      reviewStack,
      '## Step 6 entry — review tier selection',
      '## Step 6: Whole-branch review loop',
    )
    // `\s+` between words, never a literal space — this prose is hand-wrapped near 100 columns and
    // any of these phrases can break across a line on the next edit.
    for (const [pattern, why] of [
      [
        /STEP_6B_MINUTES\s*=\s*\$CODEX_TIMEOUT_MINUTES/,
        "Step 6b's term must be derived from the timeout, not written as a constant",
      ],
      [
        /CODEX_TIMEOUT_MINUTES\s*=[^\n]*BOSS_CROSS_REVIEW_TIMEOUT_MS/,
        'the derivation must name the env var that actually bounds the Codex leg',
      ],
      [
        // Both legs. A term that is only the timeout is as wrong as one that is only the reviewer:
        // the fallback is dispatched AFTER the timeout is spent, so the worst path pays for both.
        /STEP_6B_MINUTES[\s\S]{0,200}fallback\s+reviewer\s+a\s+timeout\/failure\s+dispatches/i,
        'the term must include the fallback reviewer a timed-out Codex pass dispatches',
      ],
      [
        /\+\s*\$STEP_6B_MINUTES/,
        'FULL_TIER_MINUTES must consume the derived term rather than re-stating a number',
      ],
      [
        // "invalid" alone does not cover `0`: it is a perfectly well-formed value that the helper
        // still refuses, and pricing it as zero minutes underprices the leg Codex actually gets.
        // Nor does "positive integer" cover `1.8e6` — which IS one, and which the helper now
        // refuses precisely because no shell glob can match it. The contract is the narrower set.
        // `[\s#]+` not `\s+`: this lives in a fenced comment block, so a rewrap inserts a `# `
        // continuation prefix between any two words.
        /PLAIN[\s#]+DECIMAL[\s#]+DIGITS[\s\S]{0,300}300000\s*ms/i,
        'the derivation must read the env var as resolveTimeoutMs does — only plain digits are honored',
      ],
      [
        // Name the forms, not just the rule: a reader pricing this term has to know that a legal
        // `Number()` value can still be the 300000 ms default here.
        /`1\.8e6`[\s\S]{0,120}`\+?0x2710`|`0x2710`[\s\S]{0,120}`\+600000`/,
        'the derivation must name the exponent/hex/signed forms that resolve to the default',
      ],
    ]) {
      assert.match(tierSelection, pattern, `${dir}: Step 6b must be priced as a chain — ${why}`)
    }
    // The negative that matters: every positive above can co-exist with the old flat constant left
    // sitting in the formula, which is what a merge or a partial revert would produce.
    assert.doesNotMatch(
      tierSelection,
      /\+\s*10\s+#\s*Step\s*6b/i,
      `${dir}: Step 6b must not be re-priced as a flat 10-minute review in the formula`,
    )
    // ARITHMETIC, not prose. The stated defaults are the value of the expression, so they must
    // actually add up — the exact way a spec fix relocates its defect is by correcting one term and
    // leaving the totals it feeds behind. Lift every number out of the shipped markdown and check.
    const num = (re, what) => {
      const m = tierSelection.match(re)
      assert.ok(m, `${dir}: could not read ${what} out of the tier formula`)
      return Number(m[1])
    }
    const step6b = num(
      /default\s*→\s*(\d+)\s+minutes;\s*a\s+\d+\s*ms/,
      'the default STEP_6B_MINUTES',
    )
    const step6c = num(/STEP_6C_MINUTES\s*=\s*(\d+)/, 'STEP_6C_MINUTES')
    const reserve = num(/#\s*=\s*(\d+)\s+minutes/, 'POST_REVIEW_RESERVE_MINUTES')
    const degradedReviewer = num(
      /DEGRADED_REVIEWER_MINUTES\s*=\s*(\d+)/,
      'DEGRADED_REVIEWER_MINUTES',
    )
    const degradedAPI = num(/DEGRADED_API_CHECK_MINUTES\s*=\s*(\d+)/, 'DEGRADED_API_CHECK_MINUTES')
    assert.match(
      tierSelection,
      /DEGRADED_TIER_MINUTES\s*=\s*\$DEGRADED_REVIEWER_MINUTES[\s\S]{0,100}\+\s*\$DEGRADED_API_CHECK_MINUTES/,
      `${dir}: the degraded-tier formula must include both the reviewer and required API-gate cost`,
    )
    const degraded = degradedReviewer + degradedAPI
    assert.equal(
      degraded,
      15,
      `${dir}: the degraded tier must price the 10-minute reviewer plus 5-minute API gate`,
    )
    // The FULL_TIER summary line must restate BOTH of its variable inputs, so a later edit to
    // either one cannot leave the total behind — that is the relocation this gate exists for.
    const summary = tierSelection.match(
      /default\s+\$MAX_ROUNDS\s*=\s*(\d+)\s+and\s+\$STEP_6B_MINUTES\s*=\s*(\d+)\s*→\s*(\d+)\s+minutes/,
    )
    assert.ok(summary, `${dir}: the formula must state its default total and the inputs it assumed`)
    const [maxRounds, restatedStep6b, fullTier] = summary.slice(1).map(Number)
    assert.equal(
      restatedStep6b,
      step6b,
      `${dir}: the FULL_TIER summary restates a STEP_6B_MINUTES default the derivation above does not produce`,
    )
    assert.equal(
      fullTier,
      maxRounds * 20 + 40 + step6b + 20 + step6c,
      `${dir}: the stated FULL_TIER_MINUTES default must equal the terms above it`,
    )
    const floorBranch = num(
      /DEGRADED_TIER_MINUTES \+ POST_REVIEW_RESERVE_MINUTES`\*\*\s*\(default\s*\*\*(\d+)\*\*\)/,
      "branch 2's stated default",
    )
    assert.equal(
      floorBranch,
      degraded + reserve,
      `${dir}: branch 2's stated default must equal the floor it compares against`,
    )
    assert.equal(
      floorBranch,
      40,
      `${dir}: the degraded-tier floor must reserve 15 review minutes plus 25 post-review minutes`,
    )
    const fullBranch = num(
      /FULL_TIER_MINUTES \+ POST_REVIEW_RESERVE_MINUTES`\*\*\s*\(default\s*\*\*(\d+)\*\*\)/,
      "branch 3's stated default",
    )
    assert.equal(
      fullBranch,
      fullTier + reserve,
      `${dir}: branch 3's stated default must equal FULL_TIER_MINUTES plus the reserve`,
    )
    const [rangeLo, rangeHi] = (() => {
      const m = tierSelection.match(/\(default\s*\*\*(\d+)[–-](\d+)\*\*\)/)
      assert.ok(m, `${dir}: branch 4 must state the degraded-tier range`)
      return [Number(m[1]), Number(m[2])]
    })()
    assert.equal(rangeLo, floorBranch, `${dir}: branch 4 must start at branch 2's floor`)
    assert.equal(
      rangeHi,
      fullBranch - 1,
      `${dir}: branch 4 must end one minute below branch 3's threshold`,
    )
    // Step 6b's OWN budget gate is the other reader of this number. Left as a judgement call it
    // admits the same chain the formula just re-priced, one section further down.
    // BOS-737: no `length > 0` pin — `region()` already throws on an absent marker or an empty
    // region.
    const step6bSection = region(
      reviewStack,
      '## Step 6b: Outside voice',
      '## Step 6c: Consolidated multi-lens review',
    )
    assert.match(
      step6bSection,
      /STEP_6B_MINUTES\s*\+\s*20\s*\+\s*POST_REVIEW_RESERVE_MINUTES/,
      `${dir}: Step 6b's own budget gate must use the derived term plus the re-review and the reserve`,
    )
    assert.doesNotMatch(
      step6bSection,
      /no\s+comfortable\s+margin/i,
      `${dir}: Step 6b's budget gate must be arithmetic, not a "comfortable margin" judgement call`,
    )
    // ...and that gate states its own default, so it is one more total that can be left behind.
    const gateDefault = step6bSection.match(
      /POST_REVIEW_RESERVE_MINUTES`\s*\(default\s*\*\*(\d+)\*\*\)/,
    )
    assert.ok(gateDefault, `${dir}: Step 6b's budget gate must state its default`)
    assert.equal(
      Number(gateDefault[1]),
      step6b + 20 + reserve,
      `${dir}: Step 6b's budget-gate default must equal its own expression at the shipped defaults`,
    )
  }
})

test('BOS-758 P2: the BLOCKED handoff reports the rescue branch, not a fixed "unpushed" sentence', () => {
  // The push block has THREE outcomes (`PUSHED=yes` / `rescue` / `no`) but the closing instruction
  // described only one, and described it with the pre-rescue attempt count: "if all three attempts
  // fail, name the unpushed commit SHAs". On the `PUSHED=rescue` path that is doubly false — eight
  // attempts, and the commits ARE on the remote — so the handoff omitted the one branch holding the
  // work while telling the next run to go looking for commits that had already left the worktree.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const secIdx = reviewStack.indexOf('### BLOCKED-route publication')
    assert.ok(
      secIdx >= 0,
      `${dir}: review-stack.md must carry the BLOCKED-route publication section`,
    )
    const secEndRel = reviewStack.slice(secIdx + 1).search(/\n#{2,3} /)
    const section = reviewStack.slice(
      secIdx,
      secEndRel === -1 ? reviewStack.length : secIdx + 1 + secEndRel,
    )
    const pushBlock = [...section.matchAll(/```bash\n([\s\S]*?)```/g)]
      .map((m) => m[1])
      .find((b) => /git[ ]push -u[ ]origin/.test(b))
    assert.ok(pushBlock, `${dir}: the push rule must ship a runnable bash block`)

    // The count the prose may quote is whatever the loop actually runs — derive it, never pin a
    // literal, or this gate rots into the very drift it exists to catch.
    const bound = pushBlock.match(/while \[ "\$attempts" -lt (\d+) \]/)
    assert.ok(bound, `${dir}: the push loop must state its attempt bound`)
    const WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']
    const spelled = WORDS[Number(bound[1])]
    assert.ok(spelled, `${dir}: unhandled attempt bound ${bound[1]} — extend WORDS`)
    // Prose outside the bash block must not quote a DIFFERENT count than the loop runs. `\s+`, not
    // a literal space: these sentences are hand-wrapped and any of them can break across a line.
    const prose = section.replace(/```bash\n[\s\S]*?```/g, '')
    for (const word of WORDS.slice(2)) {
      if (word === spelled) continue
      assert.doesNotMatch(
        prose,
        new RegExp(`(all\\s+)?${word}\\s+attempts`, 'i'),
        `${dir}: the BLOCKED-route prose quotes "${word} attempts" but the loop runs ${bound[1]}`,
      )
    }
    assert.match(
      prose,
      new RegExp(`all\\s+${spelled}\\s+attempts`, 'i'),
      `${dir}: the rescue outcome must name the real attempt count (${bound[1]})`,
    )

    // Rescue SUCCESS and rescue FAILURE need separate instructions, and only the failure one may
    // reach for bare SHAs.
    // Anchor on the BULLETS (`/m`, list-item start), not on the first mention anywhere: the
    // surrounding rationale legitimately names these tokens while explaining why each arm must
    // assign explicitly, and a first-mention search reads that discussion as the handoff itself.
    const rescueIdx = prose.search(/^- `PUSHED=rescue`/m)
    const failIdx = prose.search(/^- `PUSHED=no`/m)
    assert.ok(
      rescueIdx >= 0 && failIdx > rescueIdx,
      `${dir}: the handoff must branch on PUSHED, with the rescue-success case stated before the total-failure case`,
    )
    const rescueArm = prose.slice(rescueIdx, failIdx)
    assert.match(
      rescueArm,
      /Name\s+`?\$RESCUE`?[\s\S]{0,200}BLOCKED\s+comment/i,
      `${dir}: on PUSHED=rescue the handoff must name $RESCUE as the branch holding the commits`,
    )
    assert.match(
      rescueArm,
      /do\s+\*\*not\*\*\s+describe\s+the\s+commits\s+as\s+unpushed/i,
      `${dir}: on PUSHED=rescue the handoff must not describe the persisted commits as unpushed`,
    )
    // The negative that matters: the stale sentence was an UNCONDITIONAL "name the unpushed SHAs".
    // Every positive above survives it being re-added alongside them, and a runner following the
    // unconditional one still buries the rescue branch. The instruction must live under PUSHED=no.
    const shaIdx = prose.search(/name\s+the\s+unpushed\s+commit\s+SHAs/i)
    assert.ok(
      shaIdx > failIdx,
      `${dir}: "name the unpushed commit SHAs" must appear only under the PUSHED=no arm, never as the unconditional handoff`,
    )
  }
})

// ---------------------------------------------------------------------------
// BOS-758 review round 3. All three findings share one shape: an AWAITED dispatch that spends from
// the 25-minute post-review reserve with no bound of its own, while the tier formula claims it is
// priced. Each gate below lifts the arithmetic out of the SHIPPED markdown and runs it, so a prose
// edit that keeps the words and loses the behaviour trips here.
// ---------------------------------------------------------------------------

const bashBlocksOf = (md) => [...md.matchAll(/```bash\n([\s\S]*?)```/g)].map((m) => m[1])
const runBlock = (block, env, echo) =>
  execFileSync('bash', ['-c', `${block}\nprintf '%s' "${echo}"`], {
    encoding: 'utf8',
    env: { ...process.env, PREFLIGHT_DEADLINE: '', REMAINING_MINUTES: '', ...env },
  })

test('BOS-758 P1: the ABSOLUTE Preflight deadline reaches the review worker, not just a snapshot', () => {
  // `REMAINING_MINUTES` is a whole-minute reading taken before the brief is composed, and the
  // reference told the dispatched worker not to derive a deadline of its own — yet Step 6b's budget
  // gate and Step 6c's entry gate both re-measure "against the Preflight deadline". A worker that
  // holds neither the deadline nor permission to derive one cannot run those gates, so it starts
  // Step 6b on entry-time budget the Step 6 loop has already spent. `STEP_6C_DEADLINE` does not
  // close it: that is a per-step allowance stamped downstream, not the run's global deadline.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const skill = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')

    // (a) THE PRODUCER. Only the orchestrator holds the deadline and only the body composes the
    // brief, so an input named solely in the reference is named after the dispatch that needed it.
    assert.match(
      skill,
      /`PREFLIGHT_DEADLINE`/,
      `${dir}/SKILL.md: the Step 6 dispatch brief must hand over the absolute Preflight deadline`,
    )
    assert.match(
      skill,
      /PREFLIGHT_DEADLINE[\s\S]{0,300}\*\*exactly\*\*\s+that\s+name/i,
      `${dir}/SKILL.md: the brief must pin the name, or the receiving gates bind a name nothing assigned`,
    )
    // The two deadlines are different values with different scopes. Conflating them is how this
    // fix would relocate its defect: a per-step allowance cannot bound the steps before it.
    assert.match(
      skill,
      /\*\*not\*\*\s*\n?\s*`STEP_6C_DEADLINE`/i,
      `${dir}/SKILL.md: the brief must distinguish the global deadline from Step 6c's own allowance`,
    )

    // (b) THE CONSUMER. The reference must bind the supplied name, and must NOT still tell the
    // dispatched worker it may not derive a clock — that instruction is what made the later
    // re-measure gates unrunnable.
    assert.match(
      reviewStack,
      /PREFLIGHT_DEADLINE[\s\S]{0,400}absolute\s+Unix\s+time\s+in\s+seconds/i,
      `${dir}: the reference must state the deadline's unit, or a minutes value is compared to a clock`,
    )
    assert.doesNotMatch(
      reviewStack,
      /do\s+not\s+try\s+to\s+derive\s+one\s+yourself/i,
      `${dir}: the worker may no longer be forbidden a clock — Step 6b/6c both re-measure against one`,
    )

    // (c) THE SINGLE SOURCE. Preflight stamps the absolute cap once. Step 6 then takes a fresh
    // snapshot from that immutable deadline; the worker must never recreate a later cap from an
    // already-stale snapshot.
    const preflight = region(skill, '## Preflight', '## Step 1:')
    assert.match(
      preflight,
      /PREFLIGHT_STARTED_AT="\$\(date \+%s\)"[\s\S]{0,160}PREFLIGHT_DEADLINE=\$\(\( PREFLIGHT_STARTED_AT \+ 4 \* 60 \* 60 \)\)[\s\S]{0,80}export[ ]PREFLIGHT_DEADLINE/,
      `${dir}: Preflight must stamp and export one absolute four-hour deadline`,
    )
    const remainingSnapshot = bashBlocksOf(skill).find((b) => /^NOW="\$\(date \+%s\)"/m.test(b))
    assert.ok(
      remainingSnapshot,
      `${dir}: Step 6 must compute REMAINING_MINUTES from the Preflight deadline immediately before dispatch`,
    )
    const now = Math.floor(Date.now() / 1000)
    const remaining = Number(
      runBlock(
        remainingSnapshot,
        { PREFLIGHT_DEADLINE: String(now + 100 * 60) },
        '$REMAINING_MINUTES',
      ).trim(),
    )
    assert.ok(
      remaining >= 99 && remaining <= 100,
      `${dir}: Step 6 must derive its budget from the original deadline, got ${remaining} min`,
    )
    assert.match(
      reviewStack,
      /Never\s+reconstruct\s+the\s+deadline\s+from `REMAINING_MINUTES`[\s\S]{0,360}extend\s+the\s+cap/i,
      `${dir}: the worker must reject a stale-snapshot deadline reconstruction`,
    )
    assert.doesNotMatch(
      reviewStack,
      /PREFLIGHT_DEADLINE\s*=/,
      `${dir}: review-stack must not assign a reconstructed deadline; Preflight owns that value`,
    )

    // (d) THE GATE THAT COULD NOT RUN BEFORE, run. Step 6b's budget gate, lifted and executed.
    const gate6b = bashBlocksOf(reviewStack).find((b) => /^SKIP_6B=$/m.test(b))
    assert.ok(gate6b, `${dir}: Step 6b's budget gate must be runnable arithmetic, not prose`)
    const skip6b = (mins) =>
      runBlock(
        gate6b,
        mins === null ? {} : { PREFLIGHT_DEADLINE: String(now + mins * 60) },
        '[$SKIP_6B]',
      ).trim()
    assert.equal(skip6b(null), '[]', `${dir}: no deadline supplied must mean no cap, not a skip`)
    assert.equal(skip6b(180), '[]', `${dir}: three hours must fund the Step 6b chain`)
    assert.equal(skip6b(240), '[]', `${dir}: four hours must fund the Step 6b chain`)
    // The default expression is 15 + 20 + 25 = 60 minutes; 59 must refuse and 61 must admit.
    assert.equal(skip6b(59), '[budget]', `${dir}: 59 minutes must not admit a 60-minute chain`)
    assert.equal(skip6b(61), '[]', `${dir}: 61 minutes must admit the 60-minute chain`)
    // ...and it must track the CONFIGURED Codex timeout, not a baked-in 15. At 30 minutes the
    // chain costs 30 + 10 + 20 + 25 = 85, so 61 minutes must now refuse.
    assert.equal(
      runBlock(
        gate6b,
        { PREFLIGHT_DEADLINE: String(now + 61 * 60), BOSS_CROSS_REVIEW_TIMEOUT_MS: '1800000' },
        '[$SKIP_6B]',
      ).trim(),
      '[budget]',
      `${dir}: the gate must price the Codex leg from BOSS_CROSS_REVIEW_TIMEOUT_MS, not a constant`,
    )
    // ...and it must normalize that env var the way the helper does. `0` is all digits, so a
    // shape-only guard admits it and prices the Codex leg at zero minutes — while
    // codex-review.mjs's resolveTimeoutMs rejects non-positive values and grants Codex the full
    // 300000 ms default. The chain still costs 60 minutes, so 59 must still refuse; a gate that
    // took the `0` at face value would admit it and spend 5 minutes of the post-review reserve.
    assert.equal(
      runBlock(
        gate6b,
        { PREFLIGHT_DEADLINE: String(now + 59 * 60), BOSS_CROSS_REVIEW_TIMEOUT_MS: '0' },
        '[$SKIP_6B]',
      ).trim(),
      '[budget]',
      `${dir}: a non-positive BOSS_CROSS_REVIEW_TIMEOUT_MS must price the leg at the helper's default`,
    )
    // ...and the MIRROR-IMAGE of that: normalizing must not swallow a POSITIVE zero-padded value.
    // resolveTimeoutMs parses with Number(), so `0600000` is a valid 600000 ms override and the
    // chain costs 10 + 10 + 20 + 25 = 65 minutes. A guard that rejected every leading zero as
    // "non-positive" would fall back to the 300000 ms default, price the chain at 60, and admit a
    // run with 61 minutes left — underpricing the Codex leg by five minutes of the reserve.
    assert.equal(
      runBlock(
        gate6b,
        { PREFLIGHT_DEADLINE: String(now + 61 * 60), BOSS_CROSS_REVIEW_TIMEOUT_MS: '0600000' },
        '[$SKIP_6B]',
      ).trim(),
      '[budget]',
      `${dir}: a zero-padded POSITIVE timeout must be read as base 10, not rejected as non-positive`,
    )
    // The paired positive, so the assertion above cannot be satisfied by a guard that simply
    // refuses everything: at 66 minutes that same 65-minute chain must be admitted.
    assert.equal(
      runBlock(
        gate6b,
        { PREFLIGHT_DEADLINE: String(now + 66 * 60), BOSS_CROSS_REVIEW_TIMEOUT_MS: '0600000' },
        '[$SKIP_6B]',
      ).trim(),
      '[]',
      `${dir}: 66 minutes must admit the 65-minute chain a 0600000 ms timeout buys`,
    )
  }
})

test('BOS-758 P2: the Step 6b fallback reviewer carries the ten minutes the formula charges it', () => {
  // The tier formula prices Step 6b as CODEX_TIMEOUT + 10, where the 10 is the fallback reviewer a
  // timed-out or broken Codex pass dispatches. That dispatch was awaited and UNBOUNDED, so the
  // "+ 10" was not the worst legal cost: a slow fallback could eat the whole 25-minute post-review
  // reserve inside a tier the ladder had just classified as affordable. Run the clamp.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const clamp = bashBlocksOf(reviewStack).find((b) => /^\s*FALLBACK_SECONDS=600/m.test(b))
    assert.ok(clamp, `${dir}: the Step 6b fallback must derive a runnable dispatch budget`)
    const now = Math.floor(Date.now() / 1000)
    const budget = (mins) =>
      Number(
        runBlock(
          clamp,
          mins === null ? {} : { PREFLIGHT_DEADLINE: String(now + mins * 60) },
          '$FALLBACK_SECONDS',
        ).trim(),
      )
    assert.equal(budget(null), 600, `${dir}: with no caller deadline the fallback gets its 10 min`)
    assert.equal(budget(180), 600, `${dir}: a large budget is still capped at the priced 10 min`)
    // THE REPORTED DEFECT: the clamp must reserve the MANDATORY re-review as well as the 25-minute
    // post-review reserve. §3 is not optional — a fallback reviewer that reports must-fix requires
    // a fix and exactly one confirming round before Step 7, the `+ 20` both the tier formula and
    // the entry gate charge. So 45 owed minutes come out, not 25: with 50 minutes left this leg
    // gets ~300s, and a clamp that subtracted only the reserve would hand it ~1500s (capped to the
    // full 600) and leave a must-fix from it with nowhere to be re-reviewed.
    assert.ok(
      Math.abs(budget(50) - 300) <= 1,
      `${dir}: with 50 min left the fallback must be bounded at ~300s, not the full 600s`,
    )
    assert.ok(
      Math.abs(budget(46) - 60) <= 1,
      `${dir}: the clamp must reserve the re-review too — 46 min leaves ~60s, not ~1260s`,
    )
    // Past those two allowances there is no clock for this leg at all, and the budget must say so
    // by going non-positive rather than silently handing out a full leg.
    assert.ok(
      budget(30) <= 0,
      `${dir}: 30 min cannot fund this leg AND the re-review AND the reserve — must be non-positive`,
    )
    assert.ok(
      budget(20) <= 0,
      `${dir}: inside the post-review reserve the fallback budget must be non-positive`,
    )

    // The clamp only binds if the dispatch actually states it, and only helps if the zero case is
    // a documented skip rather than an improvised dispatch.
    const step6bSection = region(
      reviewStack,
      '## Step 6b: Outside voice',
      '## Step 6c: Consolidated multi-lens review',
    )
    assert.match(
      step6bSection,
      /HARD\s+TIME\s+BUDGET: FALLBACK_SECONDS\s+seconds[\s\S]{0,160}rather\s+than\s+run\s+past\s+it/i,
      `${dir}: the fallback brief must state its budget to the worker as a hard return-by`,
    )
    assert.match(
      step6bSection,
      /Dispatch\s+only\s+while\s+`FALLBACK_SECONDS`\s+is\s+\*\*positive\*\*/i,
      `${dir}: a non-positive budget must stop the dispatch, not shrink it to nothing and run anyway`,
    )
    assert.match(
      step6bSection,
      /At\s+or\s+below\s+zero[\s\S]{0,200}`skipped:\s*budget`/i,
      `${dir}: the unfundable fallback must land on the sanctioned skipped token`,
    )
    // Honesty about what the bound is. An awaited dispatch exposes no timeout, so claiming a hard
    // kill here would be the unenforceable-cap defect one level up.
    assert.match(
      step6bSection,
      /\*\*cooperative\*\*[\s\S]{0,240}worst\s+_legal_\s+cost/i,
      `${dir}: the fallback bound must be stated as cooperative, and as what makes +10 the worst legal cost`,
    )
    // The negative that matters: the formula's own comment must claim the same thing, or the
    // arithmetic above is true while the tier ladder still reads the term as a hope.
    assert.match(
      region(
        reviewStack,
        '## Step 6 entry — review tier selection',
        '## Step 6: Whole-branch review loop',
      ),
      /worst\s+LEGAL\s+cost[\s\S]{0,220}cooperative\s+return-by/i,
      `${dir}: the tier formula must say the fallback term is enforced, not merely assumed`,
    )

    // THE RELOCATION GUARD. The runnable blocks restate two of the formula's numbers as literals —
    // the 25-minute reserve and the fallback's 10 minutes. A later edit to the formula that leaves
    // the blocks behind reprices the ladder while the enforcement keeps spending the old figures,
    // which is exactly how a spec fix moves its defect instead of closing it. Derive both from the
    // shipped formula and require every literal to agree.
    const tierSelection = region(
      reviewStack,
      '## Step 6 entry — review tier selection',
      '## Step 6: Whole-branch review loop',
    )
    const reserve = Number(tierSelection.match(/#\s*=\s*(\d+)\s+minutes/)[1])
    const fallbackMinutes = Number(
      tierSelection.match(/\+\s*(\d+)\s+#\s*AND\s+the\s+fallback\s+reviewer/)[1],
    )
    for (const [, literal] of reviewStack.matchAll(/POST_REVIEW_RESERVE_MINUTES=(\d+)/g)) {
      assert.equal(
        Number(literal),
        reserve,
        `${dir}: an enforcement block hard-codes a ${literal}-minute reserve while the formula prices ${reserve}`,
      )
    }
    for (const [, literal] of reviewStack.matchAll(/FALLBACK_SECONDS=(\d+)/g)) {
      assert.equal(
        Number(literal),
        fallbackMinutes * 60,
        `${dir}: the fallback dispatch budget must be the formula's own ${fallbackMinutes}-minute term`,
      )
    }
    // The re-review allowance is the third number the enforcement blocks restate, and it is the one
    // the clamp was missing entirely. Pin it to the formula's own term, then require the clamp to
    // subtract it ALONGSIDE the reserve — the runtime assertions above prove the arithmetic, this
    // proves the clamp reads the figure the ladder priced rather than a second constant.
    const reReviewMinutes = Number(
      tierSelection.match(
        /\+\s*(\d+)\s+#\s*the\s+one\s+bounded\s+re-review\s+Step\s+6b\s+can\s+trigger/,
      )[1],
    )
    for (const [, literal] of reviewStack.matchAll(/RE_REVIEW_MINUTES=(\d+)/g)) {
      assert.equal(
        Number(literal),
        reReviewMinutes,
        `${dir}: an enforcement block charges ${literal} minutes of re-review while the formula prices ${reReviewMinutes}`,
      )
    }
    assert.match(
      clamp,
      /RE_REVIEW_MINUTES\s*\+\s*POST_REVIEW_RESERVE_MINUTES/,
      `${dir}: the fallback clamp must reserve the mandatory re-review as well as the post-review reserve`,
    )
    // The Step 6b gate re-derives the chain in bash; its own fallback term must match too.
    const gate6b = bashBlocksOf(reviewStack).find((b) => /^SKIP_6B=$/m.test(b))
    assert.equal(
      Number(gate6b.match(/\/\s*60000\s*\+\s*(\d+)\s*\)\)/)[1]),
      fallbackMinutes,
      `${dir}: Step 6b's runnable gate must add the same fallback term the formula charges`,
    )
    assert.equal(
      Number(gate6b.match(/STEP_6B_MINUTES\s*\+\s*(\d+)\s*\+\s*POST_REVIEW_RESERVE_MINUTES/)[1]),
      reReviewMinutes,
      `${dir}: the entry gate must reserve the same re-review allowance the clamp now protects`,
    )
  }
})

test('BOS-758 P2: the full-tier BLOCKING review legs are bounded, not merely priced', () => {
  // The two remaining unenforced terms in FULL_TIER_MINUTES: the Step 6 loop's per-round review
  // pair ($MAX_ROUNDS × 20) and Step 6b §3's required re-review (+ 20). A round cap bounds how many
  // legs run, not how long ONE runs, and an awaited dispatch cannot be preempted once started — so
  // a slow or hung reviewer could consume the whole 25-minute post-review reserve inside a tier the
  // ladder had just classified as affordable, recreating the mid-review overrun the tier exists to
  // prevent. Both are now clamped against PREFLIGHT_DEADLINE. Run the arithmetic, don't read prose.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const tierSelection = region(
      reviewStack,
      '## Step 6 entry — review tier selection',
      '## Step 6: Whole-branch review loop',
    )
    // Every literal below is pinned to the SHIPPED formula, never to a second constant — a later
    // re-pricing that leaves an enforcement block behind is how a spec fix relocates its defect.
    const pairMinutes = Number(tierSelection.match(/\(\$MAX_ROUNDS\s*×\s*(\d+)\)/)[1])
    const reserve = Number(tierSelection.match(/#\s*=\s*(\d+)\s+minutes/)[1])
    const reReviewMinutes = Number(
      tierSelection.match(
        /\+\s*(\d+)\s+#\s*the\s+one\s+bounded\s+re-review\s+Step\s+6b\s+can\s+trigger/,
      )[1],
    )
    // Frozen clock (see frozenClockPath): these clamps read `date +%s` themselves, so the
    // deadline handed in must be measured from the same instant or every budget below is
    // `intended - spawn_latency` and the ~300s assertions can only be tolerances.
    const clockPath = frozenClockPath()
    const now = FROZEN_EPOCH
    const at = (block, mins, name) =>
      Number(
        runBlock(
          block,
          mins === null
            ? { PATH: clockPath }
            : { PATH: clockPath, PREFLIGHT_DEADLINE: String(now + mins * 60) },
          `$${name}`,
        ).trim(),
      )

    // ---- Step 6: both awaited legs of every round --------------------------------------------
    const loop = bashBlocksOf(reviewStack).find((b) => /^REVIEW_LEG_SECONDS=/m.test(b))
    assert.ok(loop, `${dir}: the Step 6 loop must ship a runnable per-leg clamp`)
    // The pair the clamp hands out must be the pair the ladder reserved, not a wider one.
    assert.equal(
      at(loop, null, 'REVIEW_LEG_SECONDS') + at(loop, null, 'FIX_LEG_SECONDS'),
      pairMinutes * 60,
      `${dir}: the two clamped legs must add up to the ${pairMinutes}-minute pair the formula prices`,
    )
    assert.equal(
      at(loop, 240, 'REVIEW_LEG_SECONDS'),
      (pairMinutes / 2) * 60,
      `${dir}: a large budget is still capped at the one leg the formula charges`,
    )
    // THE REPORTED DEFECT. The reviewer must reserve the fix ITS OWN findings make mandatory as
    // well as the post-review reserve, so 35 owed minutes come out, not 25: at 40 minutes left the
    // reviewer gets exactly 300s, and a clamp that subtracted only the reserve would hand it the
    // full 600 and leave its must-fix with no clock to be fixed in.
    assert.equal(
      at(loop, reserve + 15, 'REVIEW_LEG_SECONDS'),
      300,
      `${dir}: with ${reserve + 15} min left the reviewer must be bounded at 300s, not a full leg`,
    )
    assert.equal(
      at(loop, reserve + 5, 'FIX_LEG_SECONDS'),
      300,
      `${dir}: the fix leg must be clamped by the reserve too — ${reserve + 5} min leaves 300s`,
    )
    assert.ok(
      at(loop, reserve + 9, 'REVIEW_LEG_SECONDS') <= 0,
      `${dir}: too little clock for a reviewer AND its mandatory fix AND the reserve must go non-positive`,
    )
    assert.ok(
      at(loop, reserve - 1, 'FIX_LEG_SECONDS') <= 0,
      `${dir}: inside the post-review reserve the fix budget must be non-positive`,
    )
    // The negative that matters: subtracting only the reserve satisfies every prose assertion below
    // while re-opening the defect, so pin the reviewer's extra allowance structurally as well.
    assert.match(
      loop,
      /FIX_LEG_MINUTES\s*\+\s*POST_REVIEW_RESERVE_MINUTES/,
      `${dir}: the reviewer clamp must reserve the mandatory fix as well as the post-review reserve`,
    )
    for (const [, literal] of reviewStack.matchAll(
      /(?:REVIEW_LEG_SECONDS|FIX_LEG_SECONDS)=(\d+)/g,
    )) {
      assert.equal(
        Number(literal),
        (pairMinutes / 2) * 60,
        `${dir}: a round leg is budgeted ${literal}s while the formula prices the pair at ${pairMinutes} min`,
      )
    }
    for (const [, literal] of reviewStack.matchAll(/FIX_LEG_MINUTES=(\d+)/g)) {
      assert.equal(
        Number(literal),
        pairMinutes / 2,
        `${dir}: the reviewer clamp withholds ${literal} min for the fix, not the formula's half-pair`,
      )
    }

    // ---- Step 6b §3: the required re-review ---------------------------------------------------
    const reReview = bashBlocksOf(reviewStack).find((b) => /^RE_REVIEW_SECONDS=/m.test(b))
    assert.ok(reReview, `${dir}: Step 6b §3 must ship a runnable re-review clamp`)
    assert.equal(
      at(reReview, null, 'RE_REVIEW_SECONDS'),
      reReviewMinutes * 60,
      `${dir}: with no caller deadline the re-review gets the ${reReviewMinutes} min the formula charges`,
    )
    assert.equal(
      at(reReview, 180, 'RE_REVIEW_SECONDS'),
      reReviewMinutes * 60,
      `${dir}: a large budget is still capped at the priced re-review`,
    )
    assert.ok(
      Math.abs(at(reReview, reserve + 5, 'RE_REVIEW_SECONDS') - 300) <= 1,
      `${dir}: the re-review must never reach into the ${reserve}-minute post-review reserve`,
    )
    assert.ok(
      at(reReview, reserve - 5, 'RE_REVIEW_SECONDS') <= 0,
      `${dir}: inside the post-review reserve the re-review budget must be non-positive`,
    )

    // ---- The hand-off. A budget its holder never states bounds nothing. -----------------------
    // `\s+` between words, never a literal space — prettier reflows this prose at 100 columns.
    const loopSection = region(
      reviewStack,
      '## Step 6: Whole-branch review loop',
      '## Step 6b: Outside voice',
    )
    assert.match(
      loopSection,
      /HARD\s+TIME\s+BUDGET: <N> seconds[\s\S]{0,120}rather\s+than\s+run\s+past\s+it/i,
      `${dir}: each round leg must state its budget to the worker as a hard return-by`,
    )
    assert.match(
      loopSection,
      /At\s+or\s+below\s+zero[\s\S]{0,200}capped\s+path/i,
      `${dir}: a non-positive leg budget must take the capped path, not run one more unbudgeted round`,
    )
    // Honesty about the bound: an awaited dispatch exposes no timeout, so a hard-kill claim here
    // would be the unenforceable-cap defect this whole ticket is about, one level down.
    assert.match(
      loopSection,
      /\*\*cooperative\*\*[\s\S]{0,300}worst\s+_legal_\s+cost/i,
      `${dir}: the round bound must be stated as cooperative, and as what makes the pair price legal`,
    )
    const reReviewSection = region(
      reviewStack,
      '**3. Fix + bounded re-review.**',
      '**4. Record the outcome',
    )
    assert.match(
      reReviewSection,
      /`\[TIME_BUDGET_SECONDS\]`/,
      `${dir}: §3's confirming round must hand its budget over through the template slot`,
    )
    assert.match(
      reReviewSection,
      /\*\*cooperative\*\*[\s\S]{0,200}worst\s+_legal_\s+cost/i,
      `${dir}: §3's bound must be stated as cooperative, not as a hard kill`,
    )
    // GATE THE HAND-OFF, in the template itself: the clamp is inert unless the dispatched worker is
    // actually told the number, and the template is the only thing the dispatch fills in.
    const template = fs.readFileSync(
      path.join(rootDir, dir, 'references/code-reviewer-template.md'),
      'utf8',
    )
    assert.match(
      template,
      /HARD[ ]TIME[ ]BUDGET: \[TIME_BUDGET_SECONDS\] seconds[\s\S]{0,400}return/i,
      `${dir}: the reviewer template must carry a hard return-by slot for its caller to fill`,
    )
    assert.match(
      template,
      /-\s*`\[TIME_BUDGET_SECONDS\]`\s*—/,
      `${dir}: the template's placeholder list must document the budget slot`,
    )
    assert.match(
      template,
      /degraded\s+whole-branch\s+reviewer['’]s\s+`DEGRADED_REVIEWER_MINUTES`\s*\(10\)\s+in\s+seconds[\s\S]{0,240}separately\s+priced\s+API\s+classification[\s\S]{0,160}`DEGRADED_API_CHECK_MINUTES`\s*\(5\)\s+in\s+seconds/i,
      `${dir}: the template must give the degraded reviewer its 10-minute budget and reserve the API check's separate allowance`,
    )
    // And the loop must actually fill it. A template slot no dispatch site names is the same inert
    // feature one step earlier.
    assert.match(
      loopSection,
      /`\[TIME_BUDGET_SECONDS\]`\s*slot\s*\n?\s*with\s+`REVIEW_LEG_SECONDS`/,
      `${dir}: Step 6's reviewer dispatch must fill the template slot with its clamped budget`,
    )

    // ---- The formula must AGREE that both terms are enforced ---------------------------------
    // Without this the arithmetic above is true while the ladder still prices the terms as hopes,
    // which is the stale-restatement failure that made this a P2 rather than a one-line fix.
    assert.match(
      tierSelection,
      /each\s+20\s+is\s+a\s+CAP\s+the\s+loop\s+enforces/i,
      `${dir}: the formula must say the per-round pair is a cap, not an estimate`,
    )
    assert.match(
      tierSelection,
      /also\s+a\s+CAP:\s+Step\s+6b\s+§3\s+clamps/i,
      `${dir}: the formula must say the re-review term is a cap, not an estimate`,
    )
  }
})

test('BOS-758 P2: boss-review Phase 8 notes dispatches are gated on the caller deadline', () => {
  // Phase 8 was declared local and ungated alongside Phases 0/5/7. It is local only when the repo
  // has NOT opted into a notes extension: opting in dispatches awaited workers there, each allowed
  // a full BOSS_SKILL_EXTENSION_TIMEOUT_MS, and because the caller awaits the whole skill they run
  // straight out of its post-review reserve — after the Step 6c allowance is already spent.
  for (const dir of BUILD_MIRRORS) {
    const reviewSkill = fs.readFileSync(
      path.join(rootDir, dir.replace(/boss-build$/, 'boss-review'), 'SKILL.md'),
      'utf8',
    )
    // The defect sentence itself. Every positive below survives it being re-added.
    assert.doesNotMatch(
      reviewSkill,
      /Phases\s+5,\s+7\s+and\s+8\s+are\s+local/i,
      `${dir}: Phase 8 may no longer be declared local — an opted-in repo dispatches awaited workers there`,
    )
    // The leg list is where a reader learns what is gated; an omission there reads as a decision.
    assert.match(
      region(reviewSkill, 'The legs, each with its `LEG_SECONDS`', '## Findings contract'),
      /\*\*Phase\s+8\*\*[\s\S]{0,200}`DEADLINE_LEG_SECONDS`/i,
      `${dir}: Phase 8 must appear in the gated-leg list with a leg allowance`,
    )

    // ARITHMETIC: lift Phase 8's own gate and run it against the documented caller name.
    const gate = bashBlocksOf(reviewSkill).find((b) => /SKIP_NOTES=1/.test(b))
    assert.ok(gate, `${dir}: Phase 8 must carry a runnable caller-deadline gate`)
    const now = Math.floor(Date.now() / 1000)
    const skip = (secs) =>
      execFileSync('bash', ['-c', `${gate}\nprintf '%s' "[$SKIP_NOTES]"`], {
        encoding: 'utf8',
        env: {
          ...process.env,
          DEADLINE_LEG_SECONDS: '300',
          SKIP_NOTES: '',
          deadline: '',
          STEP_6C_DEADLINE: secs === null ? '' : String(now + secs),
        },
      }).trim()
    assert.equal(
      skip(null),
      '[]',
      `${dir}: no caller deadline means no cap, never a refusal of all`,
    )
    assert.equal(skip(3600), '[]', `${dir}: an hour of clock must fund a notes worker`)
    assert.equal(skip(60), '[1]', `${dir}: 60s left must refuse a 300s notes leg`)

    // A post-terminal phase may not reach back into the report. The generic "stop there" rule
    // routes a refused leg to the capped exit; doing that here would rewrite a verdict already
    // handed to the caller, so the exception has to be written down.
    const phase8 = region(reviewSkill, '## Phase 8 — Cleanup')
    assert.match(
      phase8,
      /`extension <name>: skipped \(caller\s+deadline\)`/,
      `${dir}: a refused notes dispatch must land on a named ledger token, not silence`,
    )
    assert.match(
      phase8,
      /never\s+re-enters\s+Phase\s+7\s+and\s+never\s+touches\s*\n?\s*the\s+capped\s+report/i,
      `${dir}: Phase 8's refusal must not reduce a report the caller already has`,
    )
    // Portability: the opt-in must be described generically. A published core names no repo's
    // own extension directory — it appears in every project on the machine.
    assert.doesNotMatch(
      phase8,
      /bossanova|\.claude\/skills\/boss-review-/i,
      `${dir}: the published core must describe the notes opt-in generically, never a specific repo's extension`,
    )
  }
})

// ---------------------------------------------------------------------------
// BOS-758 review round 3. One defect class, seen now in three files: a millisecond timeout read
// from the environment and fed to `$(( ))` with no base-10 radix, so a zero-padded `0600000` is
// read as OCTAL — and, on the other side of the same seam, a helper that parses with a bare
// `Number()` and so honours exponent/hex/signed forms no shell glob can match. Both directions
// misprice a gate against the leg the helper actually grants. These gates run the SHIPPED shell
// and call the SHIPPED helper, so an edit that keeps the prose and loses the radix trips here.
// ---------------------------------------------------------------------------

// The one case table both readers are held to. `expected` is the ms value each must resolve to.
const TIMEOUT_CASE_TABLE = [
  ['0600000', 600000], // zero-padded POSITIVE — a real override, and the round-2 regression
  ['600000', 600000],
  ['1800000', 1800000],
  ['08', 8], // base 10, not the octal-illegal token `08`
  ['1.8e6', 300000], // legal Number(), unmatchable by any glob → both must default
  ['+600000', 300000],
  ['0x2710', 300000],
  [' 1800000', 300000],
  ['0', 300000], // all digits, non-positive RESULT
  ['00', 300000],
  ['', 300000],
  ['abc', 300000],
  ['10x', 300000],
  ['-5', 300000],
]

test('BOS-758 P2: the Step 6c leg allowance normalizes its timeout in base 10, not octal', () => {
  // THE REPORTED DEFECT: `leg_ms=${BOSS_SKILL_EXTENSION_TIMEOUT_MS:-300000}` went straight into
  // `$(( (leg_ms + 999) / 1000 ))`, where a leading zero is OCTAL. A `0600000` timeout derived
  // 196608 ms -> ~197 s -> floored to 300, while the dispatch it prices was still configured for
  // the full 600000 ms. A Step 6c gate would then admit that ten-minute leg with five minutes left.
  for (const dir of BUILD_MIRRORS) {
    const reviewSkill = fs.readFileSync(
      path.join(rootDir, dir.replace(/boss-build$/, 'boss-review'), 'SKILL.md'),
      'utf8',
    )
    const block = bashBlocksOf(reviewSkill).find((b) => /^leg_ms=/m.test(b))
    assert.ok(block, `${dir}: the leg allowance must ship as a runnable bash block`)

    const legSeconds = (raw) =>
      Number(
        execFileSync('bash', ['-c', `set -u\n${block}\nprintf '%s' "$DEADLINE_LEG_SECONDS"`], {
          encoding: 'utf8',
          env: { ...process.env, BOSS_SKILL_EXTENSION_TIMEOUT_MS: raw },
        }).trim(),
      )

    // The defect case, stated as the allowance the dispatch actually costs.
    assert.equal(
      legSeconds('0600000'),
      600,
      `${dir}: a zero-padded 0600000 ms timeout must price 600 s, not the octal-derived ~197 -> 300`,
    )
    // ...and it must be the PADDING that is tolerated, not the number: the unpadded form agrees.
    assert.equal(
      legSeconds('600000'),
      legSeconds('0600000'),
      `${dir}: padding a value must not change the allowance it prices`,
    )
    // The whole table, so a guard cannot pass by being uniformly permissive or uniformly strict.
    for (const [raw, ms] of TIMEOUT_CASE_TABLE) {
      assert.equal(
        legSeconds(raw),
        Math.max(Math.ceil(ms / 1000), 300),
        `${dir}: BOSS_SKILL_EXTENSION_TIMEOUT_MS=${JSON.stringify(raw)} must price ${ms} ms`,
      )
    }
  }
})

test('BOS-758 P2: the Step 6b gate and resolveTimeoutMs accept exactly the same forms', async () => {
  // THE REPORTED DEFECT and the reason this is a CLASS gate rather than a third instance fix. The
  // gate's normalization is a POSIX `case` glob plus `$(( 10# ))`; the helper used a bare `Number()`
  // and so honoured `1.8e6`, `0x2710`, `+600000` and padded ` 1800000` — forms no glob can express.
  // Every such form is a leg the gate reserves 300000 ms for while the helper grants the override:
  // `1.8e6` reserves five minutes for a thirty-minute Codex leg, straight out of the reserve. The
  // fix narrowed the HELPER to the shell's own digits-only shape, so the two now define one set.
  // This asserts that set from both ends at once — the shipped markdown and the shipped module.
  const { resolveTimeoutMs } = await import(
    pathToFileURL(path.join(rootDir, 'skills-toolbox/codex-review.mjs')).href
  )
  const claudeSide = await import(
    pathToFileURL(path.join(rootDir, 'skills-toolbox/claude-review.mjs')).href
  )

  for (const dir of BUILD_MIRRORS) {
    const gate6b = bashBlocksOf(reviewStackFor(dir)).find((b) => /^SKIP_6B=$/m.test(b))
    assert.ok(gate6b, `${dir}: Step 6b must ship its budget gate as a runnable bash block`)
    // Only the normalization; the clock comparison below it is a different assertion's business.
    const normalizer = gate6b.split('\nSTEP_6B_MINUTES=')[0]
    assert.match(
      normalizer,
      /10#\$CODEX_TIMEOUT_MS/,
      `${dir}: the gate must convert through an EXPLICIT base-10 radix, never a bare $(( ))`,
    )

    const shellMs = (raw) =>
      Number(
        execFileSync('bash', ['-c', `set -u\n${normalizer}\nprintf '%s' "$CODEX_TIMEOUT_MS"`], {
          encoding: 'utf8',
          env: { ...process.env, PREFLIGHT_DEADLINE: '', BOSS_CROSS_REVIEW_TIMEOUT_MS: raw },
        }).trim(),
      )

    for (const [raw, ms] of TIMEOUT_CASE_TABLE) {
      const env = { BOSS_CROSS_REVIEW_TIMEOUT_MS: raw }
      assert.equal(
        shellMs(raw),
        ms,
        `${dir}: the Step 6b gate must read ${JSON.stringify(raw)} as ${ms} ms`,
      )
      assert.equal(
        resolveTimeoutMs(env),
        ms,
        `codex-review.mjs resolveTimeoutMs must read ${JSON.stringify(raw)} as ${ms} ms — the gate does`,
      )
      // claude-review.mjs documents an IDENTICAL contract; narrowing one alone is how they diverge.
      assert.equal(
        claudeSide.resolveTimeoutMs(env),
        ms,
        `claude-review.mjs must match codex-review.mjs on ${JSON.stringify(raw)}`,
      )
    }
  }
})

test('BOS-758 P2: both timeout normalizers share one idiom, stated in shipped prose', () => {
  // The two shell sites are three lines each and trivially re-diverge under a later edit, so pin
  // the SHAPE of the idiom in each: digits-only glob, explicit `10#`, non-positive-RESULT reject.
  const sites = []
  for (const dir of BUILD_MIRRORS) {
    const reviewSkill = fs.readFileSync(
      path.join(rootDir, dir.replace(/boss-build$/, 'boss-review'), 'SKILL.md'),
      'utf8',
    )
    sites.push([`${dir} (boss-review Step 6c leg)`, 'leg_ms', reviewSkill])
    sites.push([`${dir} (Step 6b codex timeout)`, 'CODEX_TIMEOUT_MS', reviewStackFor(dir)])
  }
  for (const [label, name, md] of sites) {
    const block = bashBlocksOf(md).find((b) =>
      new RegExp(`^${name}=\\$\\{BOSS_[A-Z_]+:-\\d+\\}`, 'm').test(b),
    )
    assert.ok(block, `${label}: the normalizer must ship as a runnable bash block`)
    // Every pattern is `^`-anchored under /m. Without that a COMMENTED-OUT guard satisfies the
    // regex — the exact vacuity a mutant caught here: `#[ "$leg_ms" -gt 0 ] || leg_ms=300000` still
    // contains the whole idiom as a substring while executing nothing. Step 3 in particular has no
    // observable effect in the boss-review block (the 300 s floor absorbs a zero), so this
    // structural gate is its ONLY gate and it has to be about the line, not the characters.
    assert.match(
      block,
      new RegExp(`^case\\s+"\\$${name}"\\s+in\\s+''\\s*\\|\\s*\\*\\[!0-9\\]\\*\\)`, 'm'),
      `${label}: step 1 must reject the SHAPE with a digits-only glob before any arithmetic`,
    )
    assert.match(
      block,
      new RegExp(`^${name}=\\$\\(\\(\\s*10#\\$${name}\\s*\\)\\)`, 'm'),
      `${label}: step 2 must convert with an EXPLICIT base-10 radix — a bare $(( )) is octal`,
    )
    assert.match(
      block,
      new RegExp(`^\\[\\s*"\\$${name}"\\s+-gt\\s+0\\s*\\]\\s*\\|\\|\\s*${name}=\\d+`, 'm'),
      `${label}: step 3 must reject a non-positive RESULT, which is what 0 and 00 are`,
    )
    // ORDER is load bearing: `10#` on a non-digit string is itself an arithmetic error, so the
    // shape glob must precede the conversion, and the result test must follow it.
    assert.ok(
      precedes(block, `case "$${name}" in`, `10#$${name}`, label) &&
        precedes(block, `10#$${name}`, `[ "$${name}" -gt 0 ]`, label),
      `${label}: the three steps must run shape -> base-10 -> positive-result, in that order`,
    )
  }

  // And the reason, in the doc a reader edits: the accepted set is the NARROWER of the two readers,
  // so widening either side alone re-opens the class. Prose regexes use \s+ — prettier rewraps.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    assert.match(
      reviewStack,
      // `[_*]` because prettier normalizes markdown emphasis; `\s+` because it rewraps at 100.
      /`resolveTimeoutMs`\s+applies\s+the\s+[_*]same[_*]\s+digits-only\s+shape\s+gate/,
      `${dir}: the doc must state that the helper implements this same shape gate`,
    )
    assert.match(
      reviewStack,
      /a\s+change\s+to\s+either\s+side\s+is\s+a\s+change\s+to\s*\n?\s*both/,
      `${dir}: the doc must forbid widening one reader without the other`,
    )
    assert.match(
      reviewStack,
      /skills-toolbox\/claude-review\.mjs`\s+carries\s+the\s+identical\s+contract/,
      `${dir}: the doc must name the SECOND helper that shares the contract`,
    )
    // The superseded claim. It described a deliberate divergence that no longer exists, and left
    // `+600000` / `1.8e6` documented as underpriced-but-tolerated rather than rejected.
    assert.doesNotMatch(
      reviewStack,
      /Where\s+this\s+deliberately\s+diverges\s+from\s+the\s+helper/,
      `${dir}: the doc may no longer advertise a divergence the helper no longer has`,
    )
  }
})

// ---------------------------------------------------------------------------
// BOS-758 review round 4. The BLOCKED-route push block guarded its whole body behind
// "commits ahead of upstream", so a resumed branch with nothing to send fell straight past it
// leaving `PUSHED` UNSET — and the handoff below branches on `yes`/`rescue`/`no`, so an unset
// value matches no arm and the BLOCKED comment cannot say where the work is stored.
// The obvious repair (seed `PUSHED=yes` above the conditional) is fail-OPEN twice over: it makes
// "the work is safely on the remote" the default for any path that forgets to assign, and
// zero-ahead does not actually imply the work is on origin — `@{upstream}` is a remote-TRACKING
// ref that still resolves after the branch it mirrors was deleted server-side. So the gate below
// runs the SHIPPED block against real repositories and asserts the honest outcome on each path.
// ---------------------------------------------------------------------------

const pushBlockOf = (md) => {
  const block = bashBlocksOf(md).find((b) => /git[ ]push -u[ ]origin "\$SESSION_BRANCH"/.test(b))
  assert.ok(block, 'the BLOCKED-route section must ship a runnable push block')
  return block
}

const REAL_GIT = execFileSync('sh', ['-c', 'command -v git'], { encoding: 'utf8' }).trim()

// Run the shipped block inside a throwaway clone and report what `PUSHED` ended up as. `<UNSET>`
// is a distinct, catchable result — the whole defect is that it used to be reachable.
//
// The block runs with a shim `git` and `sleep` first on PATH. `git` logs its argv and delegates to
// the real binary, so the gate can assert WHICH commands ran — the only way to tell a guard that
// confirmed containment (no push) from one that fell through and pushed, since both call
// `ls-remote` and both can end at `PUSHED=yes`. `sleep` is a no-op so the eight-attempt backoff
// loop costs milliseconds; the loop's control flow is what is under test, not its wall clock.
const runPushBlock = (
  block,
  {
    deleteRemoteBranch = false,
    commitsAhead = 0,
    forcePushRemote = false,
    remoteAhead = false,
    unreachableRemote = false,
    blankHeadSha = false,
    // BOS-860: the pre-push tag injection's own failure shapes. Each one must record an outcome
    // and leave the push untouched — a tag is never worth withholding the commits over.
    ghFails = false,
    noPrForBranch = false,
    injectorFails = false,
    noToolbox = false,
    // An uncommitted change to a TRACKED file — the one shape the injector's rebase refuses to
    // start on ("cannot rebase: You have unstaged changes"). Untracked dirt is a different case,
    // below: a rebase runs straight past it, so counting it as dirty would disable the whole
    // injection over one leftover scratch artifact.
    dirtyTree = false,
    untrackedOnly = false,
    // BOS-860 round 2: the containment guard's own inputs. `git ls-remote` failing and the branch
    // simply not existing are indistinguishable once stderr is discarded, and an unfetchable
    // advertised commit makes ancestry undecidable — both must fail CLOSED rather than licensing an
    // unguarded rewrite, which only an advertised-NOTHING remote does.
    lsRemoteFails = false,
    fetchBranchFails = false,
    // A commit the injector cannot rewrite (the real one fast-forwards over commits whose amend is
    // rejected, keeping their SHA). This is the shape the feature exists for: origin holds a commit
    // that stays put, the guard therefore holds, and the run's own commits are tagged and pushed.
    injectorKeeps = '',
    // BOS-860 round 3: the injector leaves a DETACHED HEAD carrying the rewrite while the branch ref
    // — the ref the loop actually pushes — still points at the untagged original. Reading `HEAD` for
    // the tag outcome would then report `all` for a branch that carries no tag at all.
    injectorDetaches = false,
    // BOS-860 review round 1: run the shipped block under `set -euo pipefail`. An orchestrator's
    // bash block may well be strict, and under errexit a BARE `VAR=$(cmd)` takes the substitution's
    // status — so a `gh` or `git merge-base` that fails aborts the whole block BEFORE the push,
    // which is precisely the gate the route forbids. Every non-strict run here is blind to it.
    errexit = false,
    // `git merge-base HEAD origin/<base>` fails: the shape the post-loop re-derivation's own
    // `[ -z "$TAG_RANGE_BASE" ]` arm exists to handle, and the one it never reached under errexit.
    mergeBaseFails = false,
    // The containment rollback's own `git reset --hard` fails (an index or ref lock is the real
    // shape). The arm exists to UNDO an unsafe rewrite, so an abort here leaves the branch
    // rewritten and unpushed, and a `skipped` report there asserts a rewrite that did happen did
    // not. Only the block's own reset is failed — the injector's is not, or the rewrite the
    // rollback exists to undo would never happen and the arm would go unreached.
    resetFails = false,
    // BOS-860 extension round 1: `git rev-parse --short HEAD` fails on the RESCUE path. The suffix
    // is what makes the rescue ref unique, and an empty one builds the invalid ref
    // `refs/heads/<branch>-blocked-` that no push can create — so the `$$` fallback is the last
    // thing standing between an unpushable branch and commits that never leave the worktree.
    shortHeadFails = false,
    // BOS-860 extension round 2: the reconcile in the retry loop drops EVERY commit this run made,
    // because the same patch reached the base branch by another path — the case the post-loop
    // re-derivation exists for. The range it then scans is empty, which satisfies "every commit
    // carries the tag" vacuously and must not be reported as an observation of a tag.
    reconcileDropsRange = false,
  } = {},
) => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'boss-build-push-'))
  const git = (cwd, ...args) => execFileSync('git', args, { cwd, encoding: 'utf8', stdio: 'pipe' })
  const remote = path.join(tmp, 'remote.git')
  const wc = path.join(tmp, 'wc')
  const other = path.join(tmp, 'other')
  const shim = path.join(tmp, 'shim')
  const gitLogFile = path.join(tmp, 'git-argv.log')
  // A private HOME, so the `$HOME/.claude/skills` → `$HOME/.codex/skills` resolution the block
  // performs can only ever find the fixture toolbox below — never a real one installed on the
  // machine running the gate, which would make `noToolbox` silently untestable.
  const home = path.join(tmp, 'home')
  const toolbox = path.join(home, '.claude', 'skills', 'boss-build', 'toolbox')
  const tagLogFile = path.join(tmp, 'inject.log')
  const author = (dir) => {
    git(dir, 'config', 'user.email', 'gate@example.test')
    git(dir, 'config', 'user.name', 'gate')
    // Throwaway fixture commits gain nothing from a signature, and signing every one of them puts
    // real pressure on a shared gpg-agent — which fails with "Cannot allocate memory" under the
    // parallel test processes `make test` spawns, turning an environment limit into a fake red.
    git(dir, 'config', 'commit.gpgsign', 'false')
    git(dir, 'config', 'tag.gpgsign', 'false')
  }
  const commit = (dir, subject) => {
    fs.writeFileSync(path.join(dir, `${subject}.txt`), `${subject}\n`)
    git(dir, 'add', '-A')
    git(dir, 'commit', '-q', '-m', subject)
  }
  git(tmp, 'init', '-q', '--bare', remote)
  git(tmp, 'clone', '-q', remote, wc)
  author(wc)
  git(wc, 'commit', '-q', '--allow-empty', '-m', 'base')
  git(wc, 'push', '-q', '-u', 'origin', 'HEAD:main')
  git(wc, 'checkout', '-q', '-b', 'feat')
  commit(wc, 'work')
  git(wc, 'push', '-q', '-u', 'origin', 'feat')
  for (let i = 0; i < commitsAhead; i++) commit(wc, `ahead-${i}`)

  // Every mutation below moves the SERVER without refreshing this clone's tracking ref, which is
  // exactly the state in which `@{upstream}..HEAD` reads zero while the claim it implies is false.
  //
  // The branch is deleted server-side: the name is gone (round 4's case).
  if (deleteRemoteBranch) git(tmp, `--git-dir=${remote}`, 'branch', '-D', 'feat')
  // The branch is force-pushed to a DIVERGENT commit: the name still exists, at a commit that does
  // not contain HEAD. Existence-checking passes here; containment-checking must not.
  if (forcePushRemote) {
    git(tmp, 'clone', '-q', remote, other)
    author(other)
    git(other, 'checkout', '-q', 'main')
    commit(other, 'divergent')
    git(other, 'push', '-q', '--force', 'origin', 'HEAD:refs/heads/feat')
  }
  // The branch moved AHEAD of HEAD but still contains it — someone pushed on top. The work is
  // safe, so the honest answer is `yes` with no push attempted.
  if (remoteAhead) {
    git(tmp, 'clone', '-q', remote, other)
    author(other)
    git(other, 'checkout', '-q', 'feat')
    commit(other, 'extra')
    git(other, 'push', '-q', 'origin', 'feat')
  }
  // Someone else landed this run's patch on the base branch and moved `feat` onto it. The push is
  // rejected, the reconcile rebases onto what was fetched, and every local commit — tagged copy
  // included — is dropped as PATCH-identical, leaving `HEAD` at a commit the base already contains.
  // The re-derivation's range is then empty. Only `feat` is stale in this clone: the worktree's
  // view of the base branch is current, which is what makes the merge-base land on `HEAD` itself.
  if (reconcileDropsRange) {
    git(tmp, 'clone', '-q', remote, other)
    author(other)
    git(other, 'checkout', '-q', 'main')
    fs.writeFileSync(path.join(other, 'work.txt'), 'work\n')
    git(other, 'add', '-A')
    git(other, 'commit', '-q', '-m', 'work (landed by another route)')
    git(other, 'push', '-q', 'origin', 'HEAD:refs/heads/main')
    git(other, 'push', '-q', '--force', 'origin', 'HEAD:refs/heads/feat')
    git(wc, 'fetch', '-q', 'origin', 'main')
  }
  if (unreachableRemote) git(wc, 'remote', 'set-url', 'origin', path.join(tmp, 'gone.git'))

  fs.mkdirSync(shim)
  fs.writeFileSync(
    path.join(shim, 'git'),
    `#!/bin/sh\nprintf '%s\\n' "$*" >> "$BOSS_GATE_GIT_LOG"\n` +
      // Simulates an unresolvable HEAD so the gate can prove an empty advertised SHA is never
      // allowed to compare equal to an empty local SHA on the way to "already pushed".
      `if [ -n "$BOSS_GATE_BLANK_HEAD" ] && [ "$*" = "rev-parse HEAD" ]; then exit 0; fi\n` +
      // A remote the run cannot ASK (no network, no auth, a hung server). The branch may be fully
      // published; nothing here says otherwise, which is the point.
      `case "$*" in\n` +
      `  ls-remote*) [ -n "$BOSS_GATE_LS_FAIL" ] && exit 128 ;;\n` +
      // The advertised commit cannot be brought local, so ancestry against it is undecidable.
      `  'fetch -q origin feat') [ -n "$BOSS_GATE_FETCH_FAIL" ] && exit 128 ;;\n` +
      // Only the two-arg range form the re-derivation uses — never `merge-base --is-ancestor`,
      // which the containment guard depends on and which must keep answering honestly.
      `  'merge-base HEAD origin/'*) [ -n "$BOSS_GATE_MERGE_BASE_FAIL" ] && exit 128 ;;\n` +
      // The rollback's own reset. The injector strips this flag from the environment it hands its
      // own git calls, so only the block's reset is failed here.
      `  'reset --hard'*) [ -n "$BOSS_GATE_RESET_FAIL" ] && exit 128 ;;\n` +
      // The rescue path's suffix read. Only the `--short` form — the plain `rev-parse HEAD` reads
      // elsewhere on the route have their own flag and their own guards.
      `  'rev-parse --short HEAD') [ -n "$BOSS_GATE_SHORT_HEAD_FAIL" ] && exit 128 ;;\n` +
      `esac\n` +
      `exec ${REAL_GIT} "$@"\n`,
    { mode: 0o755 },
  )
  // `gh` answers the two reads the injection step makes: which PR this branch maps to, and what
  // that PR's base branch is. `BOSS_GATE_GH_FAIL` makes both unavailable, which is the shape a
  // missing token, a rate limit, or a branch with no open PR all present as.
  fs.writeFileSync(
    path.join(shim, 'gh'),
    `#!/bin/sh\nprintf 'gh %s\\n' "$*" >> "$BOSS_GATE_GIT_LOG"\n` +
      `[ -n "$BOSS_GATE_GH_FAIL" ] && exit 1\n` +
      `case "$*" in\n` +
      // A branch with no open PR: the query SUCCEEDS and returns nothing. Distinct from `gh`
      // failing outright, and the only shape that isolates the empty-PR-number guard.
      `  'pr list'*) [ -n "$BOSS_GATE_NO_PR" ] || printf '7\\n' ;;\n` +
      `  'pr view'*) printf 'main\\n' ;;\n` +
      `  *) exit 1 ;;\n` +
      `esac\n`,
    { mode: 0o755 },
  )
  if (!noToolbox) {
    fs.mkdirSync(path.join(toolbox, 'finalize'), { recursive: true })
    // Stands in for the shipped finalize CLI: it records the argv it was invoked with (so the gate
    // can prove the PR number is passed POSITIONALLY — a flag form would tag commits with a literal
    // `[#--pr]`), then does what the real injector does, which is REWRITE every commit since the
    // base to carry the tag. That rewrite is the hazard the containment check exists to catch.
    fs.writeFileSync(
      path.join(toolbox, 'finalize', 'cli.mjs'),
      [
        `import { execFileSync } from 'node:child_process'`,
        `import fs from 'node:fs'`,
        `const [cmd, pr] = process.argv.slice(2)`,
        `const base = process.env.BASE_BRANCH`,
        `fs.appendFileSync(process.env.BOSS_GATE_TAG_LOG, cmd + ' ' + (pr ?? '') + ' base=' + (base ?? '') + '\\n')`,
        `if (process.env.BOSS_GATE_INJECT_FAIL) process.exit(1)`,
        // The injector's own git calls never see BOSS_GATE_RESET_FAIL: that flag models a lock the
        // BLOCK's rollback trips over, and failing the injector's reset too would stop the rewrite
        // the rollback exists to undo from ever happening.
        `const git = (...a) =>`,
        `  execFileSync('git', a, {`,
        `    encoding: 'utf8',`,
        `    env: { ...process.env, BOSS_GATE_RESET_FAIL: '' },`,
        `  }).trim()`,
        `let baseRef = base`,
        `try { git('rev-parse', '--verify', 'origin/' + base); baseRef = 'origin/' + base } catch {}`,
        `const shas = git('rev-list', '--reverse', baseRef + '..HEAD').split('\\n').filter(Boolean)`,
        // The real injector is a `git rebase <base> --exec`, which FAST-FORWARDS over any commit it
        // leaves unchanged — that commit keeps its SHA. BOSS_GATE_INJECT_KEEP models exactly that:
        // rewind only as far as the last commit it must preserve, and rewrite what follows.
        `const keep = process.env.BOSS_GATE_INJECT_KEEP`,
        `let resetTo = baseRef`,
        `let start = 0`,
        `if (keep) {`,
        `  for (let i = 0; i < shas.length; i++) {`,
        `    if (git('log', '-1', '--format=%s', shas[i]).includes(keep)) { resetTo = shas[i]; start = i + 1 }`,
        `  }`,
        `}`,
        // A rewrite that never reaches the branch ref: the real route lands here when the injector
        // leaves a rebase mid-flight and BOTH the abort and the re-attach fail.
        `if (process.env.BOSS_GATE_INJECT_DETACH) git('checkout', '--quiet', '--detach', 'HEAD')`,
        `git('reset', '--hard', resetTo)`,
        `for (const sha of shas.slice(start)) {`,
        `  git('cherry-pick', sha)`,
        `  const subject = git('log', '-1', '--format=%s')`,
        `  if (!subject.includes('[#' + pr + ']')) git('commit', '--amend', '-q', '-m', subject + ' [#' + pr + ']')`,
        `}`,
        ``,
      ].join('\n'),
    )
  }
  // `work.txt` is committed by `commit(wc, 'work')` above, so this is an unstaged change to a
  // tracked path — not a new file, which `git status --porcelain --untracked-files=no` ignores.
  if (dirtyTree) fs.writeFileSync(path.join(wc, 'work.txt'), 'locally modified\n')
  // Deliberately a name no global gitignore is likely to match: an ignored path never appears in
  // `git status --porcelain` at all, which would make the untracked case vacuous.
  if (untrackedOnly) fs.writeFileSync(path.join(wc, 'scratch-artifact.txt'), 'left behind\n')
  fs.writeFileSync(
    path.join(shim, 'sleep'),
    `#!/bin/sh\nprintf 'sleep %s\\n' "$*" >> "$BOSS_GATE_GIT_LOG"\nexit 0\n`,
    {
      mode: 0o755,
    },
  )

  // TAGGED first, PUSHED last: the parse below slices from the LAST `PUSHED=`. `TAGNOTE` rather
  // than `TAG_NOTE` so the line-anchored `^TAGGED=` read cannot straddle it.
  //
  // Emitted from an EXIT trap, not from a trailing line, so an errexit run that aborts MID-block
  // still reports the variables as they stood — the alternative loses the whole result to a
  // non-zero exit and the gate can then only say "something failed", never where or with what.
  // No single quote anywhere in `emit`: it is embedded inside `trap '…' EXIT`, and single-quoting
  // the trap body is what defers the `${…}` reads to trap time rather than definition time.
  const emit =
    `printf "TAGGED=%s\\nTAGNOTE=%s\\nTAGINJECTNOTE=%s\\nPUSHED=%s" ` +
    `"\${TAGGED:-<UNSET>}" "\${TAG_NOTE:-<UNSET>}" "\${TAG_INJECT_NOTE:-<UNSET>}" ` +
    `"\${PUSHED:-<UNSET>}"`
  let aborted = false
  const run = () =>
    execFileSync(
      'bash',
      [
        '-c',
        // The strict runs use the full `set -euo pipefail` an orchestrator is likeliest to write,
        // not `-e` alone: `-u` would abort on a variable an arm forgot to assign, and `pipefail`
        // makes a pipeline take its FIRST failing stage's status — both are ways this block can
        // gate the push that plain errexit never sees. The non-strict runs stay `+u`, so the two
        // together still separate "needs a guard" from "aborts under strictness".
        `set +u\ntrap '${emit}' EXIT\n${errexit ? 'set -euo pipefail\n' : ''}` +
          // `exit 0` so the block's own trailing status cannot masquerade as an errexit abort.
          `SESSION_BRANCH=feat\n${block}\nexit 0\n`,
      ],
      {
        cwd: wc,
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'ignore'],
        env: {
          ...process.env,
          PATH: `${shim}${path.delimiter}${process.env.PATH}`,
          HOME: home,
          // Explicitly empty rather than absent: `${BOSS_SKILLS_HOME:-…}` must fall back to the
          // private HOME above even when the machine running the gate exports a real one.
          BOSS_SKILLS_HOME: '',
          BOSS_GATE_GIT_LOG: gitLogFile,
          BOSS_GATE_TAG_LOG: tagLogFile,
          BOSS_GATE_BLANK_HEAD: blankHeadSha ? '1' : '',
          BOSS_GATE_GH_FAIL: ghFails ? '1' : '',
          BOSS_GATE_NO_PR: noPrForBranch ? '1' : '',
          BOSS_GATE_INJECT_FAIL: injectorFails ? '1' : '',
          BOSS_GATE_INJECT_KEEP: injectorKeeps,
          BOSS_GATE_INJECT_DETACH: injectorDetaches ? '1' : '',
          BOSS_GATE_LS_FAIL: lsRemoteFails ? '1' : '',
          BOSS_GATE_FETCH_FAIL: fetchBranchFails ? '1' : '',
          BOSS_GATE_MERGE_BASE_FAIL: mergeBaseFails ? '1' : '',
          BOSS_GATE_RESET_FAIL: resetFails ? '1' : '',
          BOSS_GATE_SHORT_HEAD_FAIL: shortHeadFails ? '1' : '',
          // `git status` reads the user's global excludes, so a fixture file the machine running the
          // gate happens to ignore would silently stop being "dirty". Pin the config to this repo.
          GIT_CONFIG_GLOBAL: '/dev/null',
          GIT_CONFIG_SYSTEM: '/dev/null',
          // …and git's DEFAULT excludes file is `$XDG_CONFIG_HOME/git/ignore`, which the two pins
          // above do not cover. Inherited from the machine, it could ignore the untracked fixture
          // artifact and pass the untracked-only row for the wrong reason. Point it at the private
          // HOME, where no such file exists.
          XDG_CONFIG_HOME: path.join(home, '.config'),
        },
      },
    )
  let out
  try {
    out = run()
  } catch (err) {
    // A non-zero exit means the block never reached its own `exit 0` — under errexit, that IS the
    // abort. Keep the trap's output so the assertion can still name where it stopped.
    aborted = true
    out = typeof err.stdout === 'string' ? err.stdout : ''
  }
  const gitLog = fs.existsSync(gitLogFile)
    ? fs.readFileSync(gitLogFile, 'utf8').split('\n').filter(Boolean)
    : []
  const remoteSubjects = (() => {
    try {
      return git(tmp, `--git-dir=${remote}`, 'log', '--format=%s', 'refs/heads/feat')
        .split('\n')
        .filter(Boolean)
    } catch {
      return null
    }
  })()
  const tagLog = fs.existsSync(tagLogFile)
    ? fs.readFileSync(tagLogFile, 'utf8').split('\n').filter(Boolean)
    : []
  fs.rmSync(tmp, { recursive: true, force: true })
  // Read every field out of the TRAP's own printf rather than out of the whole stdout: the block
  // echoes diagnostics of its own before the trap fires, and a line-anchored `^TAGGED=` read over
  // everything would take the FIRST such line as authoritative while `PUSHED` was already read from
  // the LAST — two fields sourced from different places the moment any of them collides.
  const emittedAt = out.lastIndexOf('TAGGED=')
  const emitted = emittedAt >= 0 ? out.slice(emittedAt) : ''
  return {
    pushed: emitted.slice(emitted.lastIndexOf('PUSHED=') + 'PUSHED='.length),
    tagged: (emitted.match(/^TAGGED=(.*)$/m) ?? [, '<ABSENT>'])[1],
    tagNote: (emitted.match(/^TAGNOTE=(.*)$/m) ?? [, '<ABSENT>'])[1],
    tagInjectNote: (emitted.match(/^TAGINJECTNOTE=(.*)$/m) ?? [, '<ABSENT>'])[1],
    // The block exited before its own `exit 0` — under errexit, an abort.
    aborted,
    remoteHas: remoteSubjects !== null,
    remoteSubjects: remoteSubjects ?? [],
    // `git push …` as the block invokes it; the shim logs argv verbatim.
    attemptedPush: gitLog.some((l) => /^push\b/.test(l)),
    fetched: gitLog.some((l) => /^fetch\b/.test(l)),
    // The rescue ref the block actually asked origin to create, read out of the shim's argv log so
    // it is observable even when the push itself fails. `null` when no rescue push was attempted;
    // the empty-suffix defect surfaces here as the trailing-hyphen ref `feat-blocked-`.
    rescueRef: (gitLog
      .map((l) => /^push\s+origin\s+HEAD:refs\/heads\/(\S*)$/.exec(l))
      .find(Boolean) ?? [, null])[1],
    // Argv the injection step handed the finalize CLI, verbatim.
    injectArgv: tagLog,
  }
}

test('BOS-758 P2: the push block leaves no route with PUSHED unset (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const block = pushBlockOf(reviewStack)

    // The route the review found: a resumed branch already level with its upstream. It used to
    // skip the entire block and reach the handoff with no value at all.
    const level = runPushBlock(block)
    assert.equal(
      level.pushed,
      'yes',
      `${dir}: a branch with nothing to push must report PUSHED=yes, not an unset variable`,
    )
    assert.equal(
      level.attemptedPush,
      false,
      `${dir}: a branch whose remote is already AT HEAD must not push at all`,
    )

    // Commits ahead, remote healthy: unchanged behaviour.
    const ahead = runPushBlock(block, { commitsAhead: 2 })
    assert.equal(ahead.pushed, 'yes', `${dir}: a successful push must report PUSHED=yes`)
    assert.equal(ahead.attemptedPush, true, `${dir}: real commits ahead must actually be pushed`)

    // The reason `PUSHED=yes` may NOT simply be seeded on the zero-ahead test. The local tracking
    // ref still resolves and still reads zero-ahead, yet origin holds nothing. A seeded `yes`
    // would claim the work is stored remotely while it exists only in this worktree.
    const stale = runPushBlock(block, { deleteRemoteBranch: true })
    assert.ok(
      stale.remoteHas,
      `${dir}: a stale zero-ahead reading must fall through to the push, not claim the remote already has the work`,
    )
    assert.equal(
      stale.pushed,
      'yes',
      `${dir}: after re-pushing a server-side-deleted branch the outcome is an honest PUSHED=yes`,
    )
    assert.equal(
      stale.attemptedPush,
      true,
      `${dir}: a branch missing from origin must be pushed, not confirmed`,
    )

    // Round 5's case, and the reason EXISTENCE is not the predicate. The branch was force-pushed
    // server-side, so the name is still advertised — at a commit that does not contain HEAD. An
    // existence check passes here and claims the completed work is stored while it is only local.
    const diverged = runPushBlock(block, { forcePushRemote: true })
    assert.equal(
      diverged.attemptedPush,
      true,
      `${dir}: a remote advertising the branch at a DIVERGENT commit must be pushed to, not accepted as proof the work is stored`,
    )
    assert.ok(
      // `startsWith`, not equality: origin advertises a DIVERGENT commit, so this run's `work`
      // commit is unpublished and the tag injection legitimately rewrites its subject to
      // `work [#7]`. The property under test is that the commit reaches origin, not its subject.
      diverged.remoteSubjects.some((s) => s.startsWith('work')),
      `${dir}: after a server-side force-push the run must leave the work on origin, not stop with it local (remote had: ${diverged.remoteSubjects.join(', ')})`,
    )
    assert.equal(diverged.pushed, 'yes', `${dir}: recovering from a force-push ends at PUSHED=yes`)

    // The counterweight that makes CONTAINMENT — not equality — the right predicate. The remote
    // moved ahead of HEAD but still contains it, so the work is safe and a push would be pointless.
    const onTop = runPushBlock(block, { remoteAhead: true })
    assert.equal(
      onTop.pushed,
      'yes',
      `${dir}: a remote that is ahead of HEAD but still CONTAINS it already holds the work`,
    )
    assert.equal(
      onTop.attemptedPush,
      false,
      `${dir}: a remote containing HEAD must be confirmed, not pushed to — equality is the wrong test`,
    )
    assert.equal(
      onTop.fetched,
      true,
      `${dir}: an advertised SHA that is not HEAD must be FETCHED before ancestry can be claimed`,
    )

    // Every failure to confirm routes to the push arm, and from there to an honest verdict —
    // never to `yes`. A dead remote cannot persist anything, and the block must say so.
    const dead = runPushBlock(block, { unreachableRemote: true })
    assert.equal(
      dead.pushed,
      'no',
      `${dir}: an unreachable remote must fall through to the push arm and report the honest failure`,
    )
    assert.equal(dead.attemptedPush, true, `${dir}: an unreachable remote must still be tried`)

    // Fail-closed on empty strings: with HEAD unresolvable AND the remote unreachable, both SHAs
    // are empty. Comparing them without a non-empty test would read "" = "" as "already pushed".
    const blank = runPushBlock(block, { unreachableRemote: true, blankHeadSha: true })
    assert.notEqual(
      blank.pushed,
      'yes',
      `${dir}: an empty advertised SHA must never compare equal to an empty HEAD and confirm a push`,
    )

    // Structural counterpart: the value must be assigned INSIDE the arms, never seeded above the
    // conditional where a future unassigned path would inherit "the work is safe". Anchor at
    // line start under /m so a commented-out `# PUSHED=yes` cannot satisfy either check.
    const preamble = block.slice(0, block.search(/^if \[ "\$REMOTE_HAS_HEAD"/m))
    assert.doesNotMatch(
      preamble,
      /^\s*PUSHED=/m,
      `${dir}: PUSHED must not be initialized above the conditional — that defaults the run to "already safe"`,
    )
    assert.match(
      block,
      /^if \[ "\$REMOTE_HAS_HEAD" = yes \][^\n]*\n\s*PUSHED=yes$/m,
      `${dir}: the confirmed arm must assign PUSHED=yes explicitly`,
    )
    assert.match(
      block,
      /^else$\n\s*PUSHED=no$/m,
      `${dir}: the push arm must still default to PUSHED=no before any attempt`,
    )
    // Same fail-closed discipline one level down: the confirmation flag is seeded `no`, so a path
    // that reaches the conditional without proving containment can only route to the push. This is
    // the one property the fixtures cannot show — they exercise the paths that DO exist today.
    assert.match(
      block,
      /^REMOTE_HAS_HEAD=no$/m,
      `${dir}: the containment flag must start at "no" so only a positive proof can confirm`,
    )
    assert.doesNotMatch(
      block,
      /^REMOTE_HAS_HEAD=yes$/m,
      `${dir}: REMOTE_HAS_HEAD=yes must be set inside the proof arms, never at top level`,
    )

    // And the prose must carry the reasoning, so a later round does not "simplify" the guard away.
    assert.match(
      reviewStack,
      /never\s+initialize\s+it\s+above\s+the\s+conditional/i,
      `${dir}: the section must forbid seeding PUSHED above the conditional`,
    )
    assert.match(
      reviewStack,
      /Zero\s+commits\s+ahead\s+is\s+not\s+by\s+itself/i,
      `${dir}: the section must state that zero-ahead does not by itself mean the work is on the remote`,
    )
    // Pin the NEW clause, not only its predecessor: fixing a paragraph relocates the defect, and
    // the sentence above is now satisfied by an existence check that this round proved insufficient.
    assert.match(
      reviewStack,
      /existing[^\n]*\s+is\s+not\s+enough\s+either[\s\S]{0,400}?contain/i,
      `${dir}: the section must state that the branch merely EXISTING on origin does not prove the remote contains HEAD`,
    )
    assert.match(
      reviewStack,
      /Containment,\s+not\s+equality/i,
      `${dir}: the section must say why containment — not equality — is the predicate`,
    )
    // The other half of the force-push case: `git pull --rebase`'s fork-point heuristic reads the
    // STALE origin/<branch> reflog entry and drops this run's commits, so the retry that follows a
    // refused confirmation would push a branch the work is no longer on.
    // Executable lines only: the block legitimately NAMES the banned form in a comment explaining
    // why it is banned, and that comment must not read as a violation of its own rule.
    const runnable = block
      .split('\n')
      .filter((l) => !/^\s*#/.test(l))
      .join('\n')
    assert.doesNotMatch(
      runnable,
      /git\s+pull --rebase/,
      `${dir}: the retry loop must not reconcile with git pull --rebase — fork-point drops this run's commits after a server-side force-push`,
    )
    assert.match(
      runnable,
      /git[ ]rebase --no-fork-point[ ]FETCH_HEAD/,
      `${dir}: the retry loop must reconcile by rebasing onto the ref it just fetched`,
    )
    assert.match(
      reviewStack,
      /Reconcile\s+with\s+`git\s+rebase\s+--no-fork-point\s+FETCH_HEAD`/i,
      `${dir}: the section must state which reconcile form is required, and why pull --rebase is not it`,
    )
  }
})

// Discriminate by SUBSTITUTION KIND, never by the variable's spelling. `$(` and a backtick both run
// a command whose status a bare assignment takes; `$((` runs none, so an arithmetic assignment is
// exempt however loudly it is named — and a lowercase capture is the same hazard as an uppercase
// one, so both are in.
//
// Cover every SPELLING too, not just the kinds — and that is what rules out matching a PREFIX of the
// right-hand side. `VAR="$(…)"` is the house idiom a few blocks up this same file and
// `VAR=${X:-$(…)}` runs its default the moment `X` is unset; but so do `VAR="on $(…)"` and
// `VAR=pre-$(…)`, where the substitution is INTERPOLATED into a larger word. Those take the
// substitution's status exactly as the bare form does — `RESCUE="$SESSION_BRANCH-blocked-$(git
// rev-parse --short HEAD)"` aborts the block under errexit precisely where the tailed capture it
// would replace does not — yet a matcher anchored just after the `=` scores them as no capture at
// all. A gate that claims a universal and then stops at the first spelling the next editor reaches
// for teaches that editor the rule is decorative.
//
// So scan the assignment's whole RHS WORD rather than pattern-matching its head. Quote- and
// nesting-aware, because both exemptions then fall out of the scan instead of each needing a special
// case: nothing substitutes inside `'…'`, and `$((…))` runs no command. Where the word ENDS is the
// other half of the answer — that is where the `|| VAR=` tail has to start, so a `||` living INSIDE
// the substitution can no longer be miscounted as one.
// One scanner answers both questions this gate asks, because both need the same shell-quoting
// state: inside `'…'` nothing is special, inside `"…"` a `$(` still runs while a `#` starts no
// comment, and `$(…)`/`${…}`/`$((…))` nest. They differ only in where they stop.
//   mode 'word'    — stop at the unquoted delimiter ending an assignment's RHS word.
//   mode 'comment' — stop at the unquoted `#` starting a trailing comment; delimiters are ordinary
//                    text there, because a comment may follow anything.
// `${…}` is tracked even though it expands rather than runs: it NESTS, so an unquoted
// `X=${Y:- $(cmd)}` carries a brace-internal space that must not end the word — and `sh -e` really
// does abort on that one, so scoring it "no capture" is the same blindness as the anchored matcher.
const shellScan = (s, start, mode) => {
  const open = []
  let runs = false
  let i = start
  while (i < s.length) {
    const top = open[open.length - 1]
    const c = s[i]
    if (top === "'") {
      if (c === "'") open.pop()
      i += 1
    } else if (c === '\\') {
      i += 2
    } else if (c === '$' && s[i + 1] === '(' && s[i + 2] === '(') {
      open.push('$((')
      i += 3
    } else if (c === ')' && top === '$((' && s[i + 1] === ')') {
      open.pop()
      i += 2
    } else if (c === '$' && s[i + 1] === '(') {
      open.push('$(')
      runs = true
      i += 2
    } else if (c === ')' && top === '$(') {
      open.pop()
      i += 1
    } else if (c === '$' && s[i + 1] === '{') {
      open.push('${')
      i += 2
    } else if (c === '}' && top === '${') {
      open.pop()
      i += 1
    } else if (c === '`') {
      if (top === '`') open.pop()
      else {
        open.push('`')
        runs = true
      }
      i += 1
    } else if (c === '"') {
      if (top === '"') open.pop()
      else open.push('"')
      i += 1
    } else if (c === "'") {
      // Inside `"…"` a quote is literal; anywhere else it opens a single-quoted string.
      if (top !== '"') open.push("'")
      i += 1
    } else if (
      mode === 'comment' &&
      c === '#' &&
      open.length === 0 &&
      (i === 0 || /\s/.test(s[i - 1]))
    ) {
      break
    } else if (mode === 'word' && open.length === 0 && /[\s;&|()<>]/.test(c)) {
      break
    } else {
      i += 1
    }
  }
  return { end: i, runs }
}

const rhsWord = (s, start) => shellScan(s, start, 'word')
// `runnable` drops whole-line comments only, so a TRAILING one still reaches the gate — and the
// block's own commentary writes `|| VAR=` as a literal repeatedly, which would read as a tail the
// capture does not have.
const stripComment = (s) => s.slice(0, shellScan(s, 0, 'comment').end)

// Match anywhere in the statement rather than only at its start: continuation lines are joined
// before this runs, so a capture written on the second line of one is mid-statement by the time this
// reads it. The one exemption is a CONDITION context (`if`/`elif`/`while`/`until`, with or without
// `!`), because errexit itself exempts those — and a `$(…)` inside `[ … ]` is not an assignment, so
// it never matches to begin with.
const CONDITION = /(?:^|[;&|(]|\bthen\b|\bdo\b|\belse\b)\s*(?:if|elif|while|until)\s+(?:!\s+)?$/

const bareCapturesIn = (statements) => {
  const bare = []
  // Built per call, never shared: the scan below DRIVES `lastIndex` to skip words it has already
  // consumed, so a module-level `/g` regex would carry one call's cursor into the next.
  const ASSIGN = /([A-Za-z_][A-Za-z0-9_]*)=/g
  for (const raw of statements) {
    const s = stripComment(raw)
    const hits = []
    ASSIGN.lastIndex = 0
    let m
    while ((m = ASSIGN.exec(s)) !== null) {
      const before = s.slice(0, m.index)
      // An assignment starts a word: `--flag=$(…)` and `"$prefix"=$(…)` are not one.
      if (/[\w./-]$/.test(before)) continue
      const { end, runs } = rhsWord(s, m.index + m[0].length)
      // Never re-enter a word already scanned: `awk -v ref="…"` inside one capture's RHS is not a
      // second assignment, and reading it as one would search the wrong region for the wrong tail.
      ASSIGN.lastIndex = Math.max(end, ASSIGN.lastIndex)
      if (!runs || CONDITION.test(before)) continue
      hits.push({ name: m[1], start: m.index, end })
    }
    for (const [i, hit] of hits.entries()) {
      // Each capture needs its OWN tail, so the region searched ENDS where the next capture begins —
      // otherwise one tailed capture silently exempts every bare one sharing its line. Anchor the
      // match at the word's end too: `||` only guards the command it is ATTACHED to, so in
      // `X=$(cmd); [ -n "$X" ] || X=fallback` the tail belongs to the `[` and `X=$(cmd)` still
      // aborts. An unanchored search over the region reads that as tailed, which is the same
      // false negative as missing the capture outright.
      const until = i + 1 < hits.length ? hits[i + 1].start : s.length
      if (/^\s*\|\|\s*[A-Za-z_][A-Za-z0-9_]*=/.test(s.slice(hit.end, until))) continue
      bare.push(`${hit.name}: ${s.trim()}`)
    }
  }
  return bare
}

test('BOS-860 ext3: the errexit-capture matcher sees an interpolated substitution', () => {
  // The gate below asserts a UNIVERSAL over the shipped block, so it is worth exactly what it can
  // see — and today the block happens to spell every capture as a whole right-hand side, so the
  // anchored matcher this replaces passed while covering only that one spelling. Nothing in the
  // suite could tell the two apart: no fixture falsified either, so widening the matcher would have
  // looked identical to leaving the hole in. These are the mutants that tell them apart. Each is a
  // statement the block could plausibly acquire, and each must be REPORTED bare and then CLEARED by
  // its own tail — one direction alone would pass on a matcher that flags everything.
  const bare = (s) => bareCapturesIn([s])
  for (const [label, stmt] of [
    ['the bare house idiom', 'RESCUE_SUFFIX=$(git rev-parse --short HEAD 2>/dev/null)'],
    ['a quoted whole RHS', 'RESCUE_SUFFIX="$(git rev-parse --short HEAD 2>/dev/null)"'],
    [
      'a substitution interpolated into a quoted word',
      'RESCUE="$SESSION_BRANCH-blocked-$(git rev-parse --short HEAD)"',
    ],
    [
      'a substitution interpolated into an unquoted word',
      'RESCUE=$SESSION_BRANCH-blocked-$(git rev-parse --short HEAD)',
    ],
    ['a backtick interpolated into a quoted word', 'RESCUE="blocked-`git rev-parse --short HEAD`"'],
    ['a default that runs a command', 'PR_NUMBER="${PR_NUMBER:-$(gh pr list -q .number)}"'],
    ['an interpolated default that runs a command', 'RESCUE="x-${SUFFIX:-$(git rev-parse HEAD)}"'],
    // Unquoted, and with a space inside the braces. `${…}` expands rather than runs, but it nests,
    // so a scanner that does not track it ends the word at that space and reports nothing — while
    // `sh -e` aborts on it just the same (asserted against the real shell below).
    ['an unquoted brace default holding a space', 'X=${Y:- $(git rev-parse HEAD)}'],
  ]) {
    assert.equal(
      bare(stmt).length,
      1,
      `a capture with no tail must be reported when it is ${label} — under set -e it aborts the block before the push: ${stmt}`,
    )
    assert.deepEqual(
      bare(`${stmt} || RESCUE=`),
      [],
      `…and its own \`|| VAR=\` tail must clear it when it is ${label}: ${stmt}`,
    )
  }
  // The other direction: shapes that run no command, or that errexit already exempts. A matcher
  // that reported these would be widened past the property and the next editor would delete it.
  for (const [label, stmt] of [
    ['arithmetic runs no command', 'attempts=$((attempts + 1))'],
    ['a single-quoted word substitutes nothing', "MSG='cost $(nothing) at all'"],
    ['errexit exempts a condition context', 'if TAG_BASE=$(gh pr view -q .base); then'],
    ['a long-flag value is not an assignment', 'git status --untracked-files=no'],
    ['a plain value runs nothing', 'TAGGED=partial'],
  ]) {
    assert.deepEqual(bare(stmt), [], `${label}, so it must not be reported: ${stmt}`)
  }

  // Knowing where the RHS word ENDS is load-bearing, not incidental: the tail has to sit AFTER the
  // substitution, so a scan that stopped at the first `||` would read one living INSIDE it as the
  // tail and clear a capture that has none. This statement's only `|| VAR=` is inside — the shipped
  // block's `UNPUSHED=$(… || git rev-list --count HEAD) || UNPUSHED=` is the same shape one step
  // milder, and it is the reason the region is measured from the word's end rather than from `$(`.
  assert.equal(
    bare('FOO=$(cmd || BAR=1)').length,
    1,
    'a `|| VAR=` inside the substitution is not a tail — the capture it belongs to still has none',
  )
  assert.deepEqual(
    bare('FOO=$(cmd || BAR=1) || FOO='),
    [],
    '…and the real tail, outside the substitution, does clear it',
  )

  // A `||` guards only the command it is ATTACHED to. These two are the shapes that read as tailed
  // to any search that merely looks for `|| VAR=` somewhere to the right, and both really abort.
  assert.equal(
    bare('X=$(cmd); [ -n "$X" ] || X=fallback').length,
    1,
    "a `|| VAR=` belonging to a LATER command is not this capture's tail — `X=$(cmd)` still aborts under set -e",
  )
  assert.equal(
    bare('X="$(exit 7)" # note || Y=').length,
    1,
    'a `|| VAR=` inside a trailing comment is not a tail — the block writes that literal in its own commentary',
  )
  assert.deepEqual(
    bare('X="$(exit 7)" || X= # note'),
    [],
    '…while a real tail followed by a comment still clears',
  )
  // The other direction, and the one comment-stripping actually buys: a capture written INSIDE a
  // trailing comment is prose, not code. `runnable` strips whole-line comments only, and this
  // block's commentary discusses `VAR=$(cmd)` shapes constantly, so without stripping the gate
  // manufactures findings against its own explanatory text.
  assert.deepEqual(
    bare('echo hi # FOO=$(bar)'),
    [],
    'a capture written inside a trailing comment is not code and must not manufacture a finding',
  )

  // Finally, ground the whole gate in the shell rather than in this file's belief about it. The
  // rule is only worth enforcing because an interpolated substitution's status really IS the
  // assignment's, and a reader who doubts that reads a matcher and has to take it on faith. Ask
  // `sh` instead: the untailed form aborts mid-block, the tailed form runs on.
  const errexitStatus = (script) => {
    try {
      execFileSync('sh', ['-c', script], { stdio: 'pipe' })
      return 0
    } catch (e) {
      return e.status
    }
  }
  assert.equal(
    errexitStatus('set -e; X="a$(exit 7)b"; echo NOTREACHED'),
    7,
    'an interpolated substitution hands its status to the assignment exactly as a bare one does — that is the abort the gate exists to forbid, and why it may not stop at the anchored spelling',
  )
  assert.equal(
    errexitStatus('set -e; X="a$(exit 7)b" || X=; echo REACHED'),
    0,
    '…and its own `|| VAR=` tail is what keeps the block running to the push — the gate requires that tail and nothing more',
  )
  assert.equal(
    errexitStatus('set -e; X=$((1 + 1)); echo REACHED'),
    0,
    'arithmetic runs no command, so it cannot abort and the gate must keep exempting it',
  )
  assert.equal(
    errexitStatus('set -e; X=${Y:- $(exit 7)}; echo NOTREACHED'),
    7,
    'an unquoted brace default runs its substitution and aborts on it, so the scanner must track `${…}` rather than end the word at the space inside',
  )
  assert.equal(
    errexitStatus('set -e; X=$(exit 7); [ -n "$X" ] || X=fallback; echo NOTREACHED'),
    7,
    'a `||` on a LATER command does not guard this assignment — which is why the tail must be anchored to the capture',
  )
})

test('BOS-860: the BLOCKED route tags its commits before pushing, and tagging never gates the push', () => {
  // Every route in the BLOCKED-route section stops at Stop cleanly, so the finalize step that
  // injects `[#<PR>]` never runs — the commits were published untagged and nothing downstream ever
  // added the tag. The fix injects BEFORE the push (the last moment the tag is free, since a tag
  // added after publication means rewriting published history), and the property that matters most
  // is the one a naive fix breaks: a tagging failure must never cost the run its commits.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const block = pushBlockOf(reviewStack)
    const runnable = block
      .split('\n')
      .filter((l) => !/^\s*#/.test(l))
      .join('\n')

    // --- Structure: injection is before the push, and it is the shipped CLI's positional form. ---
    assert.match(
      runnable,
      /inject-pr-tag "\$PR_NUMBER"/,
      `${dir}: the push block must invoke the finalize CLI's inject-pr-tag capability`,
    )
    // Both offsets must be FOUND: `indexOf` returns -1 for a miss, and -1 < n would let a deleted
    // injection satisfy an ordering rule about it.
    const injectAt = runnable.indexOf('inject-pr-tag')
    const pushAt = runnable.indexOf('git push -u origin "$SESSION_BRANCH"')
    assert.ok(
      injectAt >= 0 && pushAt >= 0 && injectAt < pushAt,
      `${dir}: the tag must be injected BEFORE the push — injecting after it means rewriting published history (inject at ${injectAt}, push at ${pushAt})`,
    )
    assert.doesNotMatch(
      runnable,
      /inject-pr-tag[^\n]*--pr\b/,
      `${dir}: the PR number is positional; a --pr flag form tags every commit with a literal [#--pr]`,
    )
    // The advertised SHA is read once, ABOVE the zero-ahead guard: the injection's containment
    // check lives on the other arm, which the guard by definition never enters. Both offsets must
    // be found — `search` returns -1 for a miss, and -1 < n would pass this vacuously for a read
    // that moved back inside the guard (where it is indented and so no longer line-anchored).
    const remoteShaAt = runnable.search(/^REMOTE_SHA=\$\(printf/m)
    const zeroAheadGuardAt = runnable.search(/^if \[ "\$UNPUSHED" = "0" \]/m)
    assert.ok(
      remoteShaAt >= 0 && zeroAheadGuardAt >= 0 && remoteShaAt < zeroAheadGuardAt,
      `${dir}: REMOTE_SHA must be read outside the zero-ahead guard so the injection arm can use it (read at ${remoteShaAt}, guard at ${zeroAheadGuardAt})`,
    )
    // The ASK's status must be kept apart from its answer. A pipeline's `$?` is the LAST stage's, so
    // reading the SHA straight out of `git ls-remote | awk` throws git's status away and makes "the
    // remote said nothing" and "the remote could not be asked" the same value — and one of those two
    // licenses a rewrite. Assert the raw read is captured on its own, with its status recorded.
    const lsReadAt = runnable.search(/^REMOTE_LS=\$\(git[ ]ls-remote[^\n]*\|\| REMOTE_LS_OK=no$/m)
    assert.ok(
      lsReadAt >= 0 && lsReadAt < remoteShaAt,
      `${dir}: git ls-remote's own exit status must be captured before the SHA is parsed out of its output (read at ${lsReadAt})`,
    )
    assert.match(
      runnable,
      /if \[ "\$REMOTE_LS_OK" != yes \]/,
      `${dir}: a remote the run could not ask must not reach the injector as if it had advertised nothing`,
    )
    assert.match(
      runnable,
      /git[ ]reset --hard "\$PRE_INJECT_SHA"/,
      `${dir}: an injection that would rewrite a commit origin advertises must be rolled back`,
    )
    // The published outcome must be DERIVED after the loop settles, not remembered from before it:
    // `git rebase` skips commits by patch id, which ignores the message entirely, so the reconcile
    // inside the loop can drop a tagged copy of a commit origin still holds untagged.
    const rederiveAt = runnable.indexOf('TAG_RANGE_BASE=')
    const loopEndAt = runnable.indexOf('if [ "$PUSHED" != yes ]')
    assert.ok(
      rederiveAt >= 0 && loopEndAt >= 0 && rederiveAt > pushAt && rederiveAt < loopEndAt,
      `${dir}: TAGGED must be re-derived from the branch after the retry loop, between the push and the rescue ref (re-derive at ${rederiveAt}, push at ${pushAt}, rescue at ${loopEndAt})`,
    )
    // …and it must read the ref the loop PUSHES. A detached HEAD carrying the rewrite while the
    // branch still holds the untagged original is the shape the re-attach above can fail into.
    assert.match(
      runnable,
      /git[ ]rev-parse "refs\/heads\/\$SESSION_BRANCH"/,
      `${dir}: the re-derivation must confirm HEAD is still the branch before reading a tag state off it`,
    )
    // The subject read's STATUS must be kept apart from its answer: piped into `grep -qv`, the
    // status is grep's, and an unreadable range prints nothing — which reads exactly like a fully
    // tagged one and resolves to the optimistic `all`. Same defect this block teaches against for
    // `ls-remote` a few lines above.
    assert.doesNotMatch(
      runnable,
      /git\s+log --format=%s "\$TAG_RANGE_BASE\.\.HEAD"[^\n]*\|[^|]/,
      `${dir}: a pipeline's status is grep's, so the subject read must be captured before it is parsed`,
    )
    assert.match(
      runnable,
      /TAG_SUBJECTS=\$\(git[ ]log --format=%s "\$TAG_RANGE_BASE\.\.HEAD"/,
      `${dir}: capture the branch's subjects, then parse them, so an unreadable range is not read as tagged`,
    )
    // Nothing between the injection and the retry loop may end the run: an `exit`/`break`/`return`
    // there turns a benign injector status into stranded commits, which is strictly worse than the
    // untagged commits this whole change exists to fix.
    const injection = region(
      runnable,
      'TAGGED=skipped\n  TAG_NOTE="tag injection not attempted"',
      'attempts=0',
    )
    // BOS-737: no `length > 0` pin — `region()` already throws on an absent marker or an empty
    // region. Its "the injection step must sit on the push arm" message is not lost: the
    // markers ARE that claim, and the throw names whichever of them moved.
    assert.doesNotMatch(
      injection,
      /^\s*(exit|break|return)\b/m,
      `${dir}: the tag injection must never gate the push — no exit, break or return on any of its arms`,
    )

    // --- Executable: the four failure shapes each record an outcome and still push. ---
    // Each shape runs on a branch origin does NOT hold, so the injection would otherwise succeed:
    // that keeps every expectation below non-vacuous — with the guard removed the outcome changes.
    const skips = [
      [
        'no open PR maps to the branch',
        { deleteRemoteBranch: true, noPrForBranch: true },
        'skipped',
      ],
      ['the PR lookup itself fails', { deleteRemoteBranch: true, ghFails: true }, 'skipped'],
      ['the injector exits non-zero', { deleteRemoteBranch: true, injectorFails: true }, 'partial'],
      ['the finalize toolbox is absent', { deleteRemoteBranch: true, noToolbox: true }, 'skipped'],
      ['a tracked file is dirty', { deleteRemoteBranch: true, dirtyTree: true }, 'skipped'],
    ]
    for (const [label, opts, expected] of skips) {
      const run = runPushBlock(block, opts)
      assert.equal(
        run.attemptedPush,
        true,
        `${dir}: the push must still be attempted when ${label}`,
      )
      assert.equal(run.pushed, 'yes', `${dir}: the push must still SUCCEED when ${label}`)
      assert.equal(
        run.tagged,
        expected,
        `${dir}: the run must record TAGGED=${expected} when ${label}`,
      )
    }

    // --- Executable: the happy path actually tags, and the tag reaches origin. ---
    // A branch origin does not hold: every commit is unpublished, so all of them may be rewritten.
    const fresh = runPushBlock(block, { deleteRemoteBranch: true })
    // Call shape first, then its effects: a wrong invocation should name itself rather than
    // surface as a downstream "not tagged".
    assert.deepEqual(
      fresh.injectArgv,
      ['inject-pr-tag 7 base=main'],
      `${dir}: the finalize CLI must be called once, with the PR number positionally and the PR's base branch in BASE_BRANCH`,
    )
    assert.equal(fresh.tagged, 'all', `${dir}: a fully unpublished branch must be tagged`)

    // --- Executable: the dirty guard is scoped to TRACKED paths. ---
    // A rebase runs straight past an untracked file, and a message-only rewrite of commits already
    // in this history checks out no path that could clobber one. Treating `??` as dirty would let
    // one leftover scratch artifact take the whole feature to `skipped` on the route most likely to
    // have leftovers — and the commits would then publish untagged anyway, which is the defect.
    // Paired with the `dirtyTree` row above, this is what makes the narrowing load-bearing: the
    // same guard must still fire on a tracked edit and must NOT fire on this one.
    const untracked = runPushBlock(block, { deleteRemoteBranch: true, untrackedOnly: true })
    assert.equal(
      untracked.tagged,
      'all',
      `${dir}: an untracked-only worktree must still be tagged — a rebase does not refuse over one (note: ${untracked.tagNote})`,
    )
    assert.ok(
      untracked.remoteSubjects.includes('work [#7]'),
      `${dir}: the tag must reach origin with an untracked file present (remote had: ${untracked.remoteSubjects.join(', ')})`,
    )
    assert.ok(
      fresh.remoteSubjects.includes('work [#7]'),
      `${dir}: the commits pushed by the BLOCKED route must carry the PR tag (remote had: ${fresh.remoteSubjects.join(', ')})`,
    )

    // --- Executable: the injection must NOT rewrite what origin already advertises. ---
    // Origin holds `work`; this run added commits on top. Tagging rewrites `work` too, so the
    // whole injection is rolled back and the commits are published untagged rather than force-fed
    // over a commit this run may not have authored.
    const published = runPushBlock(block, { commitsAhead: 2 })
    assert.equal(
      published.tagged,
      'skipped',
      `${dir}: an injection that would rewrite an already-advertised commit must be skipped`,
    )
    // Length first: `some()` over an empty array is vacuously false, so an unread remote would
    // otherwise satisfy the assertion below without a single commit having been examined.
    assert.ok(
      published.remoteSubjects.length > 0,
      `${dir}: the rollback case must leave commits ON origin for the tag check to mean anything`,
    )
    assert.ok(
      !published.remoteSubjects.some((s) => s.includes('[#')),
      `${dir}: no already-published commit may be rewritten to add a tag (remote had: ${published.remoteSubjects.join(', ')})`,
    )
    assert.equal(published.pushed, 'yes', `${dir}: skipping the tag must not skip the push`)
    // The injector DID run here and was rolled back — which is what makes the two fail-closed
    // shapes below non-vacuous: they reach `skipped` by never running it at all.
    assert.ok(
      published.injectArgv.length > 0,
      `${dir}: the rollback case must reach the injector — otherwise it proves nothing about rollback`,
    )

    // --- Executable: a rollback that FAILS may not be reported as a rollback that happened. ---
    // Same shape as `published` above, except the rollback's own `git reset --hard` fails (an index
    // or ref lock is the real one). Two defects live here. Under errexit the bare reset is not a
    // condition, so its failure exits the arm whose entire purpose is undoing an unsafe rewrite —
    // before the push, leaving the branch rewritten AND unpushed. And with the status unread, the
    // arm goes on to report `skipped` with "injection would have rewritten…", a sentence asserting
    // the rewrite did not happen on a branch that is still carrying it.
    const rollbackFailed = runPushBlock(block, {
      commitsAhead: 2,
      resetFails: true,
      errexit: true,
    })
    assert.equal(
      rollbackFailed.aborted,
      false,
      `${dir}: under set -e a failed rollback must not abort the block before the push (got TAGGED=${rollbackFailed.tagged}, PUSHED=${rollbackFailed.pushed})`,
    )
    assert.equal(
      rollbackFailed.pushed,
      'yes',
      `${dir}: a failed rollback must not cost the run its commits`,
    )
    assert.notEqual(
      rollbackFailed.tagged,
      'skipped',
      `${dir}: a rollback that failed left the rewrite in place — reporting it as skipped asserts a rewrite that did happen did not (note: ${rollbackFailed.tagNote})`,
    )
    assert.match(
      rollbackFailed.tagInjectNote,
      /rollback/i,
      `${dir}: a failed rollback must name itself in the injector-side diagnostic (inject note: ${rollbackFailed.tagInjectNote})`,
    )
    // …and it must name the ATTEMPT, never the branch. This note is written BEFORE the retry loop
    // and never re-derived after it, while the reconcile inside that loop rebases — and a rewritten
    // copy of a commit origin still holds untagged is dropped there as patch-identical. So a note
    // claiming the branch "still carries" the rewrite publishes a state the block never observed,
    // and can be falsified by the very next line of the block that printed it.
    assert.doesNotMatch(
      rollbackFailed.tagInjectNote,
      /still\s+carries|untagged/i,
      `${dir}: the failed-rollback diagnostic may not assert what the branch carries — the re-derivation owns that, and the reconcile can falsify it (inject note: ${rollbackFailed.tagInjectNote})`,
    )

    // --- Executable: the containment guard's own inputs fail CLOSED. ---
    // A remote the run could not ASK. `deleteRemoteBranch` alone reaches TAGGED=all through these
    // same arms (`fresh` above), so the only difference here is that ancestry became undecidable.
    const unaskable = runPushBlock(block, { deleteRemoteBranch: true, lsRemoteFails: true })
    assert.deepEqual(
      unaskable.injectArgv,
      [],
      `${dir}: a remote this run could not ask is not a remote holding nothing — do not rewrite against it`,
    )
    assert.equal(unaskable.tagged, 'skipped', `${dir}: an unguardable rewrite records skipped`)
    assert.equal(unaskable.pushed, 'yes', `${dir}: an unguardable rewrite must not cost the push`)
    // An advertised commit that cannot be brought local: ancestry against it is undecidable too.
    const unfetchable = runPushBlock(block, { commitsAhead: 2, fetchBranchFails: true })
    assert.deepEqual(
      unfetchable.injectArgv,
      [],
      `${dir}: an advertised commit that will not fetch leaves the guard unable to answer — do not rewrite`,
    )
    assert.equal(unfetchable.tagged, 'skipped', `${dir}: an undecidable guard records skipped`)
    assert.equal(unfetchable.pushed, 'yes', `${dir}: an undecidable guard must not cost the push`)
    // A pre-injection HEAD the run could not read fails closed for the same reason: the rollback
    // rewinds to it, so an empty answer leaves an unsafe rewrite with nothing able to take it back.
    // (`git reset --hard ""` is not the hazard — it exits 128 and moves nothing.) Same branch shape
    // as `fresh` above, which reaches TAGGED=all through these very arms, so the only difference
    // here is the unreadable HEAD: with the arm gone the injector runs and the outcome changes.
    const noPreSha = runPushBlock(block, { deleteRemoteBranch: true, blankHeadSha: true })
    assert.deepEqual(
      noPreSha.injectArgv,
      [],
      `${dir}: a rewrite whose rollback has no target must not be started`,
    )
    assert.equal(
      noPreSha.tagged,
      'skipped',
      `${dir}: an unrollbackable rewrite records skipped (note: ${noPreSha.tagNote})`,
    )
    assert.match(
      noPreSha.tagNote,
      /pre-injection[ ]HEAD/i,
      `${dir}: the skip must name the unreadable pre-injection HEAD (note: ${noPreSha.tagNote})`,
    )
    assert.equal(noPreSha.pushed, 'yes', `${dir}: an unrollbackable rewrite must not cost the push`)

    // --- Executable: the shape the change exists for, end to end. ---
    // Origin holds `work`; the injector fast-forwards over it (the real one does exactly this for a
    // commit whose amend is rejected, keeping its SHA) and rewrites only what follows. The guard
    // therefore HOLDS, so this run's own commits reach origin tagged — and the published commit
    // stays untagged, which the report must say rather than inheriting the injector's exit code.
    const kept = runPushBlock(block, { commitsAhead: 2, injectorKeeps: 'work' })
    assert.equal(kept.pushed, 'yes', `${dir}: the fast-forward-over-published shape must push`)
    assert.ok(
      kept.remoteSubjects.includes('ahead-0 [#7]') && kept.remoteSubjects.includes('ahead-1 [#7]'),
      `${dir}: this run's own commits must reach origin carrying the tag (remote had: ${kept.remoteSubjects.join(', ')})`,
    )
    assert.ok(
      kept.remoteSubjects.includes('work'),
      `${dir}: the already-published commit must reach origin unrewritten (remote had: ${kept.remoteSubjects.join(', ')})`,
    )
    // The injector exited 0 here — "all" — yet the branch it left still carries an untagged commit.
    // Only a re-derivation from the branch can tell those apart, which is the whole point.
    assert.equal(
      kept.tagged,
      'partial',
      `${dir}: TAGGED must be re-derived from the pushed branch, never remembered from the injector's exit status`,
    )

    // --- Executable: a rewrite that never reached the branch may not be reported as tagged. ---
    // The injector exits 0 having tagged a DETACHED HEAD; the branch — what the loop pushes — is
    // untouched. Reading `HEAD` would answer `all` about commits no reader can see.
    const detached = runPushBlock(block, { deleteRemoteBranch: true, injectorDetaches: true })
    assert.equal(detached.pushed, 'yes', `${dir}: a detached rewrite must not cost the push`)
    assert.ok(
      detached.remoteSubjects.length > 0 && !detached.remoteSubjects.some((s) => s.includes('[#')),
      `${dir}: the branch the loop pushed is the untagged one here (remote had: ${detached.remoteSubjects.join(', ')})`,
    )
    assert.notEqual(
      detached.tagged,
      'all',
      `${dir}: TAGGED must be read from the branch the loop pushes, never from a detached HEAD`,
    )

    // --- Executable: under `set -e`, no capture on this route may abort before the push. ---
    // A bare `VAR=$(cmd)` takes the command substitution's status, so an errexit orchestrator would
    // lose the whole publication to a `gh` that is offline or a `git merge-base` whose base ref
    // moved — the exact "tagging gates the push" failure the route forbids, and one every
    // non-errexit run above is blind to. Each shape below is a capture whose OWN guard exists to
    // handle it, and which under errexit never reached that guard.
    for (const [label, opts, expected] of [
      // The PR lookup: `PR_NUMBER="${PR_NUMBER:-$(gh …)}"` aborted here.
      ['the PR lookup fails', { deleteRemoteBranch: true, ghFails: true }, 'skipped'],
      // The post-push re-derivation: `TAG_RANGE_BASE=$(git merge-base …)` aborted before the
      // `[ -z "$TAG_RANGE_BASE" ]` arm written to catch exactly this.
      [
        'the range base will not resolve',
        { deleteRemoteBranch: true, mergeBaseFails: true },
        'partial',
      ],
      // The healthy path, so a block that merely aborts EARLY everywhere cannot pass the two above.
      ['everything succeeds', { deleteRemoteBranch: true }, 'all'],
    ]) {
      const strict = runPushBlock(block, { ...opts, errexit: true })
      assert.equal(
        strict.aborted,
        false,
        `${dir}: under set -e the block must run to completion when ${label} (got TAGGED=${strict.tagged}, PUSHED=${strict.pushed}, note: ${strict.tagNote})`,
      )
      assert.equal(
        strict.pushed,
        'yes',
        `${dir}: under set -e the push must still succeed when ${label}`,
      )
      assert.equal(
        strict.tagged,
        expected,
        `${dir}: under set -e the run must record TAGGED=${expected} when ${label}`,
      )
    }

    // --- Structure: EVERY command-substitution capture carries its own `|| VAR=` tail. ---
    // The block states that as a universal rule, and a universal that the same block violates —
    // or that its gate only half-covers — is worse than no rule: the next editor reads it and
    // stops checking. So this enforces the rule as stated, for any variable name and in any
    // position; the paragraph above the matcher records exactly what "capture" means here and the
    // one context it exempts. Pinning captures one at a
    // time with an env-gated fixture flag does not scale and left several with no flag at all, so
    // assert over the shipped TEXT instead — one gate that covers every capture, including the ones
    // added after this was written, at zero fixture cost. Join continuation lines first: a capture
    // may carry its tail on the next line, and the `|| VAR=` would otherwise read as absent.
    const statements = []
    for (const line of runnable.split('\n')) {
      const prev = statements[statements.length - 1]
      if (prev !== undefined && /(\|\||&&|\||\\)\s*$/.test(prev)) {
        statements[statements.length - 1] = `${prev.replace(/\\\s*$/, '')} ${line.trim()}`
      } else {
        statements.push(line)
      }
    }
    const bareCaptures = bareCapturesIn(statements)
    assert.deepEqual(
      bareCaptures,
      [],
      `${dir}: every capture on this route must carry its own \`|| VAR=\` tail — a bare VAR=$(cmd) takes the substitution's status, so under set -e it aborts the block before the push (bare: ${bareCaptures.map((s) => s.trim()).join(' // ')})`,
    )

    // --- Structure: the post-loop re-derivation is the SOLE author of a non-skipped TAGGED. ---
    // Assigning `all`/`partial` from the injector's exit status as well gave the value two authors,
    // the second unconditionally overwriting the first — so the injector's own diagnostic was dead
    // state no reader could ever observe. What crosses the loop instead is the `TAG_INJECTED` gate
    // and a separate `TAG_INJECT_NOTE`, which the re-derivation appends to rather than clobbers.
    const preLoop = runnable.slice(0, pushAt)
    assert.doesNotMatch(
      preLoop,
      /TAGGED=(all|partial)\b/,
      `${dir}: only the post-loop re-derivation may write TAGGED=all/partial — a value written before the reconcile is exactly what the re-derivation exists to replace`,
    )

    // --- Executable: the injector's diagnostic survives the re-derivation. ---
    // The injector failed AND the branch is observably untagged. The report owes both: WHAT the
    // branch carries (only the re-derivation can see that) and WHY the injection stopped (only the
    // injector can). Clobbering either leaves the next reader to re-derive it.
    const diagnosed = runPushBlock(block, { deleteRemoteBranch: true, injectorFails: true })
    assert.equal(
      diagnosed.tagged,
      'partial',
      `${dir}: an injector failure that leaves untagged commits must re-derive to partial`,
    )
    assert.match(
      diagnosed.tagNote,
      /commits\s+on\s+this\s+branch\s+still\s+carry\s+no \[#7\]/,
      `${dir}: the note must carry the re-derivation's own observation (note: ${diagnosed.tagNote})`,
    )
    assert.match(
      diagnosed.tagInjectNote,
      /injector[ ]exited[ ]non-zero/,
      `${dir}: the injector's diagnostic must survive the re-derivation, not be overwritten by it (inject note: ${diagnosed.tagInjectNote})`,
    )
    // …and it must survive as its OWN field. Joined onto `TAG_NOTE`, neither clause is attributable
    // any more — the reader cannot tell the observation from the cause — and the injector's text is
    // free form, so no separator a join might pick is reserved against it.
    assert.doesNotMatch(
      diagnosed.tagNote,
      /injector\s+exited\s+non-zero/,
      `${dir}: the injector diagnostic is a separate field, never appended onto TAG_NOTE (note: ${diagnosed.tagNote})`,
    )
    // …and it carries the CAUSE only. A non-zero injector exit does not imply an untagged commit,
    // and `TAGGED` is re-derived independently — `kept` above exits 0 and still leaves one — so a
    // second clause guessing at the branch's state can be printed beside a `TAGGED=all` that
    // contradicts it. That is the ambiguity the two-field split removed, re-entering as a value.
    assert.doesNotMatch(
      diagnosed.tagInjectNote,
      /still\s+carries|untagged/i,
      `${dir}: the injector diagnostic states its cause and asserts nothing about what the branch carries (inject note: ${diagnosed.tagInjectNote})`,
    )

    // Same fail-closed discipline PUSHED gets: every arm assigns the tagging outcome, including
    // the confirmed arm that never injects. An unset value matches no arm of the report contract.
    for (const [label, opts] of [
      ['level with the remote', {}],
      ['ahead of the remote', { commitsAhead: 2 }],
      ['unreachable remote', { unreachableRemote: true }],
    ]) {
      assert.notEqual(
        runPushBlock(block, opts).tagged,
        '<UNSET>',
        `${dir}: TAGGED must be assigned on every route (${label}) — the report branches on it`,
      )
    }

    // --- Prose: the outcome contract, its honesty bound, and the non-goal. ---
    assert.match(
      reviewStack,
      /Report\s+the\s+tagging\s+outcome\s+too/i,
      `${dir}: the section must require the BLOCKED report to state the tagging outcome`,
    )
    assert.match(
      reviewStack,
      /Read\s+`TAGGED`\s+\*\*after\*\*\s+`PUSHED`\s+is\s+assigned/i,
      `${dir}: the tagging outcome must be read after PUSHED — a tag on a commit that never left the worktree is not an outcome`,
    )
    for (const value of ['all', 'partial', 'skipped']) {
      assert.match(
        reviewStack,
        new RegExp(`\`TAGGED=${value}\``),
        `${dir}: the report contract must give TAGGED=${value} its own statement`,
      )
    }
    // The honesty bound. The defect that motivated this change was a run reporting a red CI check
    // it never observed; the replacement must state the real cost and stay project-agnostic.
    // Slice the paragraph and assert INSIDE it, rather than over a character-distance window: a
    // prettier reflow moves the two clauses apart without changing a word, and a gate that reds on
    // that teaches the next editor to fight the formatter instead of reading the rule.
    const honestyAt = reviewStack.indexOf('Say what an untagged commit actually costs')
    const honestyEnd = reviewStack.indexOf('**Not a goal: retro-tagging', honestyAt)
    assert.ok(
      honestyAt >= 0 && honestyEnd > honestyAt,
      `${dir}: the section must carry the untagged-commit honesty bound as its own paragraph`,
    )
    const honesty = reviewStack.slice(honestyAt, honestyEnd)
    assert.match(
      honesty,
      /no\s+commit-message\s+check\s+in\s+CI/i,
      `${dir}: the honesty bound must condition on whether the project runs a commit-message check at all`,
    )
    assert.match(
      honesty,
      /not\s+a\s+red\s+check/i,
      `${dir}: without such a check an untagged commit is a traceability gap, not a red check`,
    )
    assert.doesNotMatch(
      reviewStack,
      /commitlint/i,
      `${dir}: these skills ship to every project — name the class of check, never one project's tool`,
    )
    // The no-force rule's justification used to rest on "nothing here rewrites history", which the
    // injection makes false. Correct the reasoning rather than dropping the rule: the injection is
    // bounded to unpublished commits, so a rejected push still means the REMOTE moved.
    assert.doesNotMatch(
      reviewStack,
      /None\s+of\s+these\s+routes\s+rewrote\s+history/i,
      `${dir}: the no-force justification must not claim this route rewrites nothing — the tag injection does`,
    )
    // …and the replacement must be bounded to what the shipped guard actually enforces. "Rewrites
    // only commits origin has never seen" is itself false on a DIVERGED remote, where the injector
    // rewrites commits origin also holds — safely, because nothing on this route pushes over them.
    // A justification that overclaims is the same defect one level up from the one it replaced.
    // The bound must carry its PREMISE in the same sentence: an unconditional "never rewrites a
    // commit origin's tip is built on" is false on a force-pushed remote, where the advertised tip
    // is not contained here and the guard is inert by design.
    assert.match(
      reviewStack,
      /where\s+origin\S*\s+advertised\s+tip\s+is\s+contained[\s\S]{0,120}?never\s+rewrites\s+a\s+commit\s+that\s+tip\s+is\s+built\s+on/i,
      `${dir}: the no-force justification must bound the rewrite to what the containment guard enforces, premise included`,
    )
    assert.match(
      reviewStack,
      /diverged\*\*[\s\S]{0,400}?stays\s+\*\*local\*\*/i,
      `${dir}: the justification must name the diverged case, where origin does hold commits the injection rewrites`,
    )
    assert.match(
      reviewStack,
      /§PARTIAL-route\s+publication\s+borrows\s+this\s+same\s+push\s+procedure/i,
      `${dir}: the routes-that-share-this-block walk must include PARTIAL, whose T3 conjunct reads the tagging outcome`,
    )
    assert.match(
      reviewStack,
      /skips\s+commits\s+by\s+\*\*patch\s+id\*\*/i,
      `${dir}: the section must say WHY the outcome is re-derived — rebase drops by patch id, which ignores the message`,
    )
    // Three of the four `partial` arms observed nothing — they record `tag state unverifiable:`.
    // A contract that glosses `partial` as "some commit is untagged" makes the reader assert a
    // defect the block never saw, which is the same class of invention as an unobserved red build.
    assert.match(
      reviewStack,
      /\*\*or\*\*\s+the\s+state\s+could\s+not\s+be\s+verified/i,
      `${dir}: the partial contract must separate an observed untagged commit from an unverifiable state`,
    )
    // …and it must account for the injector diagnostic as a field of its own, including what that
    // field does NOT license: it says why the injection stopped, never what the branch carries, so
    // a reader must not upgrade it into an assertion about a specific commit. Assert over the PROSE
    // only — with the fenced blocks stripped. The shipped shell assigns these strings verbatim, so
    // a regex over the whole file matches the code whether the contract is written or deleted, and
    // a contract gate that cannot fail for the reason it names gates nothing.
    const prose = reviewStack.replace(/```[\s\S]*?```/g, '')
    assert.match(
      prose,
      /`\$TAG_INJECT_NOTE`\s+is\s+a\s+\*\*second,\s+separate\s+field\*\*/i,
      `${dir}: the report contract must give the injector diagnostic its own field, not a clause appended to TAG_NOTE`,
    )
    assert.match(
      prose,
      /never\s+merge\s+the\s+two\s+into\s+one\s+string/i,
      `${dir}: the contract must forbid joining the two notes — merged, neither clause is attributable and the reader cannot tell the observation from the cause`,
    )
    assert.match(
      prose,
      /state\s+it\s+as\s+the\s+\*\*cause\*\*\s+alongside\s+the\s+observation,\s+never\s+in\s+place\s+of\s+one/i,
      `${dir}: the contract must bound what the injector diagnostic licenses — a cause, never an observation about a commit`,
    )
    // …and what an EMPTY one means. The field was promoted into the report contract without the
    // ordinary path ever assigning it — the confirmed arm does not even initialise it — so a named
    // field that is blank on every healthy run reads as a diagnostic the reporter dropped. The
    // contract closes that, not a new assignment: an absent cause is absent, not an empty one.
    assert.match(
      prose,
      /unset\s+or\s+empty\s+on\s+every\s+ordinary\s+outcome/i,
      `${dir}: the contract must say the injector diagnostic is normally absent, so an unfilled field is not read as a dropped diagnostic`,
    )
    // BOS-860 extension round 1. The `TAGGED=all` bullet closed with a categorical "Nothing further
    // is owed", while the rule that owes `$TAG_INJECT_NOTE` sits three paragraphs later — so a
    // reporter reading the bullet list top-down on the `all` path drops the injector diagnostic
    // entirely. That combination is real, not hypothetical: a failed rollback or a benign non-zero
    // exit can end with every surviving commit tagged, because the reconcile drops the rewritten
    // copies as patch-identical. Assert INSIDE the bullet — the whole defect was location, so a
    // file-wide match would pass on the far-away paragraph that was already there.
    const allBulletAt = prose.indexOf('- `TAGGED=all`')
    const partialBulletAt = prose.indexOf('- `TAGGED=partial`', allBulletAt)
    assert.ok(
      allBulletAt >= 0 && partialBulletAt > allBulletAt,
      `${dir}: the report contract must state TAGGED=all before TAGGED=partial`,
    )
    assert.match(
      prose.slice(allBulletAt, partialBulletAt),
      /Nothing\s+further\s+is\s+owed\s+beyond\s+`\$TAG_INJECT_NOTE`\s+where\s+it\s+is\s+non-empty/i,
      `${dir}: the TAGGED=all bullet may not close categorically — a non-empty injector diagnostic is still owed on that arm`,
    )
    // …and the compounding half: the re-derivation CLEARS `TAG_NOTE` on that arm, so "report it
    // beside $TAG_NOTE" names no companion there. The contract must say where the line goes.
    assert.match(
      prose,
      /re-derivation\s+clears\s+`TAG_NOTE`\s+there[\s\S]{0,200}?report\s+`\$TAG_INJECT_NOTE`\s+under\s+the\s+`TAGGED=all`\s+statement\s+itself/i,
      `${dir}: the contract must say where the injector diagnostic goes on the all arm, where TAG_NOTE is empty`,
    )
    // The vacuous `all`: an emptied range satisfies the predicate without any commit carrying a
    // tag. The bullet must send the reporter to `$TAG_NOTE` for it rather than leave the reader to
    // guess which of the two `all`s they are holding — the block now records the difference there.
    assert.match(
      prose.slice(allBulletAt, partialBulletAt),
      /vacuously\*{0,2},?\s+and\s+the\s+block\s+records[\s\S]{0,120}?`\$TAG_NOTE`[\s\S]{0,200}?never\s+"all\s+commits\s+are\s+tagged"/i,
      `${dir}: the TAGGED=all bullet must point at $TAG_NOTE for the emptied-range case, and forbid reporting it as an observed tag`,
    )
    assert.match(
      reviewStack,
      /Not\s+a\s+goal:\s+retro-tagging/i,
      `${dir}: the section must scope out retro-tagging commits origin already holds`,
    )
    assert.match(
      reviewStack,
      /Every\s+reader\s+of\s+this\s+block\s+gets\s+the\s+injection/i,
      `${dir}: the section must walk the routes that share this block, and what survives the retry loop`,
    )
    // …and that walk may not overstate what the re-derivation buys. Re-reading the branch after the
    // loop is what makes `all` an OBSERVATION rather than the injector's pre-loop word — but the
    // emptied-range arm reaches `all` with nothing left carrying anything, so the token alone is not
    // the claim that the tag survived. The paragraph must send the reader to `$TAG_NOTE` to tell the
    // two apart, exactly as the report bullet above already does; asserting the tag from the token
    // alone is the same invented success the rest of this section exists to forbid.
    // Windows sized with real headroom, not to the byte: pinned at the distance the prose happened
    // to have on the day it was written, one added clause reds this with a message alleging a
    // semantic regression that has not happened, and the next editor learns to widen gates rather
    // than read them.
    assert.match(
      reviewStack,
      /re-derivation\s+after\s+the\s+loop[\s\S]{0,900}?vacuously[\s\S]{0,700}?`\$TAG_NOTE`\s+empty/i,
      `${dir}: the re-derivation paragraph must pair TAGGED=all with $TAG_NOTE — an emptied range reaches all without any commit carrying the tag`,
    )
    // The banned claim, not one banned sentence. `pushed` and a `that` are the paraphrases the
    // original wording is one edit away from, so a pin that forbids only the exact prior string
    // stops at the first spelling — the very failure the sibling commit's own preamble condemns.
    assert.doesNotMatch(
      reviewStack,
      /`all`\s+means\s+(?:that\s+)?the\s+(?:pushed\s+)?branch\s+carries\s+the\s+tag/i,
      `${dir}: the re-derivation paragraph may not claim TAGGED=all proves the branch carries the tag — the emptied-range arm falsifies it`,
    )
  }
})

test('BOS-860 ext1: the rescue ref stays unique when HEAD will not resolve (both mirrors)', () => {
  // The rescue ref is the last mechanism guaranteeing these commits leave the worktree, and its
  // SUFFIX is the whole of what makes it unique — a name origin already advertises is rejected as
  // non-fast-forward, and an empty suffix builds `refs/heads/<branch>-blocked-`, which git refuses
  // outright. The block therefore captures the suffix on its own and falls back to `$$`. Nothing
  // executable covered that fallback: deleting the fallback line changed no result anywhere in this
  // file, because no fixture ever made the `rev-parse` behind it fail.
  for (const dir of BUILD_MIRRORS) {
    const block = pushBlockOf(reviewStackFor(dir))
    // An unreachable remote is the shape that exhausts the retry loop, so it is the only one that
    // reaches the rescue path at all. The rescue push fails too — the remote is gone — but the ref
    // the block ASKED for is what is under test, and the shim logs that argv either way.
    const healthy = runPushBlock(block, { unreachableRemote: true })
    assert.equal(
      healthy.pushed,
      'no',
      `${dir}: an unreachable remote must exhaust the loop and reach the rescue path`,
    )
    assert.match(
      healthy.rescueRef ?? '<none>',
      /^feat-blocked-[0-9a-f]{4,}$/,
      `${dir}: with HEAD readable the rescue ref carries the short SHA (asked for: ${healthy.rescueRef})`,
    )

    // …and with that read failing, the ref must still be a NAME: non-empty suffix, and unique, or
    // the fallback has bought nothing the empty string did not already give.
    const noShortSha = runPushBlock(block, { unreachableRemote: true, shortHeadFails: true })
    assert.match(
      noShortSha.rescueRef ?? '<none>',
      /^feat-blocked-\S+$/,
      `${dir}: an unreadable HEAD must not leave the rescue ref with an empty suffix — refs/heads/<branch>-blocked- is not a ref git will create (asked for: ${noShortSha.rescueRef})`,
    )
    const secondRun = runPushBlock(block, { unreachableRemote: true, shortHeadFails: true })
    assert.notEqual(
      noShortSha.rescueRef,
      secondRun.rescueRef,
      `${dir}: the fallback suffix must be UNIQUE per run — a constant one is rejected as non-fast-forward the second time it is needed (both runs asked for: ${noShortSha.rescueRef})`,
    )
  }
})

test('BOS-860 ext2: an emptied range is reported as vacuous, not as an observed tag (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const block = pushBlockOf(reviewStackFor(dir))
    // The reconcile drops every commit this run made, so the re-derivation scans an EMPTY range.
    // `grep -qv` finds no untagged subject there, which is how an emptied branch reaches the same
    // `all` the fully-tagged one does — the two must not be byte-identical afterwards.
    const dropped = runPushBlock(block, { reconcileDropsRange: true })
    assert.ok(
      dropped.injectArgv.length > 0,
      `${dir}: the fixture must reach the injector, or the re-derivation never runs at all`,
    )
    assert.equal(
      dropped.pushed,
      'yes',
      `${dir}: the fixture must reconcile and push, or the emptied range is never re-derived (tagged=${dropped.tagged}, note=${dropped.tagNote})`,
    )
    assert.deepEqual(
      dropped.remoteSubjects.filter((s) => s.includes('[#7]')),
      [],
      `${dir}: the fixture is only meaningful while the branch origin ends up holding carries no tag (${dropped.remoteSubjects.join(' | ')})`,
    )
    assert.equal(
      dropped.tagged,
      'all',
      `${dir}: an empty range satisfies the all predicate vacuously — that is the value under test (note=${dropped.tagNote})`,
    )
    assert.match(
      dropped.tagNote,
      /no[ ]commits[ ]in[ ]the[ ]range/i,
      `${dir}: an emptied range must SAY so in TAG_NOTE — otherwise the report asserts a tag on commits that are no longer there (got: ${dropped.tagNote})`,
    )
    // The control the note is meant to be distinguishable FROM: commits really rewritten, really
    // tagged, really pushed. `<UNSET>` is the trap's rendering of an empty `TAG_NOTE`.
    const genuine = runPushBlock(block, { deleteRemoteBranch: true })
    assert.equal(
      genuine.tagged,
      'all',
      `${dir}: the control must reach all by observation, not vacuously (note=${genuine.tagNote})`,
    )
    assert.ok(
      genuine.remoteSubjects.some((s) => s.includes('[#7]')),
      `${dir}: the control must actually publish a tagged commit (${genuine.remoteSubjects.join(' | ')})`,
    )
    assert.equal(
      genuine.tagNote,
      '<UNSET>',
      `${dir}: an observed all leaves TAG_NOTE empty, so the emptied-range note cannot be read as ordinary (got: ${genuine.tagNote})`,
    )
  }
})

test('BOS-758 repair P2c: the API clamp assigns its constants before the arithmetic', () => {
  // The budget block near the top of review-stack.md is a pricing FORMULA (`NAME = 5`), not a
  // script, so neither name is set in any shell that reaches the clamp — and an unset name is ZERO
  // inside $(( )). Before this fix the clamp computed API_CHECK_SECONDS=0 on every run, and the
  // rule below it then routed every API-surface diff to capped/BLOCKED without ever running the
  // check its tier had reserved. Assert on the RUN value, not the prose: a byte or grep gate cannot
  // tell a clamp that yields 300 from one that yields 0.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    // BOS-737: second of the three copies — see the note at the first, in the P1 degraded-tier
    // test above, for why `regionUntilNext()` replaces the hand-rolled guard byte for byte.
    const apiGate = regionUntilNext(
      reviewStack,
      '### API-surface check (conditional, required',
      '## Step 6b:',
      `${dir}/references/review-stack.md`,
    )
    const clamp = bashBlocksOf(apiGate).find((block) => /^API_CHECK_SECONDS=/m.test(block))
    assert.ok(clamp, `${dir}: the API gate must ship an executable deadline clamp`)

    // (a) Both names assigned, and assigned BEFORE the arithmetic that reads them.
    const allowanceAt = clamp.search(/^DEGRADED_API_CHECK_MINUTES=\d+/m)
    const reserveAt = clamp.search(/^POST_REVIEW_RESERVE_MINUTES=\d+/m)
    const arithmeticAt = clamp.search(/^API_CHECK_SECONDS=/m)
    assert.ok(
      allowanceAt >= 0 && allowanceAt < arithmeticAt,
      `${dir}: DEGRADED_API_CHECK_MINUTES must be assigned in the clamp, above the arithmetic`,
    )
    assert.ok(
      reserveAt >= 0 && reserveAt < arithmeticAt,
      `${dir}: POST_REVIEW_RESERVE_MINUTES must be assigned in the clamp, above the arithmetic`,
    )

    // (b) The assigned values must track the priced formula, not drift from it.
    const priced = Number(/DEGRADED_API_CHECK_MINUTES\s*=\s*(\d+)/.exec(reviewStack)?.[1])
    const assigned = Number(/^DEGRADED_API_CHECK_MINUTES=(\d+)/m.exec(clamp)?.[1])
    assert.equal(assigned, priced, `${dir}: the clamp's allowance must equal the priced allowance`)
    const reserveSum = Number(
      /POST_REVIEW_RESERVE_MINUTES =[\s\S]{0,400}?=\s*(\d+) minutes/.exec(reviewStack)?.[1],
    )
    const reserveSet = Number(/^POST_REVIEW_RESERVE_MINUTES=(\d+)/m.exec(clamp)?.[1])
    assert.equal(
      reserveSet,
      reserveSum,
      `${dir}: the clamp's reserve must equal the priced reserve`,
    )

    // (c) No deadline in the environment → the full priced allowance, in SECONDS. This is the
    // assertion the original defect fails: it yielded 0 here.
    const noDeadline = runBlock(clamp, {}, '$API_CHECK_SECONDS').trim()
    assert.equal(
      noDeadline,
      String(priced * 60),
      `${dir}: with no deadline the clamp must yield the priced allowance in seconds, not 0`,
    )

    // (d) A roomy deadline leaves the allowance intact.
    const roomy = String(Math.floor(Date.now() / 1000) + (reserveSum + priced + 5) * 60)
    assert.equal(
      runBlock(clamp, { PREFLIGHT_DEADLINE: roomy }, '$API_CHECK_SECONDS').trim(),
      String(priced * 60),
      `${dir}: a deadline with room to spare must not shrink the priced allowance`,
    )

    // (e) A deadline inside the reserve must clamp NON-POSITIVE, so the documented capped/BLOCKED
    // route fires rather than the check spending Steps 7-12's reserve.
    const tight = String(Math.floor(Date.now() / 1000) + Math.floor(reserveSum / 2) * 60)
    const clamped = Number(
      runBlock(clamp, { PREFLIGHT_DEADLINE: tight }, '$API_CHECK_SECONDS').trim(),
    )
    assert.ok(
      clamped <= 0,
      `${dir}: a deadline inside the post-review reserve must clamp non-positive, got ${clamped}`,
    )
  }
})

test('BOS-758 repair P2d: the API clamp binds BOTH tiers, not the degraded one alone', () => {
  // FULL_TIER_MINUTES prices no allowance for the conditional API pass, and the clamp used to be
  // scoped to the degraded tier by its own heading — so on a full-tier run whose priced legs had
  // consumed their caps, nothing held the pass out of POST_REVIEW_RESERVE_MINUTES, which Steps
  // 7-12 still need. The pass is BOUNDED instead of budgeted (as Step 6c is), and that bound only
  // works if it is stated to run in both tiers.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    // BOS-737: third of the three copies — see the note at the first, in the P1 degraded-tier
    // test above. This site is the one that most wanted it: only positive `assert.match` runs
    // over `apiGate` here, so a -1 already failed closed, but it failed naming a missing phrase
    // rather than the heading that actually moved.
    const apiGate = regionUntilNext(
      reviewStack,
      '### API-surface check (conditional, required',
      '## Step 6b:',
      `${dir}/references/review-stack.md`,
    )

    assert.match(
      apiGate,
      /run\s+it\s+in\s+BOTH\s+tiers/,
      `${dir}: the clamp must bind both tiers, or the full tier runs the pass unbounded`,
    )
    assert.match(
      apiGate,
      /clean\s+verdict\s+in\s+\*\*either\*\*\s+tier/i,
      `${dir}: an unrun required API gate must fail closed in both tiers, not just the degraded one`,
    )
    assert.doesNotMatch(
      apiGate,
      /clean\s+degraded-tier\s+verdict/i,
      `${dir}: the fail-closed clause may no longer be scoped to the degraded tier alone`,
    )
    // The formula must say WHY the full tier carries no line item, or a later round "fixes" the
    // omission by inflating the admission threshold for every diff, surface-touching or not.
    assert.match(
      reviewStack,
      /API-surface\s+check\s+is\s+deliberately\s+NOT\s+priced\s+here[\s\S]{0,400}BOUNDED\s+instead/i,
      `${dir}: the budget formula must record that the API pass is bounded rather than priced`,
    )
  }
})

test('BOS-758 repair P1: Step 7 confirms the pushed tip is the tip that was reviewed', () => {
  // The push procedure reaches PUSHED=yes by two routes that move the tip: its zero-ahead arm
  // accepts a remote copy that merely CONTAINS HEAD, and its retry loop rebases onto FETCH_HEAD.
  // Step 7 then created/reused the PR immediately, so a tree that was never reviewed could ship
  // under a body reporting full coverage.
  for (const dir of BUILD_MIRRORS) {
    const skill = readSkill(`${dir}/SKILL.md`)
    // BOS-737: no `length > 0` pin — `region()` already throws on an absent marker or an empty
    // region.
    const step7 = region(skill, '## Step 7:', '## Steps 8-12:')

    // (a) The body states the rule where the decision is taken, and points at the mechanics.
    assert.match(
      step7,
      /`PUSHED=yes`\s+is\s+not\s+proof/i,
      `${dir}/SKILL.md: Step 7 must deny that PUSHED=yes proves the reviewed tree is what ships`,
    )
    assert.match(
      step7,
      /Reviewed-tip\s+confirmation/,
      `${dir}/SKILL.md: Step 7 must point at the reference section carrying the comparison`,
    )
    // (b) BOTH routes, so a run cannot invent a third (continue anyway).
    assert.match(
      step7,
      /re-run\s+the\s+Step\s+5\s+gates\s+and\s+the\s+Step\s+6\s+review[\s\S]{0,120}Stop\s+cleanly\*\*\s+`BLOCKED`/i,
      `${dir}/SKILL.md: Step 7 must name both routes for a moved tip — re-review, or BLOCKED`,
    )

    // (c) The reference carries the capture/compare, and it fails CLOSED on an unreadable tip.
    const reviewStack = reviewStackFor(dir)
    const at = reviewStack.indexOf('### Reviewed-tip confirmation')
    assert.ok(at >= 0, `${dir}: review-stack.md must carry the reviewed-tip confirmation`)
    const rest = reviewStack.slice(at + 1)
    const end = rest.search(/\n#{2,3} /)
    const section = end === -1 ? rest : rest.slice(0, end)

    assert.match(
      section,
      /REVIEWED_HEAD=\$\(git[ ]rev-parse[ ]HEAD\)/,
      `${dir}: the reviewed tip must be captured BEFORE the push procedure runs`,
    )
    assert.match(
      section,
      /PR_TIP=\$\(git[ ]rev-parse[ ]FETCH_HEAD[\s\S]{0,60}echo[ ]unknown\)/,
      `${dir}: the shipped tip must be read back from the remote, not from local HEAD`,
    )
    assert.match(
      section,
      /Compare\s+the\s+two\s+as\s+\*\*strings\*\*/i,
      `${dir}: the comparison must be a string compare — a numeric one passes on two SHAs`,
    )
    assert.match(
      section,
      /fails\s+\*\*closed\*\*[\s\S]{0,200}`unknown`/i,
      `${dir}: an unreadable tip must fail closed, not read as a match`,
    )
  }
})

test('BOS-758 repair P2e: the degraded reviewer is clamped against the live deadline', () => {
  // The tier is admitted on a reading taken at tier selection, but the reviewer was given a FIXED
  // ten minutes. Admitted at the 40-minute floor, five minutes of setup between admission and
  // dispatch is enough for that fixed leg to run into the 25-minute post-review reserve, and the
  // later API clamp cannot recover reserve time this leg already spent. The clamp must therefore
  // preserve BOTH the API allowance that follows it and the reserve.
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const at = reviewStack.indexOf('### Degraded tier (minimal)')
    assert.ok(at >= 0, `${dir}: review-stack.md must carry the degraded tier section`)
    const rest = reviewStack.slice(at + 1)
    const end = rest.search(/\n#{2,3} /)
    const section = end === -1 ? rest : rest.slice(0, end)

    const clamp = bashBlocksOf(section).find((b) => /^\s*DEGRADED_REVIEWER_SECONDS=/m.test(b))
    assert.ok(clamp, `${dir}: the degraded reviewer must ship an executable deadline clamp`)

    // Constants assigned before the arithmetic — the formula block is prose, not a script.
    for (const name of [
      'DEGRADED_REVIEWER_MINUTES',
      'DEGRADED_API_CHECK_MINUTES',
      'POST_REVIEW_RESERVE_MINUTES',
    ]) {
      const assignedAt = clamp.search(new RegExp(`^\\s*${name}=\\d+`, 'm'))
      const usedAt = clamp.search(/^\s*DEGRADED_REVIEWER_SECONDS=/m)
      assert.ok(
        assignedAt >= 0 && assignedAt < usedAt,
        `${dir}: ${name} must be assigned in the clamp, above the arithmetic that reads it`,
      )
    }

    const priced = Number(/DEGRADED_REVIEWER_MINUTES\s*=\s*(\d+)/.exec(reviewStack)?.[1])
    const api = Number(/DEGRADED_API_CHECK_MINUTES\s*=\s*(\d+)/.exec(reviewStack)?.[1])
    const reserve = Number(
      /POST_REVIEW_RESERVE_MINUTES =[\s\S]{0,400}?=\s*(\d+) minutes/.exec(reviewStack)?.[1],
    )

    // (a) No deadline set → the full priced allowance in seconds.
    assert.equal(
      runBlock(clamp, {}, '$DEGRADED_REVIEWER_SECONDS').trim(),
      String(priced * 60),
      `${dir}: with no deadline the reviewer keeps its priced allowance`,
    )

    // (b) Roomy deadline → allowance intact.
    const roomy = String(Math.floor(Date.now() / 1000) + (reserve + api + priced + 5) * 60)
    assert.equal(
      runBlock(clamp, { PREFLIGHT_DEADLINE: roomy }, '$DEGRADED_REVIEWER_SECONDS').trim(),
      String(priced * 60),
      `${dir}: a deadline with room to spare must not shrink the priced allowance`,
    )

    // (c) THE DEFECT: admitted at the floor, then setup burns time. The reviewer must be clamped
    // strictly below its fixed allowance rather than spending the reserve or the API allowance.
    const squeezed = String(Math.floor(Date.now() / 1000) + (reserve + api + priced - 6) * 60)
    const got = Number(
      runBlock(clamp, { PREFLIGHT_DEADLINE: squeezed }, '$DEGRADED_REVIEWER_SECONDS').trim(),
    )
    assert.ok(
      got < priced * 60 && got > 0,
      `${dir}: a squeezed deadline must clamp the reviewer below its allowance, got ${got}`,
    )

    // (d) The clamp must reserve the API allowance too, not just the post-review reserve. With only
    // the reserve plus the API allowance left, there is no reviewer time at all.
    const noRoom = String(Math.floor(Date.now() / 1000) + (reserve + api) * 60)
    assert.ok(
      Number(
        runBlock(clamp, { PREFLIGHT_DEADLINE: noRoom }, '$DEGRADED_REVIEWER_SECONDS').trim(),
      ) <= 0,
      `${dir}: the clamp must preserve the API allowance as well as the post-review reserve`,
    )

    // (e) GATE THE HAND-OFF. A clamp the dispatch never states bounds nothing.
    assert.match(
      section,
      /\[TIME_BUDGET_SECONDS\]`?\s*slot\s+with\s+it|fill[\s\S]{0,80}\[TIME_BUDGET_SECONDS\][\s\S]{0,80}with\s+it/i,
      `${dir}: the clamped reviewer budget must be handed to the dispatch template slot`,
    )
    assert.match(
      section,
      /non-positive\s+clamp[\s\S]{0,200}`bs-review\s+capped:`[\s\S]{0,60}BLOCKED/i,
      `${dir}: a non-positive reviewer clamp must fail closed through capped/BLOCKED`,
    )
  }
})

// ─────────────────────────────────────────────────────────────────────────────
// BOS-842: `PARTIAL`, the fourth terminal state.
//
// These tests live at the END of the file on purpose: they consume `readReviewStack` /
// `reviewStackFor`, both `const` arrows declared mid-file, so registering the tests below those
// declarations is the only placement with no TDZ hazard. (They also consume `region()`, which is
// a module import and so has no such hazard — BOS-737 replaced the third name here, the local
// `sliceSection` helper, with it.)
//
// They are deliberately ADJACENT to the BOS-240 test rather than folded into it. BOS-240 byte-pins
// the phrases this ticket must not disturb (`BLOCKED, never REVIEW_READY`,
// `REVIEW_READY only with no deferred required item`); keeping that test literally untouched is
// what proves the carve-out was attached, not substituted. BOS-240 also iterates `RESIDENT_BODIES`
// (canonical only); everything below iterates `BUILD_MIRRORS` so a hand-edit of the plugin mirror,
// or a skipped `make copy-skills`, trips.
const EPIC_CORE = 'services/boss/internal/skillinstall/skills/boss-epic'
const EPIC_MIRRORS = [EPIC_CORE, 'plugins/bossd-plugin-claude/skilldata/skills/boss-epic']
const buildBody = (dir) => fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')

test('BOS-842: the resident state list declares four states and names PARTIAL’s three conjuncts (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const body = buildBody(dir)
    // Slice the state list rather than whole-file matching. `partial` appears a dozen times
    // elsewhere in this body (the transport preflight's `partial` capability report, "partial
    // implementation is not complete", resume classification), so a whole-file `/PARTIAL/` would
    // stay green with the state itself deleted — the exact defect this ticket's own risk section
    // calls inertness.
    const states = region(
      body,
      'Four terminal states, nothing else:',
      'An existing PR/branch',
      `${dir}/SKILL.md`,
    )
    assert.doesNotMatch(
      body,
      /Three\s+terminal\s+states/,
      `${dir}: the body must not still declare three terminal states`,
    )
    for (const state of ['REVIEW_READY', 'BLOCKED', 'PARTIAL', 'NO_CHANGE']) {
      assert.match(
        states,
        new RegExp(`^- \`${state}\``, 'm'),
        `${dir}: the terminal-state list must carry a \`${state}\` bullet`,
      )
    }
    // The bullet itself, not the list around it: a reader who never opens a reference must learn
    // what EARNS this state, or an unattended agent picks the state that reads as progress and
    // `BLOCKED` empties out. All three conjuncts, in the one bullet.
    const partial = region(states, '- `PARTIAL`', '- `NO_CHANGE`', `${dir}/SKILL.md states`)
    assert.match(
      partial,
      /certified\s+by\s+the\s+acceptance-criteria\s+lens/,
      `${dir}: the PARTIAL bullet must name T1 — a criterion certified by the acceptance-criteria lens, not self-asserted`,
    )
    assert.match(
      partial,
      /branch\s+green/,
      `${dir}: the PARTIAL bullet must name T2 — the branch is green`,
    )
    assert.match(
      partial,
      /every\s+deferred\s+required\s+item\s+is\s+an\s+unsatisfied\s+in-scope\s+criterion/,
      `${dir}: the PARTIAL bullet must name T3 — every deferred required item is an unsatisfied in-scope criterion`,
    )
    // …and the two facts that distinguish it from REVIEW_READY at a glance.
    assert.match(
      partial,
      /stays\s+\*\*In\s+Progress\*\*/,
      `${dir}: the PARTIAL bullet must say the ticket stays In Progress`,
    )
    assert.match(
      partial,
      /never\s+`please-review`/,
      `${dir}: the PARTIAL bullet must forbid the please-review label`,
    )
  }
})

test('BOS-842: the required-deferred carve-out is SCOPED to unsatisfied criteria (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const body = buildBody(dir)
    // The whole risk of this ticket is that the carve-out is written as a general softening. Slice
    // the Hard-rules bullet and assert the SCOPING WORDING, not the presence of the token
    // `PARTIAL` — a token test passes on prose that says "any deferred required item may route
    // PARTIAL", which is the widening this assertion exists to red.
    const rule = region(
      body,
      '- **Required-deferred ⇒ BLOCKED, never REVIEW_READY**',
      '- Never merge. Terminal success',
      `${dir}/SKILL.md`,
    )
    assert.match(
      rule,
      /BLOCKED, never\s+REVIEW_READY/,
      `${dir}: the required-deferred rule must keep its BOS-240 phrasing verbatim`,
    )
    assert.match(
      rule,
      /\*\*single\*\*\s+exception\s+is\s*\n?\s*`PARTIAL`/,
      `${dir}: PARTIAL must be stated as the SINGLE exception, not one of several`,
    )
    assert.match(
      rule,
      /available\s+\*\*only\*\*\s+when\s+the\s+deferred\s+required\s+items\s+are\s*\n?\s*\*\*exclusively\*\*\s+unsatisfied\s+in-scope\s+acceptance\s+criteria/,
      `${dir}: the carve-out must be scoped to EXCLUSIVELY unsatisfied in-scope acceptance criteria`,
    )
    // The negative half: the three classes that may never route PARTIAL are named on the same
    // bullet. Deleting this sentence is how the carve-out silently becomes general.
    assert.match(
      rule,
      // Windows are generous on purpose: the assertion is that all four clauses survive IN ORDER
      // on this bullet, not that nobody may insert a qualifier between them. A tight window here
      // reds on an innocuous rewording while catching no widening the ordering does not already.
      /open\s+must-fix[\s\S]{0,240}API-version\s+bump\s+or\s+transform[\s\S]{0,160}red\s+branch[\s\S]{0,160}forces\s*\n?\s*BLOCKED\s+—\s+never\s*\n?\s*`PARTIAL`/,
      `${dir}: the rule must still force BLOCKED for a must-fix, a missing API-version transform, or a red branch`,
    )
    // T1 on the bullet that DEFINES the exception. Without it the carve-out reads as "defer every
    // criterion and still land PARTIAL" — a 0-of-N universal soft landing that is strictly worse
    // than BLOCKED, because it publishes a ready PR asserting progress that never happened.
    assert.match(
      rule,
      /≥1\s+criterion\s+is\s+lens-certified/,
      `${dir}: the carve-out must require at least one CERTIFIED-satisfied criterion (T1)`,
    )
    assert.match(
      rule,
      /`0\/<total>`\s+is\s+BLOCKED/,
      `${dir}: the carve-out must say outright that a 0-of-N run is BLOCKED, never PARTIAL`,
    )
    // The widening detector proper. This phrase is absent from the bullet today and is exactly the
    // wording a softening edit reaches for.
    assert.doesNotMatch(
      rule,
      /any\s+deferred\s+required\s+item/i,
      `${dir}: the carve-out must never be widened to "any deferred required item"`,
    )
    // BOS-240's Step 12 pointer phrase is unchanged, and PARTIAL is attached as the else-branch
    // BELOW it — not substituted for it.
    const pointers = region(body, '## Steps 8-12:', '## Cron gate', `${dir}/SKILL.md`)
    assert.match(
      pointers,
      /REVIEW_READY\s+only\s+with\s+no\s+deferred\s+required\s+item/,
      `${dir}: the Steps 8-12 pointer must still forbid REVIEW_READY with any deferred required item`,
    )
    assert.match(
      pointers,
      /else\s+`PARTIAL`\s+when\s+every\s*\n?\s*deferred\s+required\s+item\s+is\s+an\s+unsatisfied\s+in-scope\s+criterion[\s\S]{0,48}on\s+a\s+green\s+branch/,
      `${dir}: the Steps 8-12 pointer must route PARTIAL only on the scoped condition`,
    )
    // T1 belongs HERE too, not only on the state bullet and the Hard rules. This pointer is the
    // resident text an agent reads at the moment it picks the terminal state, and T3 + T2 without
    // T1 reads as "defer every criterion, stay green, ship PARTIAL" — the 0-of-N soft landing.
    assert.match(
      pointers,
      /≥1\s+lens-certified/,
      `${dir}: the Steps 8-12 pointer must carry T1's floor — at least one lens-certified criterion`,
    )
    // The Step 9 pointer in the SAME resident block. Its "assert **no required item was deferred**,
    // then ready the PR" predates PARTIAL and contradicts it: on the non-`capped` PARTIAL path the
    // assert fails, the agent skips the ready, and T2 — which neither finalize-and-stop.md nor
    // review-stack.md can read on a draft — becomes unestablishable, so the run falls to BLOCKED.
    // That is round 1's inertness defect reappearing on the OTHER route, from the resident summary.
    assert.match(
      pointers,
      /no\s+required\s+item\s+was\s+deferred\*\*[\s\S]{0,60}`PARTIAL`[\s\S]{0,60}ready/,
      `${dir}: the Step 9 pointer must carve PARTIAL out of its no-deferred-item assert and still ready the PR`,
    )
    // ...and it must point at PARTIAL's GATE, not name PARTIAL as the automatic else. A bare
    // "(else `PARTIAL`)" is the unscoped carve-out — readable as "any deferred required item lands
    // PARTIAL", which is the universal soft landing the state exists to refuse. The scope itself
    // lives in Step 12's pointer below and in Step 9 proper; this word is the pointer at it.
    assert.match(
      pointers,
      /`PARTIAL`\s+gate/,
      `${dir}: the Step 9 pointer must name PARTIAL's GATE — an unscoped "else PARTIAL" reads as a general softening`,
    )
  }
})

test('BOS-842: Step 12’s printed output enumerates all four states (body + reference, both mirrors)', () => {
  // A run prints exactly one of these. An enumeration that still lists three is how a PARTIAL run
  // prints BLOCKED — the state would exist everywhere except on the one line a human reads.
  const allFour = /`REVIEW_READY`\s*\/\s*`PARTIAL`\s*\/\s*`BLOCKED`\s*\/\s*`NO_CHANGE`/
  for (const dir of BUILD_MIRRORS) {
    const pointers = region(buildBody(dir), '## Steps 8-12:', '## Cron gate', `${dir}/SKILL.md`)
    assert.match(
      pointers,
      allFour,
      `${dir}: the resident Step 12 pointer must print one of all four terminal states`,
    )
    // BOS-737: hoisted to a local so the receiver is a plain identifier. As a call expression
    // the raw form slipped the vacuity gate (its backreference matches one identifier, not
    // `f(x)`), and the `length > 0` pin below was itself vacuous — a moved marker makes
    // `slice(-1)` a ONE-character string, which passes it. `region()` throws instead.
    const finalizeRef = finalizeAndStop(dir)
    const step12 = region(finalizeRef, '## Step 12:')
    assert.match(
      step12,
      allFour,
      `${dir}: Step 12's printed output line must enumerate all four terminal states`,
    )
  }
})

