test('BOS-842: finalize-and-stop keeps PARTIAL out of the review role, the label and proof (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const ref = finalizeAndStop(dir)
    // Section-sliced, because each of these sentences is only correct in its own step: a
    // "never .inReview" clause sitting in Step 12 would leave Step 9 free to ready-and-move the
    // ticket, and the whole point of PARTIAL is that the ticket stays visibly incomplete.
    const step9 = region(ref, '## Step 9:', '## Step 10:', `${dir}/${FINALIZE_REF}`)
    assert.match(
      step9,
      /no\s+required\s+item\s+was\s+deferred/,
      `${dir}: Step 9 must keep the BOS-240 deferral gate`,
    )
    // Anchor each conjunct on its OPERATIVE phrase, the way T3 already is. A window regex ending on
    // a bare keyword (`green`, `independently certified`) spans a negation and still matches: the
    // window swallows "the branch **need not** be green" and lands on the `green` after it, so the
    // one regression these pins exist to catch — a conjunct SOFTENED rather than deleted — is
    // exactly the one they miss, and a red-branch PARTIAL ships with the suite green.
    for (const [label, re] of [
      [
        'T1 (a certified criterion)',
        /\*\*T1\*\*\s+—\s+at\s+least\s+one\s+in-scope\s+acceptance\s+criterion\s+is\s+satisfied\s+\*\*and\s+independently\s+certified\*\*/,
      ],
      ['T2 (a green branch)', /\*\*T2\*\*\s+—\s+the\s+branch\s+is\s+\*\*green\*\*/],
      [
        'T3 (only unsatisfied criteria deferred)',
        /\*\*T3\*\*[\s\S]{0,200}\*\*only\*\*\s+an\s+unsatisfied\s+in-scope\s+acceptance\s+criterion/,
      ],
    ]) {
      assert.match(step9, re, `${dir}: the Step 9 PARTIAL gate must state ${label}`)
    }
    // Belt and braces on the same failure: no conjunct may acquire a softening qualifier anywhere
    // in the gate. `assert.match` proves the strong phrase is PRESENT; only this proves a weaker
    // one was not added beside it.
    assert.doesNotMatch(
      step9,
      /\*\*T[123]\*\*[\s\S]{0,300}\b(need\s+not|does\s+not\s+have\s+to|is\s+not\s+required\s+to|regardless\s+of)\b/,
      `${dir}: no Step 9 PARTIAL conjunct may be softened with a "need not" / "regardless of" qualifier`,
    )
    // T1's POSITIVE form, pinned here and not only in review-stack.md. Step 9 is the copy this
    // skill's own T3 defers to on the required-item list, and the copy SKILL.md's Hard-rules bullet
    // points at — so an absence-shaped T1 here is the governing wording, whatever review-stack says.
    // `independently certified` alone does not distinguish the two forms: the pre-remediation text
    // ("emitted no acceptance-criteria must-fix naming it") matched it too, and that reading
    // certifies EVERY criterion on a branch no lens ever read — which is exactly a run-generated
    // `sentinel capped 1`. Each clause below is a separate half of the fix, so pin them separately.
    for (const [label, re] of [
      [
        'certification is a positive record, never an absence',
        /certification\s+is\s+a\s+[_*]{0,2}positive[_*]{0,2}\s+record[\s\S]{0,16}never\s+an\s+absence/,
      ],
      [
        'the certification RAN over the full supplied criteria list',
        /certification\s+[_*]{0,2}ran[_*]{0,2}\s+over\s+the\s+full\s+supplied\s+criteria\s+list/,
      ],
      [
        'the verdict was authored by a reviewer',
        /verdict\s+a\s+[_*]{0,2}reviewer[_*]{0,2}\s+authored/,
      ],
      [
        'a self-generated capped verdict fails T1 outright',
        /generated\s+for\s+itself\s+fails\s+T1\s+by\s+construction/,
      ],
      ['zero satisfied criteria is BLOCKED, never PARTIAL', /is\s+BLOCKED,\s+never\s+`PARTIAL`/],
    ]) {
      assert.match(
        step9,
        re,
        `${dir}: Step 9's T1 must require ${label} — an absence test certifies an unreviewed branch`,
      )
    }
    // T2 is defined at a gate the `capped` route never reaches. Saying so here is what stops an
    // agent inheriting a green it never measured; "unmeasured is not green" is the whole rule.
    assert.match(
      step9,
      /Unmeasured\s+is\s+not\s+green/,
      `${dir}: Step 9 must say a capped-route PARTIAL takes T2's reading itself, not inherit it`,
    )
    assert.match(
      step9,
      /\*\*never\*\*\s+move\s+the\s+ticket\s+to\s+`\.inReview`/,
      `${dir}: Step 9 must forbid moving a PARTIAL ticket to the .inReview role`,
    )
    assert.match(
      step9,
      /\*\*never\*\*\s+add\s+`please-review`/,
      `${dir}: Step 9 must forbid the please-review label on a PARTIAL PR`,
    )
    assert.match(
      step9,
      /leave\s+the\s+ticket\s*\n?\s*in\s+the\s+`\.inProgress`\s+role/,
      `${dir}: Step 9 must leave a PARTIAL ticket in the .inProgress role`,
    )
    // Step 11 is REVIEW_READY-only. Proof captured off a deliberately incomplete slice is evidence
    // of a finished feature — the single most misleading artifact this pipeline can publish.
    const step11 = region(ref, '## Step 11:', '## Step 12:', `${dir}/${FINALIZE_REF}`)
    assert.match(
      step11,
      /Skip\s*\n?\s*entirely\s+for[^.]*`PARTIAL`/,
      `${dir}: Step 11's skip list must contain PARTIAL`,
    )
    // Step 12's pick, not just its printed line.
    const step12 = region(ref, '## Step 12:')
    assert.match(
      step12,
      /`PARTIAL`\s+is\s+the\s+single\s+scoped\s+exception[\s\S]{0,320}T1\/T2\/T3\s+all\s+held/,
      `${dir}: Step 12 must pick PARTIAL only when the Step 9 gate's three conjuncts held`,
    )
  }
})

test('BOS-842: review-stack owns the PARTIAL publication route and writes the body itself (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = readReviewStack(dir)
    assert.ok(
      reviewStack.indexOf('### PARTIAL-route publication') >= 0,
      `${dir}: review-stack.md must carry the PARTIAL-route publication section`,
    )
    const section = region(
      reviewStack,
      '### PARTIAL-route publication',
      '### BLOCKED-route publication',
      `${dir}/references/review-stack.md`,
    )
    // The inertness gate, mirroring the BLOCKED route's own `gh pr edit --body-file` assertion
    // above: `capped` never reaches Step 7, the sole place that writes a PR body, so a PARTIAL
    // route that does not write the body itself produces a state name with no artifact behind it
    // while every other gate here goes green.
    //
    // Assert against the section's COMMAND FENCES, not its prose. The section also *describes* the
    // mechanism ("with the same `gh pr edit --body-file` mechanism Step 7 uses"), and a match on
    // the whole section is satisfied by that sentence alone — so deleting `--body-file "$PR_BODY"`
    // from the command that actually runs would leave this gate green while the route publishes a
    // title with no body behind it. Prose is a claim; the fence is the artifact.
    const fenceList = [...section.matchAll(/```bash\n([\s\S]*?)```/g)].map((m) => m[1])
    const fences = fenceList.join('\n')
    assert.ok(
      fences.length > 0,
      `${dir}: §PARTIAL-route publication must carry runnable bash fences, not prose alone`,
    )
    assert.match(
      fences,
      /gh\s+pr\s+edit\s+"\$PR_NUMBER"(?:[^\n]|\\\n)*?--body-file\s+"\$PR_BODY"/,
      `${dir}: the PARTIAL route must write the PR body itself, in a real command — it never reaches Step 7`,
    )
    assert.match(
      section,
      /`Partial: <satisfied>\/<total> acceptance\s+criteria`/,
      `${dir}: the PARTIAL body must carry the <satisfied>/<total> count line`,
    )
    assert.match(
      section,
      /\*\*full\*\*\s+criteria\s+checklist[\s\S]{0,320}`- \[x\]`[\s\S]{0,240}`- \[ \]`/,
      `${dir}: the PARTIAL body must carry the full - [x]/- [ ] checklist, none elided`,
    )
    assert.match(
      section,
      /One\s+line\s+per\s+`- \[ \]`[\s\S]{0,200}`file:line`\s+precision/,
      `${dir}: every open criterion needs a file:line reason — a bare unticked box hands the next reader nothing`,
    )
    assert.match(
      section,
      /`## Cross-model\s+review`\s+and\s+`## Review\s+coverage`\s+sections/,
      `${dir}: the PARTIAL body must retain both mandatory review sections — an absent one reads as full coverage`,
    )
    assert.match(
      section,
      /\*\*plus\s+the\s+PR\s+URL\*\*/,
      `${dir}: the matching ticket comment must carry the PR URL`,
    )
    // Step 7 is the sole place that CREATES a PR, READIES it and PUSHES, and Step 9 is the sole
    // place that measures the branch green. `capped` reaches none of them. A route that only knows
    // how to `gh pr edit` therefore dead-ends on the common fresh workspace — the same inertness
    // defect the section's own opening paragraph exists to prevent, one level down — and a route
    // that never readies leaves T2 unreadable on a draft whose CI is expected to be partial.
    assert.match(
      section,
      /gh[ ]pr[ ]create --base/,
      `${dir}: the PARTIAL route must create the PR when none exists — Step 7's create arm never ran`,
    )
    assert.match(
      section,
      /gh\s+pr\s+ready\s+"?\$PR_NUMBER"?/,
      `${dir}: the PARTIAL route must ready the PR itself — a draft cannot supply T2's green reading`,
    )
    // Ordering, not mere presence. `gh pr create --body-file "$PR_BODY"` with `$PR_BODY` assembled
    // AFTERWARDS is the same inertness one level further in: on the fresh workspace this arm exists
    // to serve, the create fails on an unset variable and the route never reaches its `gh pr edit`.
    // Step 7's own `PR_BODY="$(mktemp)"` cannot cover it — `capped` never reaches Step 7.
    const bodyInit = section.search(/PR_BODY="?\$\(mktemp\)"?/)
    const createAt = section.indexOf('gh pr create --base')
    assert.ok(
      bodyInit >= 0,
      `${dir}: §PARTIAL-route publication must assemble $PR_BODY itself — Step 7's mktemp never runs on this route`,
    )
    assert.ok(
      bodyInit < createAt,
      `${dir}: $PR_BODY must be assembled BEFORE the gh pr create that consumes it, not after`,
    )
    // The same identifiers Step 7/Preflight set in EARLIER Bash calls, which do not persist. An
    // empty $PR_NUMBER here sends a resume run down the create arm and fails it on "already exists".
    assert.match(
      section,
      /PR_NUMBER="\$\{PR_NUMBER:-/,
      `${dir}: the PARTIAL route must re-derive $PR_NUMBER — shell state does not survive between tool calls`,
    )
    assert.match(
      section,
      /SESSION_BRANCH="\$\{SESSION_BRANCH:-[\s\S]{0,200}BASE_BRANCH="\$\{BASE_BRANCH:-/,
      `${dir}: the PARTIAL route must re-derive $SESSION_BRANCH and $BASE_BRANCH before the create arm uses them`,
    )
    assert.match(
      section,
      /gh[ ]pr[ ]edit[\s\S]{0,200}--title[\s\S]{0,120}\(partial <satisfied>\/<total>\)/,
      `${dir}: the title suffix needs a named mechanism — a body-only write halves boss-epic condition (5)`,
    )
    assert.match(
      section,
      // Both flags and the PR it reads, without pinning argument ORDER: `gh pr checks --watch
      // --fail-fast "$PR_NUMBER"` is the same command, and reddening on a reorder catches no
      // regression. What must not drift is that the reading is taken, on THIS PR, and fails fast.
      /gh\s+pr\s+checks(?=[\s\S]{0,60}\$PR_NUMBER)[\s\S]{0,60}--watch\s+--fail-fast/,
      `${dir}: T2 must be MEASURED on this route — Step 9's green gate never ran`,
    )
    // The gate itself, restated where the route fires. All three conjuncts, plus the explicit
    // refusal of the 0-of-N soft landing.
    for (const [label, re] of [
      ['T1', /\*\*T1[\s\S]{0,240}independently\s+certified/],
      ['T2', /\*\*T2[\s\S]{0,200}green/],
      // Emphasis marker is `_only_` here and `**only**` in finalize-and-stop — nested inside an
      // already-bold T3 lead the marker has to differ, so match either rather than pin the styling.
      [
        'T3',
        /\*\*T3[\s\S]{0,240}[_*]{1,2}only[_*]{1,2}\s+an\s+unsatisfied\s+in-scope\s+acceptance\s+criterion/,
      ],
    ]) {
      assert.match(section, re, `${dir}: §PARTIAL-route publication must re-check ${label} itself`)
    }
    assert.match(
      section,
      /satisfied\s+\*\*zero\*\*\s*\n?\s*criteria\s+is\s+`BLOCKED`,\s+never\s+`PARTIAL`/,
      `${dir}: the route must refuse a 0-of-N run outright`,
    )
    // The failure edges: an unestablished conjunct, and a push that only reached the rescue path,
    // both change the TERMINAL STATE, not merely the report.
    assert.match(
      section,
      /§BLOCKED-route\s+publication[\s\S]{0,120}`BLOCKED`\s+as\s+the\s+terminal\s+state/,
      `${dir}: a failed conjunct must fall back to the BLOCKED route with BLOCKED as the terminal state`,
    )
    assert.match(
      section,
      /`PUSHED=rescue`\s+or\s+`PUSHED=no`\s+the\s+terminal\s+state\s+becomes\s+`BLOCKED`/,
      `${dir}: an unpushed slice must become BLOCKED, not a PARTIAL nobody can fetch`,
    )
    // T1 must be a POSITIVE record, not an absence test. Two routes write a `sentinel capped 1`
    // the run generated for ITSELF — the pre-dispatch floor route below and the degraded tier's
    // did-not-report path — and on both of them no lens ever ran. Under an absence reading
    // ("emitted no must-fix") every criterion on a wholly unreviewed branch certifies vacuously,
    // and the capped arm routes EVERY capped verdict but `dispatch-failure` here, so PARTIAL would
    // be publishable off a review that never happened. The two halves are what closes it.
    // Match the CLAIM, not its punctuation: emphasis markers and the comma are free to move under a
    // reword or a prettier reflow, and a gate that reds on a comma→em-dash edit costs a rewrite it
    // was never meant to police. The windows are generous for the same reason.
    assert.match(
      section,
      /certification\s+is\s+a\s+[_*]{0,2}positive[_*]{0,2}\s+record[\s\S]{0,16}never\s+an\s+absence/,
      `${dir}: T1 must demand a positive certification record — an absence test certifies an unreviewed branch`,
    )
    assert.match(
      section,
      /generated[\s\S]{0,800}[_*]{0,2}fails\s+T1\s+by\s+construction/,
      `${dir}: a self-generated capped verdict must fail T1 outright — no lens ran, so nothing certified`,
    )
    // T1's first half must ask for something boss-review actually emits. Its certification reports
    // only the criteria the branch does NOT evidence, so a demand for a per-criterion "satisfied"
    // reading names an artifact that does not exist: PARTIAL becomes unreachable, or the agent
    // improvises the self-certification the same conjunct forbids two sentences later.
    assert.match(
      section,
      /certification\s+[_*]{0,2}ran[_*]{0,2}\s+over\s+the\s+full\s+supplied\s+criteria\s+list/,
      `${dir}: T1's positive half must be the certification RUN over the supplied list — a verifiable fact`,
    )
    assert.match(
      section,
      /verdict\s+a\s+[_*]{0,2}reviewer[_*]{0,2}\s+authored/,
      `${dir}: T1 must require a reviewer-authored verdict — the half a self-generated capped verdict cannot supply`,
    )
    // T2 is read only AFTER the ready + both writes (a draft cannot supply it), so the red path
    // must undo the partial title, body and do-not-merge marker before it reports BLOCKED —
    // otherwise boss-epic condition (5) keeps holding the PR on a marker that is now false.
    assert.match(
      section,
      /red\s+reading\s+must\s+[_*]{1,2}unwind[_*]{1,2}\s+before\s+it\s+reports/,
      `${dir}: a red T2 must unwind the partial artifact — publication precedes the reading`,
    )
    assert.match(
      fences,
      /gh\s+pr\s+edit\s+"\$PR_NUMBER"(?:[^\n]|\\\n)*?--body-file\s+"\$BLOCKED_BODY"/,
      `${dir}: the unwind needs a real command that rewrites title and body, not a described intent`,
    )
    // ...and `$BLOCKED_BODY` must be ASSEMBLED, before the write that consumes it. Naming a file in
    // a `--body-file` that nothing ever creates is the unset-variable defect this section already
    // names for `$PR_BODY`, three paragraphs up, reappearing on the one path that repairs a false
    // PARTIAL claim: the unwind fails, the PR keeps the partial title, body and do-not-merge marker,
    // and boss-epic condition (5) holds it on a marker that is now false.
    const blockedInit = fences.search(/BLOCKED_BODY="?\$\(mktemp\)"?/)
    const unwindAt = fences.search(/--body-file\s+"\$BLOCKED_BODY"/)
    assert.ok(
      blockedInit >= 0,
      `${dir}: the unwind must assemble $BLOCKED_BODY itself — no other step composes a blocked body here`,
    )
    assert.ok(
      blockedInit < unwindAt,
      `${dir}: $BLOCKED_BODY must be assembled BEFORE the gh pr edit that consumes it, not after`,
    )
    // The unwind fires from a LATER Bash call than the acquisition block that set $PR_NUMBER — the
    // red `gh pr checks --watch` reading is what sends you here — and shell state does not survive
    // between tool calls. An unwind that inherits an empty $PR_NUMBER runs `gh pr edit ""`, fails,
    // and leaves the false PARTIAL claim standing on title, body and marker alike. Same defect the
    // acquisition block already names for itself; it has to be named in this fence too.
    // Scoped to the unwind's OWN fences — plural, and joined in source order. The compose step and
    // the write that consumes it deliberately sit in separate fences (so a verbatim run of the first
    // cannot publish an empty body), and `.find` would then see only the first of them and stop
    // enforcing the ordering below. Filtering keeps the acquisition block — which re-derives
    // $PR_NUMBER for its own reasons — out of scope, which is what `.find` was for.
    const unwindFence = fenceList.filter((f) => f.includes('BLOCKED_BODY')).join('\n')
    assert.match(
      unwindFence,
      /PR_NUMBER="\$\{PR_NUMBER:-/,
      `${dir}: the unwind fence must re-derive $PR_NUMBER itself — it runs in a later call than the acquisition block`,
    )
    assert.ok(
      unwindFence.search(/PR_NUMBER="\$\{PR_NUMBER:-/) <
        unwindFence.search(/--body-file\s+"\$BLOCKED_BODY"/),
      `${dir}: the unwind must re-derive $PR_NUMBER BEFORE the gh pr edit that uses it`,
    )
    // Composing and consuming $BLOCKED_BODY in ONE runnable block is the defect one level down from
    // CR1: `mktemp` returns an EMPTY file, so an agent that runs the block verbatim publishes a body
    // with no `## Cross-model review` and no `## Review coverage` section — and an absent mandatory
    // section reads as FULL coverage, on the one route that exists because coverage was reduced.
    // `$PR_BODY` is already split this way three paragraphs down for exactly this reason. If a future
    // author composes the body inline instead, that is a fine fix — update this pin with it; do not
    // re-merge the fences and delete the assertion.
    const consumesBlockedBody =
      fenceList.find((f) => /--body-file\s+"\$BLOCKED_BODY"/.test(f)) ?? ''
    assert.doesNotMatch(
      consumesBlockedBody,
      /BLOCKED_BODY="?\$\(mktemp\)"?/,
      `${dir}: the fence that WRITES $BLOCKED_BODY must not also mktemp it — run verbatim, that publishes an empty body`,
    )
    // An empty $PR_NUMBER reaching `gh pr edit ""` is a spurious "failed unwind" blocker on the one
    // path where nothing was ever published (the create arm itself failed), so there is no partial
    // claim to restore. Guard it, and keep `rm -f` outside the guard so the temp file never leaks.
    assert.match(
      unwindFence,
      /\[\s+-n\s+"\$PR_NUMBER"\s+\]/,
      `${dir}: the unwind must guard an empty $PR_NUMBER — no PR was created means nothing to unwind, not a blocker`,
    )
    // The unwind must also un-ready. Readying is THIS route's own write (T2 is unreadable on a
    // draft), so a BLOCKED report that only rewrites title and body ships a ready PR — contradicting
    // Step 9's "do not ready" and leaving boss-epic condition (4) as the sole remaining hold.
    assert.match(
      fences,
      /gh\s+pr\s+ready\s+--undo\s+"?\$PR_NUMBER"?|gh\s+pr\s+ready\s+"?\$PR_NUMBER"?\s+--undo/,
      `${dir}: the unwind must un-ready the PR — every other BLOCKED path leaves a draft`,
    )
    // T3's required set is Step 9's. A locally restated, shorter copy is the weakest of the three
    // wordings and it is the one governing the live route. The deference is about the MEMBERSHIP of
    // that list only — read unqualified, "Step 9 governs" also points T1 at Step 9's copy, and an
    // adversarial reader resolves any strength difference there in favour of the weaker wording.
    assert.match(
      section,
      /\*\*T3[\s\S]{0,1200}[_*]{0,2}Step\s+9\s+governs/,
      `${dir}: T3 must defer to Step 9's full required list, not restate a shorter one`,
    )
    assert.match(
      section,
      /Step\s+9\s+governs[\s\S]{0,400}[_*]{0,2}stronger[_*]{0,2}\s+reading\s+governs/,
      `${dir}: the deference must be scoped to the required-item list — never a licence to adopt a weaker conjunct`,
    )
    // The body is Step 7's plus a delta. This route owns the ONLY body write on the capped path, so
    // a from-scratch re-specification here silently drops the elements every other route guarantees.
    assert.match(
      section,
      /body\s+is\s+Step\s+7's\s+PR\s+body\s+plus\s+a\s+delta[\s\S]{0,1200}`## Autonomous\s+decisions`/,
      `${dir}: the PARTIAL body must inherit Step 7's body — including the elements only Step 7 lists`,
    )
  }
})

// The one edge that makes PARTIAL REACHABLE at all. Everything else here pins the state's
// description; this pins the link from the review loop's `capped` verdict to the publication route.
// Delete that link and PARTIAL is described everywhere and produced nowhere — inertness one level up
// from where the section defends it — while every other assertion in this file stays green.
test('BOS-842: the review loop’s `capped` arm routes to the PARTIAL publication section (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const routes = region(
      buildBody(dir),
      '**Route on the file verdict.**',
      'Steps 6b and 6c are',
      `${dir}/SKILL.md`,
    )
    const capped = region(routes, '- `capped` →', '- `dispatch-failure`', `${dir}/SKILL.md`)
    assert.match(
      capped,
      /§PARTIAL-route\s+publication/,
      `${dir}: the capped arm must name §PARTIAL-route publication — without it PARTIAL has no producer`,
    )
    assert.match(
      capped,
      /publishes\s+`PARTIAL`/,
      `${dir}: the capped arm must say it PUBLISHES PARTIAL, not merely that PARTIAL exists`,
    )
    assert.match(
      capped,
      // `lens-certified`, not a bare `certified`: this arm is the live route, and an agent that
      // reads its own assertion as the certification is the exact failure T1 exists to refuse.
      /≥1\s+lens-certified/,
      `${dir}: the capped arm must carry T1 and name the LENS as certifier, not leave it self-assertable`,
    )
    assert.match(
      capped,
      /green\s+branch/,
      `${dir}: the capped arm must carry T2 — a red branch is BLOCKED, never PARTIAL`,
    )
    // …and the default is unchanged: every other capped run is still BLOCKED.
    assert.match(
      capped,
      /\*\*Stop\s+cleanly\*\*\s+`BLOCKED`/,
      `${dir}: every other capped run must still stop cleanly BLOCKED`,
    )
  }
})

// The reachability criterion. Everything above proves PARTIAL is DESCRIBED; only this proves it is
// HELD. boss-epic's merge gate condition (5) had no producer before this ticket, and it matches a
// literal string — so a one-character drift on either side (an em dash reflowed to a hyphen, a
// reworded count phrase) silently un-holds every PARTIAL PR while both files still read correctly
// in isolation. The literal is EXTRACTED from boss-build and asserted into boss-epic rather than
// hard-coded twice: a hard-coded copy in the test is a third place to drift, and it would let both
// skills be edited together into agreement on a string the gate no longer matches.
test('BOS-842: the do-not-merge marker is byte-identical across boss-build and boss-epic (all mirrors)', () => {
  const pairs = BUILD_MIRRORS.map((buildDir, i) => [buildDir, EPIC_MIRRORS[i]])
  for (const [buildDir, epicDir] of pairs) {
    const section = region(
      readReviewStack(buildDir),
      '### PARTIAL-route publication',
      '### BLOCKED-route publication',
      `${buildDir}/references/review-stack.md`,
    )
    // Anchored on "exactly this literal:" plus the fence, not on the full sentence: the sentence's
    // wording is not the contract, the quoted bytes are. `[a-z]*` tolerates a language tag, and the
    // fence must be the FIRST one after the phrase so an added example block cannot be picked up.
    const quoted = section.match(/exactly\s+this\s+literal:\s*\n+```[a-z]*\n([^\n]+)\n```/)
    assert.ok(
      quoted,
      `${buildDir}: §PARTIAL-route publication must quote the do-not-merge marker in a fenced block`,
    )
    const marker = quoted[1]
    assert.match(
      marker,
      /^do\s+not\s+merge/,
      `${buildDir}: the extracted literal must be the do-not-merge marker`,
    )
    const mergeRecovery = fs.readFileSync(
      path.join(rootDir, epicDir, 'references/merge-recovery.md'),
      'utf8',
    )
    assert.ok(
      mergeRecovery.includes(marker),
      `${epicDir}/references/merge-recovery.md must match boss-build's marker byte-for-byte: ${JSON.stringify(marker)}`,
    )
    // …and the resident boss-epic body, which restates condition (5) twice without opening a
    // reference. A marker that only agrees in the reference still un-holds a run that read the body.
    const epicBody = fs.readFileSync(path.join(rootDir, epicDir, 'SKILL.md'), 'utf8')
    assert.ok(
      epicBody.includes(marker),
      `${epicDir}/SKILL.md must quote the same marker byte-for-byte: ${JSON.stringify(marker)}`,
    )
    assert.match(
      mergeRecovery,
      /a\s+`PARTIAL`\s+child\s+writes\s+it/i,
      `${epicDir}: condition (5) must name PARTIAL as the marker's producer`,
    )
  }
})

test('BOS-842: core-spine §1 carries four AGENT-NEUTRAL terminal states (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const spine = fs.readFileSync(path.join(rootDir, dir, 'references/core-spine.md'), 'utf8')
    const one = region(spine, '## 1. Four terminal states', '## 2. ', `${dir}/core-spine.md`)
    for (const state of ['review-ready', 'blocked', 'partial', 'no-change']) {
      assert.match(
        one,
        new RegExp(`^- \\*\\*${state}\\*\\*`, 'm'),
        `${dir}: core-spine §1 must carry an agent-neutral **${state}** bullet`,
      )
    }
    // The bolded invariant stays UNCONDITIONAL, and the exception lives in the sentence after it.
    // core-spine.md is the agent-neutral summary — the one file an implementer of a non-Claude
    // runner reconstructs the contract from — so a bolded sentence narrowed to "a required item
    // THAT IS NOT AN ACCEPTANCE CRITERION forces blocked" reads, on its own, as a grant of
    // review-ready to precisely the run PARTIAL was invented for, with the restriction recoverable
    // only from unbolded prose that looks subordinate. It also needs no narrowing: partial is not
    // review-ready, so "never review-ready" is true of it as written. Every other site keeps the
    // invariant whole and routes the criterion case to partial; this must not be the weak copy.
    assert.match(
      one,
      /\*\*a\s+deferred\s+_required_\s+item\s+forces\s*\n?\s*blocked,\s+never\s*\n?\s*review-ready\.\*\*/,
      `${dir}: core-spine §1's bolded invariant must stay unconditional — "a deferred required item forces blocked, never review-ready"`,
    )
    // The narrowed form is forbidden only where the hazard lives: inside the bolded span an agent
    // quotes on its own. BOS-842's plan asked for that exact restatement, and it is genuinely the
    // operative test — it is only unsafe when it is the sentence a reader takes away INSTEAD of the
    // three conjuncts, which is what emphasis does. So it survives here unbolded and downstream of
    // the exception, and the assertion below pins that ordering rather than banning the words.
    assert.doesNotMatch(
      one,
      /\*\*[^*]{0,120}item\s+that\s+is\s+not\s+an\s+acceptance\s*\n?\s*criterion\s+forces\s+blocked/,
      `${dir}: core-spine §1 must not narrow the BOLDED invariant by excluding acceptance criteria from it`,
    )
    // ...and the plan's restatement must actually be present, downstream of the conjuncts, so a
    // reader who reconstructs the contract from this file alone still learns the operative test.
    const narrowed = one.search(
      /a\s+deferred\s+required\s+item\s+that\s+is\s+not\s+an\s+acceptance\s*\n?\s*criterion\s*\n?\s*forces\s+blocked/,
    )
    const exception = one.search(/\*\*single\*\*\s+exception\s+is\s+partial/)
    assert.ok(
      narrowed > 0,
      `${dir}: core-spine §1 must restate the operative test — "a deferred required item that is not an acceptance criterion forces blocked"`,
    )
    assert.ok(
      exception > 0 && narrowed > exception,
      `${dir}: core-spine §1's restatement must follow the scoped exception, never precede it`,
    )
    // ...and the exception must still be there, scoped, in the sentence that follows it.
    assert.match(
      one,
      /\*\*single\*\*\s+exception\s+is\s+partial[\s\S]{0,400}\*\*every\*\*\s+deferred\s+required\s+item\s+is\s+an\s+unsatisfied\s+acceptance\s+criterion/,
      `${dir}: core-spine §1 must still name partial as the single, scoped exception`,
    )
    // This file is the published, project-agnostic spine. The new prose must not smuggle in the
    // uppercase state tokens (workspace-specific spellings) or any project name.
    assert.doesNotMatch(
      one,
      /bossanova|linear|BOS-\d+/i,
      `${dir}: core-spine §1 must stay project-agnostic`,
    )
    assert.doesNotMatch(
      one,
      /REVIEW_READY|NO_CHANGE|PARTIAL/,
      `${dir}: core-spine §1 must use agent-neutral state names, not boss-build's literal tokens`,
    )
  }
})

test('BOS-775: Step 2 keeps agent-question informational for selection', () => {
  const skill = fs.readFileSync(path.join(rootDir, `${CORE}/SKILL.md`), 'utf8')
  assert.match(
    skill,
    /`agent-question`\s+never\s+blocks;\s+no\s+override[\s\S]{0,80}`##\s+Open\s+Questions`\s+to\s+PR/,
    'named-ID branch must state agent-question needs no override',
  )
  assert.match(
    skill,
    /`agent-question`\s+does\s+not\s+exclude\s+a\s+candidate[\s\S]{0,80}`##\s+Open\s+Questions`\s+to\s+PR/,
    'auto-queue branch must keep agent-question informational and publish questions',
  )
})

test('BOS-842: all three user-facing docs enumerate PARTIAL alongside the other three', () => {
  // The docs surfaces are what a human reads before they ever open a skill. An enumeration that
  // still lists three states tells a reviewer a do-not-merge PR is an anomaly rather than a
  // documented outcome — and these three pages are the only places the state set is published
  // outside the skill tree.
  for (const rel of [
    'docs/skills/boss-build.md',
    'docs/skills/README.md',
    'services/docs/docs/skills/overview.md',
  ]) {
    const doc = fs.readFileSync(path.join(rootDir, rel), 'utf8')
    for (const state of ['REVIEW_READY', 'PARTIAL', 'BLOCKED', 'NO_CHANGE']) {
      assert.match(doc, new RegExp(`\`${state}\``), `${rel} must enumerate \`${state}\``)
    }
    assert.match(
      doc,
      /do-not-merge/,
      `${rel} must say what makes PARTIAL different: the PR is opened but marked do-not-merge`,
    )
    assert.doesNotMatch(
      doc,
      /three\s+terminal\s+states/i,
      `${rel} must not still describe three terminal states`,
    )
  }
})

// BOS-798: the blast-radius rules for prose edits. Each one exists because a prose change was
// scoped to the line someone quoted and the real site was elsewhere — a reader the plan never
// enumerated, a fixture directory nobody grepped, a corrected sentence that shipped unpinned.
//
// These live in `references/core-spine.md` §2 rather than in the resident Step 5 body, and that is
// forced, not preference: the binding constraint is `bytes <= RATCHET`, and the live SKILL.md sits
// single-digit bytes under it, so ~1.5 KB of resident prose is not spendable at any wording. (The
// RATCHET-to-baseline gap is a different, larger number; it is not the one that stops you.) §2 is
// the portable shape of Step 5 and the section that describes what a task brief carries, so it is
// where a run composing a brief is standing.
//
// A reference is only read when its trigger fires, so the two places that route a run there are
// pinned below: Step 5's first paragraph, and the reference table's own "read it when" cell. Both
// are prose that rewraps — the table cell is re-padded by prettier whenever a sibling row changes
// width — so both pins are `\s+`-tolerant.
//
// The pins are whitespace-tolerant (`\s+`, never a literal space) because these sentences sit in
// paragraphs that rewrap whenever a neighbouring one is edited, and a literal-space pin would red
// on the rewrap while naming no real defect.
test('BOS-798: core-spine §2 carries the three blast-radius rules for prose edits (both mirrors)', () => {
  for (const dir of BUILD_MIRRORS) {
    const spine = fs.readFileSync(path.join(rootDir, dir, 'references/core-spine.md'), 'utf8')
    const rules = region(
      spine,
      // Short, rewrap-stable fragments. A full-sentence literal marker is itself a literal-space
      // prose pin: it reds loudly and falsely the first time the sentence rewraps, which is the
      // shape rule 5 forbids. `region()` names the marker it could not find, so a genuine removal
      // still fails loudly.
      "**A prose task's blast radius",
      'Discovery itself reports',
      `${dir}/references/core-spine.md`,
    )

    assert.match(
      rules,
      /the\s+brief\s+carries\s+these\s+three\s+rules/,
      `${dir}: the rules must be addressed to the implementation brief, not left as free-floating advice`,
    )

    // Rule 2 — enumerate every reader before moving a prose span.
    assert.match(
      rules,
      /Before\s+extracting\s+or\s+relocating\s+a\s+passage\s+out\s+of\s+a\s+skill\s+body/,
      `${dir}: the enumerate-every-reader rule must be present`,
    )
    assert.match(
      rules,
      /grep\s+for\s+every\s+file\s+that\s+reads\s+that\s+exact\s+path/,
      `${dir}: the enumerate-every-reader rule must prescribe the grep, not merely warn`,
    )
    assert.match(
      rules,
      /the\s+plan\s+will\s+not\s+have\s+named\s+them/,
      `${dir}: the enumerate-every-reader rule must say why the plan is not the source of the reader list`,
    )

    // Rule 4 — a glyph or format change is a whole-directory grep, not the cited file.
    assert.match(
      rules,
      /When\s+the\s+change\s+is\s+a\s+glyph\s+or\s+a\s+formatting\s+convention/,
      `${dir}: the glyph/format rule must be present`,
    )
    assert.match(
      rules,
      /grep\s+whole\s+directories/,
      `${dir}: the glyph/format rule must prescribe whole directories`,
    )
    assert.match(
      rules,
      /cannot\s+cover\s+the\s+copy\s+nobody\s+thought\s+to\s+enumerate/,
      `${dir}: the glyph/format rule must say why an enumerated file list is insufficient`,
    )

    // Rule 5 — a corrected sentence is pinned in the same commit, whitespace-tolerantly, and the
    // pin is falsified before the subagent returns.
    assert.match(
      rules,
      /When\s+the\s+deliverable\s+is\s+a\s+corrected\s+sentence/,
      `${dir}: the pin-the-sentence rule must be present`,
    )
    assert.match(
      rules,
      /`\\s\+`\s+between\s+words,\s+never\s+a\s+literal\s+space/,
      `${dir}: the pin rule must state the whitespace contract, not merely say "add a pin"`,
    )
    assert.match(
      rules,
      /see\s+the\s+gate\s+go\s+red,\s+restore,\s+see\s+it\s+go\s+green/,
      `${dir}: the pin rule must require the pin be FALSIFIED, not merely added`,
    )
    assert.match(
      rules,
      /equally\s+whitespace-tolerant\s+substitution/,
      `${dir}: the mutation used to falsify must itself be whitespace-tolerant — a literal-space substitution matches nothing and passes as green`,
    )
    // The upstream contract this rule derives from runs both ways: `\s+` matches a newline, so it
    // is a widening, and a pin over a command or a code shape must keep the literal space. Dropping
    // that half is the derived-copy defect rule 1 exists to catch, so the derived copy pins it.
    assert.match(
      rules,
      /`\\s\+`\s+also\s+matches\s+a\s+newline/,
      `${dir}: the pin rule must carry the widening caveat, not only the "never a literal space" half`,
    )
    assert.match(
      rules,
      /a\s+pin\s+over\s+a\s+command\s+or\s+a\s+code\s+shape\s+keeps\s+the\s+literal\s+space/,
      `${dir}: the widening caveat must name the case it exempts`,
    )

    // The rules are only reachable if something routes a run into this reference. Pin both routes.
    const skill = fs.readFileSync(path.join(rootDir, dir, 'SKILL.md'), 'utf8')
    assert.match(
      skill,
      /its\s+portable\s+shape\s+is\s+\[`references\/core-spine\.md`\]/,
      `${dir}: Step 5 must keep pointing at core-spine.md, or the rules above are unreachable from the step that needs them`,
    )
    assert.match(
      skill,
      /`references\/core-spine\.md`\s*\|\s*Orienting[^|]*before\s+any\s+skill-body\s+or\s+contract\s+prose\s+edit/,
      `${dir}: the reference table's cell must name a CONDITION that fires, not just describe what §2 contains — every other row in that table names a step`,
    )
  }
})

// ───────────────────────────────────────────────────────────────────────────────
// BOS-964: the review verdict must survive a subagent that dies with it undelivered.
//
// The observed failure: the Step 6 stack returned a complete `<!-- bs-review -->` report — four
// named reviewers, a finding ledger, a gate table — and `bs-run-sentinel read` returned
// `{"status":"missing"}`. Routing behaved correctly (it routes on the FILE, never on the returned
// prose) and forced BLOCKED with `none: review coverage unknown` for a run that was finished. The
// write was one unguarded step scheduled as the subagent's LAST action, after the whole advisory
// Step 6c pass, so anything ending the subagent between "verdict determined" and "verdict written"
// destroyed a verdict for work that was really done.
//
// Two independent directions close it, plus the discriminator that keeps them distinguishable:
// the orchestrator SEEDS a provisional pessimistic verdict before it dispatches (so `missing` is
// unreachable once the stack is entered), the subagent writes the real verdict the MOMENT it is
// known, and the seed carries a `provisional` payload marker so a seed nobody upgraded routes to
// the safe branch AND is still reported honestly instead of passing as a cap a reviewer earned.
//
// The hazard this must not create: one sentinel string reachable from two opposite causes is not a
// diagnostic. The marker is the discriminator — branch on whether the observation happened, never
// on the kind string, the round count, or the returned prose.

/** The single fenced bash block in `md` that emits the generated `capped 1` sentinel. */
function cappedSeedBlock(md, label) {
  const blocks = bashBlocksOf(md).filter((b) => /sentinel\s+capped\s+1/.test(b))
  assert.equal(
    blocks.length,
    1,
    `${label}: Step 6 must carry exactly one runnable seed block — an inline backticked command cannot be extracted or executed, so it cannot be gated`,
  )
  return blocks[0]
}

test('BOS-964: the shipped Step 6 seed block really writes a provisional capped sentinel', () => {
  // EXECUTABLE, not prose-pinning. This is the assertion that would have caught the observed
  // failure class: it runs the block the body actually ships against a real run dir and requires
  // the sentinel to come back out of the FILE classified, with the marker set.
  for (const dir of BUILD_MIRRORS) {
    const skill = readSkill(`${dir}/SKILL.md`)
    const toolbox = path.join(rootDir, dir, 'toolbox')
    const runSentinel = path.join(toolbox, 'bs-run-sentinel.mjs')
    const caps = path.join(toolbox, 'bs-review-caps.mjs')
    const block = cappedSeedBlock(skill, `${dir}/SKILL.md`)

    // (a) SHAPE — generated through the caps helper AND persisted through the run-file writer.
    // Either half alone lands on `dispatch-failure` from opposite directions: a hand-written
    // literal is unmatchable, and a helper that only prints leaves the run file absent.
    assert.match(
      block,
      /node\s+"\$RUN_SENTINEL"\s+write\s+"\$RUN_DIR"\s+"\$RUN_ID"\s+review[\s\S]{0,200}bs-review-caps\.mjs"?\s+sentinel\s+capped\s+1/,
      `${dir}/SKILL.md: the seed must be GENERATED by bs-review-caps.mjs and PERSISTED by bs-run-sentinel.mjs write`,
    )
    // The anti-drift join: the payload literal in the shipped markdown is the module's constant.
    // Two hand-written stores of one string drift; this is what stops them.
    assert.ok(
      block.includes(`'{"${PROVISIONAL_KEY}":true}'`),
      `${dir}/SKILL.md: the seed's payload literal must equal PROVISIONAL_KEY from skills-toolbox/bs-run-sentinel.mjs`,
    )

    const base = fs.mkdtempSync(path.join(os.tmpdir(), 'boss-build-seed-'))
    try {
      // The block makes its own context via `make-ctx`, which defaults to $TMPDIR — so point that
      // at a scratch dir and read the ids back out of the block's own variables afterwards.
      const stdout = execFileSync(
        'bash',
        ['-c', `${block}\nprintf '%s\\t%s' "$RUN_ID" "$RUN_DIR"`],
        {
          encoding: 'utf8',
          env: { ...process.env, BOSS_BUILD_TOOLBOX: toolbox, TMPDIR: base },
        },
      )
      const [runId, runDir] = stdout.split('\n').pop().split('\t')
      assert.ok(
        runId && runDir,
        `${dir}/SKILL.md: the seed block must provision RUN_ID and RUN_DIR`,
      )

      const readBack = () =>
        JSON.parse(
          execFileSync('node', [runSentinel, 'read', runDir, runId, 'review'], {
            encoding: 'utf8',
          }),
        )
      const classify = (kind) =>
        JSON.parse(execFileSync('node', [caps, 'match', kind], { encoding: 'utf8' }))

      // (b) THE SEED IS ROUTABLE. `missing` is what the observed run read; after the seed the same
      // death reads as a classified `capped`, which is a route the orchestrator already has.
      const seeded = readBack()
      assert.equal(
        seeded.status,
        'ok',
        `${dir}/SKILL.md: the seed must WRITE the sentinel to the run file before the dispatch`,
      )
      assert.deepEqual(
        classify(seeded.kind),
        { status: 'capped', rounds: 1 },
        `${dir}/SKILL.md: the seeded sentinel must classify as capped (got ${JSON.stringify(seeded.kind)})`,
      )
      // (c) …AND HONEST. Without the marker this `capped 1` is byte-identical to one a reviewer
      // earned, which is the two-opposite-causes hazard the marker exists to close.
      assert.equal(
        seeded.payload?.provisional,
        true,
        `${dir}/SKILL.md: the seed must carry payload.provisional === true, or a dead dispatch reads as a genuine cap`,
      )

      // (d) THE UPGRADE PATH. A later non-provisional write to the same (dir, runId, name) must
      // OVERWRITE the seed — otherwise the seed pins every run pessimistically forever.
      execFileSync(
        'bash',
        [
          '-c',
          `node "$RUN_SENTINEL" write "$RUN_DIR" "$RUN_ID" review "$(node "$CAPS" sentinel clean)" '{"provisional":false}'`,
        ],
        {
          encoding: 'utf8',
          env: {
            ...process.env,
            RUN_SENTINEL: runSentinel,
            CAPS: caps,
            RUN_DIR: runDir,
            RUN_ID: runId,
          },
        },
      )
      const upgraded = readBack()
      assert.equal(upgraded.status, 'ok')
      assert.equal(
        classify(upgraded.kind).status,
        'clean',
        `${dir}/SKILL.md: a non-provisional clean write must overwrite the seed`,
      )
      assert.ok(
        !upgraded.payload?.provisional,
        `${dir}/SKILL.md: the upgraded verdict must not still read as provisional`,
      )
    } finally {
      fs.rmSync(base, { recursive: true, force: true })
    }
  }
})

test('BOS-964: the classify block reads the marker and the route list carries the fourth arm', () => {
  for (const dir of BUILD_MIRRORS) {
    const skill = readSkill(`${dir}/SKILL.md`)
    const step6 = region(
      skill,
      '## Step 6: Whole-branch review',
      '## Step 6.5: Knowledge extensions',
    )

    // The orchestrator already has `jq` and the read result in hand, so the discriminator costs one
    // line rather than a second node spawn.
    assert.match(
      step6,
      /PROVISIONAL="\$\(printf '%s' "\$READ" \| jq -r '\.payload\.provisional \/\/ empty'\)"/,
      `${dir}/SKILL.md: the classify block must read the payload marker, or the fourth route arm has no input`,
    )
    // The arm itself: a seed nobody upgraded is BLOCKED — never PARTIAL (no lens ran, so T1 is
    // unestablishable) and never clean.
    assert.match(
      step6,
      /`capped`\s+with\s+`PROVISIONAL`\s*=\s*`true`[\s\S]{0,240}BLOCKED/i,
      `${dir}/SKILL.md: the route list must carry a fourth arm for a provisional verdict that survived`,
    )
    assert.match(
      step6,
      /`capped`\s+with\s+`PROVISIONAL`[\s\S]{0,240}\*\*never\*\*\s+PARTIAL[\s\S]{0,60}\*\*never\*\*\s+clean/i,
      `${dir}/SKILL.md: the provisional arm must exclude BOTH the PARTIAL and the clean routes by name`,
    )
    // The bug this ticket must not reintroduce: inferring "the subagent didn't write" from anything
    // other than the marker. Pin the prohibition positively AND deny the prose-reading route.
    assert.match(
      step6,
      /payload\s+marker\s+alone,\s+never\s+from\s+the\s+kind,\s+the\s+round\s+count\s+or\s+the\s+returned\s+prose/i,
      `${dir}/SKILL.md: the provisional arm must be decided from the marker alone`,
    )
    const routes = region(
      skill,
      '**Route on the file verdict.**',
      '## Step 6.5: Knowledge extensions',
    )
    assert.doesNotMatch(
      routes,
      /(route|classify|verdict)[\s\S]{0,80}(from|on)\s+the\s+(subagent's\s+)?(returned\s+)?(reply|prose)\b(?![\s\S]{0,40}never)/i,
      `${dir}/SKILL.md: no route arm may read the subagent's reply to determine the verdict`,
    )
    // ORDER, not just presence. The two `capped` arms are not mutually exclusive as written — a
    // provisional verdict matches both — and the list is read top-down, so the narrower arm must
    // come first or a reader takes the PARTIAL-eligible one and publishes a state no reviewer
    // earned. The prose says so twice ("Take this arm **before** the next one", "→ otherwise"),
    // but prose is what a re-wrap reorders; `precedes` throws on a marker that moved rather than
    // going green on a -1 index.
    assert.ok(
      precedes(
        routes,
        '- `capped` with `PROVISIONAL` = `true`',
        '- `capped` → otherwise',
        `${dir}/SKILL.md`,
      ),
      `${dir}/SKILL.md: the provisional arm must be evaluated BEFORE the PARTIAL-eligible capped arm`,
    )
  }
})

test('BOS-964: review-stack tells the subagent to write the verdict when it is determined', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const contract = region(
      reviewStack,
      '**Write your terminal verdict to the run file',
      '## Step 6 entry — review tier selection',
    )

    // (a) THE RULE. A last-action-only write is the defect; the write must land at the line that
    // determines the verdict and be re-affirmed at the end.
    assert.match(
      contract,
      /the\s+moment\s+the\s+blocking\s+verdict\s+is\s+determined\*{0,2},\s+and\s*\n?\s*re-affirm/i,
      `${dir}: the contract must require the write when the verdict is determined, not only last`,
    )
    // …and the bare last-action phrasing must not stand alone. region() throws on a moved marker,
    // so this negative cannot go vacuous the way a raw slice would.
    assert.doesNotMatch(
      contract,
      /As\s+your\s+\*\*last\s+action\*\*,\s+write/i,
      `${dir}: the bare "as your last action, write" instruction must not survive without the write-when-known rule`,
    )
    // (b) THE MARKER IS ALWAYS EXPLICIT. "Not provisional" is stated, never inferred from absence.
    assert.ok(
      contract.includes(`'{"${PROVISIONAL_KEY}":false}'`),
      `${dir}: every subagent write must carry the explicit non-provisional payload literal`,
    )
    // …including the two generated `capped 1` routes elsewhere in this file. The contract states
    // the marker is "always present and explicit rather than inferred from absence"; an absolute
    // rule with in-file exceptions is how the next reader concludes the marker is optional. Both
    // are the "no lens ever ran" routes, so they are the sites where explicitness matters most.
    // A whole-file count, deliberately: the invariant is that NO generated `capped 1` write in
    // this file leaves the marker to be inferred from absence, and a count is the only shape that
    // stays true when a fourth such route is added. `region()` cannot express it — both routes'
    // fences share an end marker that first occurs earlier in the file.
    // Interpolate the constant rather than re-typing the literal: the assertion above already
    // tracks `PROVISIONAL_KEY`, and a neighbour that silently kept pinning the old spelling is the
    // drift this join exists to stop. The key is asserted regex-safe so no escaping is needed.
    assert.match(PROVISIONAL_KEY, /^[A-Za-z_][A-Za-z0-9_]*$/, 'PROVISIONAL_KEY must be regex-safe')
    const markedTail = `'\\{"${PROVISIONAL_KEY}":false\\}'`
    const bareCapped =
      reviewStack.match(new RegExp(`sentinel\\s+capped\\s+1\\)"(?!\\s+${markedTail})`, 'g')) ?? []
    assert.equal(
      bareCapped.length,
      0,
      `${dir}: every generated \`capped 1\` write must state '{"provisional":false}' — found ${bareCapped.length} relying on the marker's absence`,
    )
    const markedCapped =
      reviewStack.match(new RegExp(`sentinel\\s+capped\\s+1\\)"\\s+${markedTail}`, 'g')) ?? []
    assert.ok(
      markedCapped.length >= 2,
      `${dir}: the below-floor route and the degraded did-not-report route must both still write a generated capped 1 (found ${markedCapped.length})`,
    )

    // (c) EACH WRITE POINT, at the step that owns it — not only listed in the contract preamble.
    const loop = region(
      reviewStack,
      '## Step 6: Whole-branch review loop',
      '### Mechanical remediation extension',
    )
    // Window widened 200 → 400 for the API-surface precondition that now sits between the two:
    // the required gate has to RUN before the clean write, or a death during that awaited, clamped
    // classification publishes clean over an unrun required gate. The span still ends well before
    // loop step 4, so the assertion continues to pin the write inside step 3.
    assert.match(
      loop,
      /\*\*Clean\s+check\.\*\*[\s\S]{0,400}write\s+`sentinel\s+clean`\s+to\s+the\s+run\s+file\s+here/i,
      `${dir}: the loop's clean exit must write the verdict where it is decided`,
    )
    assert.match(
      loop,
      /\*\*Clean\s+check\.\*\*[\s\S]{0,160}API-surface\s+check[\s\S]{0,200}\*\*first\*\*/i,
      `${dir}: the loop's clean exit must run the required API-surface check BEFORE writing clean`,
    )
    assert.match(
      loop,
      /\*\*Oscillation\s+guard\.\*\*[\s\S]{0,400}write\s+`sentinel\s+capped\s+<N>`\s+to\s+the\s+run\s+file\s+here/i,
      `${dir}: the oscillation-guard capped path must write the verdict where it is decided`,
    )
    assert.match(
      loop,
      /\*\*Increment\.\*\*[\s\S]{0,260}write\n?\s*`sentinel\s+capped\s+<N>`\s+to\s+the\s+run\s+file\s+here/i,
      `${dir}: the round-overflow capped path must write the verdict where it is decided`,
    )
    const step6b3 = region(
      reviewStack,
      '**3. Fix + bounded re-review.**',
      '**4. Record the outcome (idempotent).**',
    )
    assert.match(
      step6b3,
      /re-affirm\s+it\s+the\s+moment\s+this\s+settles/i,
      `${dir}: Step 6b §3 is the last pass that can move the blocking verdict, so it must re-write it`,
    )
    // …and it must DEMOTE first. Writing only on the way out leaves the Step 6 loop's `clean` on
    // disk across the one interval where the branch carries an outside-voice fix nothing has
    // reviewed — so a death there would ship an unverified fix as a clean run, which is strictly
    // worse than the missing sentinel the last-action-only contract used to leave. Pin the ORDER,
    // because "write twice" without an order is the same defect wearing a second write.
    assert.match(
      step6b3,
      /\*\*Before\s+the\s+fix\s+leg\*\*[\s\S]{0,200}write\n?\s*`sentinel\s+capped\s+<N>`/i,
      `${dir}: Step 6b §3 must demote the run-file verdict BEFORE its fix leg, not only after the confirming round`,
    )
    assert.ok(
      precedes(
        step6b3,
        '**Before the fix leg**',
        '**After the one confirming round returns**',
        `${dir} (Step 6b §3)`,
      ),
      `${dir}: §3's pessimistic write must be ordered before its confirming-round write`,
    )
    // …and the demotion must be SCOPED to the path that fixes. §3's body is conditional ("If the
    // outside voice surfaces must-fix"), so an unconditional "first action of this section" would
    // demote on the common no-findings path and leave `capped` with no confirming round left to
    // lift it — forcing a sound run to BLOCKED, which is this ticket's own headline defect.
    assert.match(
      step6b3,
      /only\s+when\s+§3's\s+fix\s+leg\s+actually\s+runs/i,
      `${dir}: §3's demotion must apply only when its fix leg runs, not on the no-findings path`,
    )
    assert.match(
      step6b3,
      /surfaced\s+none[\s\S]{0,200}stands\s*\n?\s*untouched/i,
      `${dir}: §3 must say the loop's clean STANDS when the outside voice surfaced nothing`,
    )

    // (d) THE WORKED CASE the observed run most plausibly stumbled on. "Do not copy the Step 6c
    // sentinel" says what NOT to write and never what to write instead, which is exactly the state
    // a subagent is in when it holds an advisory `bs-review capped:` line and a clean blocking path.
    assert.match(
      contract,
      /Step\s+6\/6b\s+clean\s*\+\s*Step\s+6c\s+capped\s*⇒\s*write\s+`sentinel\s+clean`/i,
      `${dir}: the reference must state positively what a clean blocking path with a capped Step 6c writes`,
    )

    // (e) Step 6c is exempt from the demotion §3 must do, and the asymmetry must be ARGUED where a
    // reader meets it. Silence here reads as an oversight, and the next editor cannot tell whether
    // 6c was reasoned about or missed — the same "says what not to write, never why" gap this
    // ticket closed elsewhere.
    assert.match(
      contract,
      /\*\*Step\s+6c\*\*[\s\S]{0,220}not\*{0,2}\s+demoted[\s\S]{0,240}(reasoned|asymmetry)/i,
      `${dir}: the Step 6c bullet must say it is not demoted either, and why`,
    )
  }
})

test('BOS-964: a provisional verdict that survived is BLOCKED, never PARTIAL', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)

    // §PARTIAL's T1 already refuses a self-generated `capped`; the seed is named explicitly so the
    // exclusion cannot be reasoned around on the live route.
    const partial = region(
      reviewStack,
      '### PARTIAL-route publication',
      '### BLOCKED-route publication',
    )
    assert.match(
      partial,
      /provisional\s+seed[\s\S]{0,400}never\s+eligible\s+for\s+`PARTIAL`/i,
      `${dir}: §PARTIAL-route publication must exclude a provisional-survived verdict by name`,
    )

    // §BLOCKED gains a THIRD bullet, ordered after the two dispatch-failure sub-cases, and — like
    // both of them — naming a value for BOTH mandatory sections. An omitted `## Cross-model review`
    // reads as "the outside voice passed clean".
    assert.ok(
      precedes(reviewStack, '**Missing/stale sentinel**', '**Present but unmatchable sentinel**') &&
        precedes(
          reviewStack,
          '**Present but unmatchable sentinel**',
          '**Provisional sentinel that survived**',
        ),
      `${dir}: the provisional bullet must come after both dispatch-failure sub-cases`,
    )
    const provisionalBullet = region(
      reviewStack,
      '- **Provisional sentinel that survived**',
      '`none: review stack did not run (<reason>)` belongs to neither bullet',
    )
    assert.match(
      provisionalBullet,
      /`## Review\s+coverage`\s*=\s*\n?\s*`none: review\s+coverage\s+unknown \(review\s+stack\s+entered; provisional\s+verdict\s+never\s+upgraded\s+—\s+<reason>\)`/,
      `${dir}: the provisional route must publish the unknown-coverage token with its cause named`,
    )
    assert.match(
      provisionalBullet,
      /`## Cross-model\s+review`\s*=\s*`error: <reason>`/,
      `${dir}: the provisional route must name a cross-model value too — an absent section reads as "passed clean"`,
    )
    // The discriminator, restated where the decision is taken. A `capped 1` a reviewer earned is
    // byte-identical in kind and round count, so only the payload can tell them apart.
    assert.match(
      provisionalBullet,
      /payload\s+marker\s+alone[\s\S]{0,200}never\s+from\s+the\s+kind\s+string,\s+the\s+round\s+count,\s+or\s+the\s+returned\s+prose/i,
      `${dir}: the provisional bullet must forbid inferring its cause from kind, round count, or prose`,
    )
    // The two existing sub-cases keep their own tokens — this route adds a third, it does not
    // relocate either of theirs.
    const missingBullet = region(
      reviewStack,
      '- **Missing/stale sentinel**',
      '- **Present but unmatchable sentinel**',
    )
    const coverage = region(
      reviewStack,
      '**Record the tier (always).**',
      '#### Bounded repair pass (conditional)',
    )
    assert.match(
      coverage,
      /A\s+verdict\s+without\s+a\s+token\s+is\s+not\s+`full`/i,
      `${dir}: a clean verdict whose dispatch returned no coverage token must not be published as full`,
    )
    // …and it must stay a PUBLICATION rule. Routing on the presence of returned prose is the exact
    // anti-pattern the run-file sentinel exists to refuse; a fix for one gap must not reopen it.
    assert.match(
      coverage,
      /\*\*not\*\*\s+a\s+routing\s+rule[\s\S]{0,200}routing\s+reads\s+the\s+run\s+file\s+and\s+nothing\s+else/i,
      `${dir}: the no-token rule must be scoped to publication and forbid becoming a routing rule`,
    )
    assert.match(missingBullet, /`none: review\s+coverage\s+unknown \(<reason>\)`/)
    assert.doesNotMatch(
      missingBullet,
      /provisional\s+verdict\s+never\s+upgraded/i,
      `${dir}: the missing/stale bullet must keep its own token, not borrow the provisional route's`,
    )
  }
})

test('BOS-964: an allowance that declines work must disclose both numbers', () => {
  for (const dir of BUILD_MIRRORS) {
    const reviewStack = reviewStackFor(dir)
    const tierSelection = region(
      reviewStack,
      '## Step 6 entry — review tier selection',
      '### Degraded tier (minimal)',
    )

    // The secondary defect in the observed run was NOT arithmetic — 900s − ~488s ≈ 412s is the
    // documented Step 6c bound working. What was missing is disclosure: nothing published that
    // three must-fix findings went unfixed because of a 15-minute advisory box while 215 minutes
    // remained on the run. Two numbers, never one.
    assert.match(
      tierSelection,
      /Allowance-disclosure\s+rule/i,
      `${dir}: the tier ladder must carry a general allowance-disclosure rule`,
    )
    assert.match(
      tierSelection,
      /\*\*two\s+separate\s+numbers\*\*[\s\S]{0,200}\*\*allowance\*\*[\s\S]{0,120}\*\*remaining\s+Preflight\s+clock\*\*/i,
      `${dir}: the rule must require the allowance AND the remaining Preflight clock as two separate numbers`,
    )
    assert.match(
      tierSelection,
      /never\s+phrase\s+an\s+inner\s+box\s+as\s+the\s+run\s+being\s+out\s+of\s+time/i,
      `${dir}: the rule must forbid reporting an inner allowance as the run running out of time`,
    )
    assert.match(
      tierSelection,
      /enclosing-ceiling[\s\S]{0,200}clamp\s+costs\s+the\s+diagnostic/i,
      `${dir}: the rule must cite the enclosing-ceiling pattern by name so the reasoning travels`,
    )

    // Step 6c is where it bites at the default, so its capped case carries the SUFFIX — a suffix,
    // never a new head form, so Step 7's resident enumeration and its pin are untouched.
    const step6c = region(reviewStack, '## Step 6c: Consolidated multi-lens review')
    assert.match(
      step6c,
      /ran\s+and\s+returned\s+a\s+capped\s+report\*{0,2}\s+is\s+not\s+one[\s\S]{0,300}leave\s+the\s+coverage\s+token\s+as\s+`?full`?/i,
      `${dir}: the pre-existing capped-but-completed pin must still match — the disclosure suffix must not displace it`,
    )
    assert.match(
      step6c,
      /`full\s+\(advisory:\s+boss-review\s+capped\s+—\s+<N>\s+open\s+must-fix\s+reported;\s+its\s+<M>-minute\s+allowance\s+funds\s+0\s+fix\s+rounds,\s+<R>\s+minutes\s+remained\s+on\s+the\s+run\)`/,
      `${dir}: a capped Step 6c must publish the disclosure suffix on its \`full\` token`,
    )
    assert.match(
      step6c,
      /a\s+(\*\*)?suffix(\*\*)?,\s+never\s+a\s+new\s+head\s+form/i,
      `${dir}: the disclosure must be a suffix, so Step 7's closed token enumeration stays unchanged`,
    )
    // "It is a suffix" says why SKILL.md was not edited; it does not tell the orchestrator that
    // appending to `full` is legal against a `|`-separated list that reads as closed. Unsaid, the
    // likeliest improvisation is normalising back to a bare `full`, which deletes the whole
    // disclosure — the same "says what not to write, never what to write" gap this ticket closed
    // one section earlier.
    assert.match(
      step6c,
      /enumerates\s+\*\*head\*\*\s+forms[\s\S]{0,220}copy\s+the\s+suffix\s+through\s+verbatim/i,
      `${dir}: the suffix rule must say the Step 7 enumeration lists head forms and the suffix is copied verbatim`,
    )
    // …and the 15-vs-20 mismatch is recorded as the designed bound, with the observed reading named
    // so the next run recognises it instead of re-filing it as a budget bug.
    assert.match(
      step6c,
      /412s[\s\S]{0,120}1200s[\s\S]{0,200}this\s+bound\s+working\s+as\s+designed/i,
      `${dir}: Step 6c must name the observed 412s/1200s reading as the bound working, not a mis-derived deadline`,
    )
    assert.match(
      step6c,
      /do\s+not\s+re-file\s+it\s+as\s+a\s+budget\s+bug\s+or\s+re-price\s+the\s*\n?\s*formula/i,
      `${dir}: re-pricing the tier formula must be named as out of scope for this reading`,
    )
  }
})
